// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"double-integral":{"id":"double-integral","prerequisites":["riemann-sum-intuition","definite-signed-area","two-variable-functions"],"next":["iterated-integral"],"related":["nonrectangular-regions","polar-double-integral","average-value","surface-area"],"objectives":["說出 $\\iint_R f(x,y)\\,dA$ 是「切小格、高度 $\\times$ 面積、加起來、取極限」，$f\\ge 0$ 時是曲面下方的體積。","用中點法估計矩形上的二重積分。","用面積、常數倍、對稱性，不算累次積分就直接得到某些二重積分。"],"concept":[{"heading":"① 從面積到體積","body":["一維時，$\\int_a^b f(x)\\,dx$ 是把 $[a,b]$ 切細，每段算 $f(x_i)\\Delta x$，再加起來取極限。","現在 $f(x,y)$ 有兩個輸入，$z=f(x,y)$ 是一張曲面。問題換成：曲面跟它底下的區域 $R$ 之間，夾著多少體積？"]},{"heading":"② 切小格、立柱子、加起來","body":["先看矩形 $R=[a,b]\\times[c,d]$。$x$ 方向切 $m$ 段、$y$ 方向切 $n$ 段，得到 $mn$ 個小矩形，每個面積 $\\Delta A=\\Delta x\\,\\Delta y$。","每一格挑一個點 $(x_{ij}^*,y_{ij}^*)$，立一根高 $f(x_{ij}^*,y_{ij}^*)$ 的柱子，體積是 $f\\cdot\\Delta A$。全部加起來是一個 Riemann 和。格子越切越細，這個和的極限就叫二重積分。","$dA$ 讀成「一小塊面積」。下一課〈累次積分〉會把它拆成 $dx\\,dy$ 來算。"],"tex":["\\iint_R f(x,y)\\,dA=\\lim_{m,n\\to\\infty}\\sum_{i=1}^{m}\\sum_{j=1}^{n} f(x_{ij}^*,y_{ij}^*)\\,\\Delta A"]},{"heading":"③ 有號體積","body":["$f\\ge 0$ 時，二重積分就是曲面下、$R$ 上的體積。$f$ 有負值時，$R$ 下方那部分算負的，跟〈定積分與有號面積〉同一個道理。"]},{"heading":"④ 不用算就知道的幾件事","body":["$\\iint_R 1\\,dA={}$ $R$ 的面積（高度 $1$ 的柱體，體積數值等於底面積）；$\\iint_R c\\,dA=c\\times{}$ 面積。","可以拆加法、提常數；$R$ 切成兩塊，積分也拆成兩塊相加。","對稱：$R$ 對 $y$ 軸對稱，而且 $f(-x,y)=-f(x,y)$，左右兩半剛好抵消，積分是 $0$。","$f$ 在 $R$ 上的平均值 $=(1/$面積$)\\iint_R f\\,dA$，跟〈平均值〉同一個想法。"]},{"heading":"⑤ 什麼時候這個極限存在（給想知道的人）","body":["$f$ 在矩形 $R$ 上連續，極限一定存在，而且跟每格怎麼挑點無關。$f$ 有界、不連續的點只落在有限條光滑曲線上，也還是存在。","非矩形的區域 $D$：把 $f$ 在 $D$ 外面補成 $0$，放進一個包住 $D$ 的大矩形裡，就回到矩形的定義。實際怎麼算見〈非矩形區域〉。"],"collapsible":true}],"workedExamples":[{"title":"中點法估計","prompt":"用 $2\\times2$ 的格子、取每格中點，估計 $\\iint_R(x^2+y)\\,dA$，$R=[0,2]\\times[0,2]$。","steps":["每格是 $1\\times1$，$\\Delta A=1$。四個中點：$(0.5,0.5)$、$(0.5,1.5)$、$(1.5,0.5)$、$(1.5,1.5)$。","高度依序是 $0.25+0.5=0.75$、$0.25+1.5=1.75$、$2.25+0.5=2.75$、$2.25+1.5=3.75$。","估計值 $=(0.75+1.75+2.75+3.75)\\times1=9$。","精確值是 $\\frac{28}{3}\\approx9.33$（下一課會算）。格子加密，估計會更準。"],"answer":"估計 $9$（精確值 $\\frac{28}{3}$）"},{"title":"看出它是一個認得的立體","prompt":"$\\iint_D\\sqrt{4-x^2-y^2}\\,dA$，$D$：$x^2+y^2\\le 4$。","steps":["$z=\\sqrt{4-x^2-y^2}$ 平方移項是 $x^2+y^2+z^2=4$，而且 $z\\ge 0$：這是半徑 $2$ 的上半球面。","$D$ 正好是它在 $xy$ 平面上的影子，所以積分就是上半球的體積。","球體積 $\\frac{4}{3}\\pi\\cdot2^3=\\frac{32\\pi}{3}$，一半是 $\\frac{16\\pi}{3}$。"],"answer":"$\\frac{16\\pi}{3}$","note":"claim 用的是〈極座標二重積分〉的算法，這裡只拿來核對。"},{"title":"常數加奇函數","prompt":"$\\iint_R(5+x^3\\cos y)\\,dA$，$R=[-1,1]\\times[0,\\pi]$。","steps":["拆成兩項：$\\iint_R 5\\,dA+\\iint_R x^3\\cos y\\,dA$。","第一項：$R$ 的面積是 $2\\times\\pi=2\\pi$，乘 $5$ 得 $10\\pi$。","第二項：$R$ 對 $y$ 軸對稱，$(-x)^3\\cos y=-x^3\\cos y$，左右抵消，是 $0$。","合計 $10\\pi$。"],"answer":"$10\\pi$"}],"pitfalls":["把二重積分一律說成「體積」：$f$ 有負值時是有號體積。","把 $\\iint_R f\\,dA$ 跟「曲面的面積」搞混：後者是〈曲面面積〉，要另外算。","中點法只加了高度，忘了乘每格面積 $\\Delta A$。","用奇函數對稱前，沒先確認區域也對稱。"],"checks":[{"ask":"$R=[1,4]\\times[0,2]$，$\\iint_R 1\\,dA$ 是？","options":[{"label":"$6$","correct":true},{"label":"$8$","why":"$x$ 方向是從 $1$ 到 $4$，長度 $3$，不是 $4$。"},{"label":"$3$","why":"那只是 $x$ 方向的長度，還要乘 $y$ 方向的長度 $2$。"}]},{"ask":"$f\\ge 0$ 時，$\\iint_R f(x,y)\\,dA$ 在幾何上是？","options":[{"label":"曲面 $z=f(x,y)$ 下方、$R$ 上方的立體體積","correct":true},{"label":"曲面 $z=f(x,y)$ 在 $R$ 上那一片的面積","why":"$dA$ 是底面的小塊面積，柱子高 $f$，乘起來是體積；曲面本身的面積是另一個積分。"},{"label":"$R$ 的面積","why":"那是 $f=1$ 的特例。一般的 $f$ 會把每一格乘上不同的高度。"}]},{"ask":"$\\iint_R x\\,e^y\\,dA$，$R=[-2,2]\\times[0,1]$，是？","options":[{"label":"$0$","correct":true},{"label":"$4(e-1)$","why":"這是把 $x$ 當成 $|x|$ 算出來的。$R$ 左右對稱、$x\\,e^y$ 對 $x$ 是奇函數，兩半抵消。"},{"label":"$e-1$","why":"只算了 $y$ 那一半。$x$ 的部分 $\\int_{-2}^{2}x\\,dx=0$，乘起來是 $0$。"}]},{"ask":"用 $2\\times2$ 格子、取中點估計 $\\iint(x^2+y^2)\\,dA$，$R=[0,2]\\times[0,2]$。四個中點的高度是 $0.5$、$2.5$、$2.5$、$4.5$，估計值是？","options":[{"label":"$10$","correct":true},{"label":"$2.5$","why":"那是四根柱子的平均高度。每格面積是 $1$，要把四個高度乘面積後加起來。"},{"label":"$40$","why":"每格的 $\\Delta A$ 是 $1\\times1=1$，不是整個 $R$ 的面積 $4$。"}]}],"practice":[{"id":"int-022","core":true},{"id":"int-034","core":true,"note":"看出它是四分之一圓的面積，不必真的積。"},{"id":"int-021","note":"$x$ 與 $y$ 地位對稱：$\\iint x\\,dA=\\iint y\\,dA$。"}]},"iterated-integral":{"id":"iterated-integral","prerequisites":["double-integral","partial-derivatives","ftc-part2"],"next":["nonrectangular-regions"],"related":["volume-disk"],"objectives":["把矩形上的二重積分寫成累次積分，由內往外算；算內層時把外層變數當常數。","知道 Fubini 定理：矩形上的連續函數，兩種積分次序結果相同，可以挑好算的那個。","$f(x,y)=g(x)h(y)$ 在矩形上時，拆成兩個一維積分相乘。"],"concept":[{"heading":"① 切片：先算截面，再把截面積起來","body":["$R=[a,b]\\times[c,d]$，$f\\ge 0$。拿一片垂直於 $x$ 軸的平面，在某個固定的 $x$ 切下去，切口是一塊平面圖形，它的面積是 $A(x)=\\int_c^d f(x,y)\\,dy$。","在〈圓盤法〉裡我們已經知道：截面面積沿著軸積起來就是體積。所以體積 $=\\int_a^b A(x)\\,dx$。"]},{"heading":"② 記號：由內往外","body":["上面兩步寫在一起就是累次積分。裡面那一層的 $dy$ 配裡面的上下限 $c$、$d$；外面那一層的 $dx$ 配 $a$、$b$。先算裡面，算完只剩 $x$，再算外面。"],"tex":["\\int_a^b\\!\\left[\\int_c^d f(x,y)\\,dy\\right]dx"]},{"heading":"③ 算內層時，$x$ 是常數","body":["對 $y$ 積分時，$x$ 就像一個固定的數，跟〈偏導數〉把其他變數當常數一樣。例：$\\int_0^2 xy\\,dy=x\\cdot\\left[\\frac{y^2}{2}\\right]_0^2=2x$。","內層代完上下限之後，$y$ 必須完全消失；如果還看到 $y$，表示上下限沒代。"]},{"heading":"④ Fubini：次序可以換","body":["$f$ 在矩形 $R$ 上連續時，先 $dy$ 後 $dx$、先 $dx$ 後 $dy$ 兩種累次積分相等，都等於 $\\iint_R f\\,dA$。所以遇到一個次序很難積，可以換另一個次序試試。"],"tex":["\\iint_R f\\,dA=\\int_a^b\\!\\int_c^d f\\,dy\\,dx=\\int_c^d\\!\\int_a^b f\\,dx\\,dy"]},{"heading":"⑤ 可分離的被積函數","body":["$R$ 是矩形、而且 $f(x,y)=g(x)h(y)$ 時，內層 $\\int_c^d g(x)h(y)\\,dy=g(x)\\int_c^d h(y)\\,dy$，後面那個積分是一個數，可以提出去。結果：$\\iint_R g(x)h(y)\\,dA=\\left(\\int_a^b g\\,dx\\right)\\left(\\int_c^d h\\,dy\\right)$。","只在矩形上成立。區域不是矩形時，內層上下限會跟著 $x$ 變，拆不開。"]},{"heading":"⑥ Fubini 的條件為什麼要寫（給想知道的人）","body":["條件不成立時，兩種次序真的可以不一樣。$f(x,y)=\\frac{x^2-y^2}{(x^2+y^2)^2}$ 在 $[0,1]^2$ 上：對 $y$ 的反導函數是 $\\frac{y}{x^2+y^2}$，所以先 $dy$ 再 $dx$ 得 $\\int_0^1\\frac{1}{1+x^2}\\,dx=\\frac{\\pi}{4}$；先 $dx$ 再 $dy$ 用同樣方法得 $-\\frac{\\pi}{4}$。","問題出在原點附近 $f$ 無界，$|f|$ 的積分是發散的。$f$ 連續（或有界、不連續點只在有限條光滑曲線上）就不會發生這種事。"],"collapsible":true}],"workedExamples":[{"title":"兩種次序都算一次","prompt":"$\\iint_R(x+2y)\\,dA$，$R=[0,2]\\times[1,3]$。","steps":["先 $dy$：內層 $\\int_1^3(x+2y)\\,dy$，$x$ 當常數。反導函數 $xy+y^2$，代 $3$ 減代 $1$：$(3x+9)-(x+1)=2x+8$。","外層 $\\int_0^2(2x+8)\\,dx=\\left[x^2+8x\\right]_0^2=4+16=20$。","換成先 $dx$：內層 $\\int_0^2(x+2y)\\,dx=\\left[\\frac{x^2}{2}+2xy\\right]_0^2=2+4y$。外層 $\\int_1^3(2+4y)\\,dy=\\left[2y+2y^2\\right]_1^3=24-4=20$。","兩個次序一樣，符合 Fubini。"],"answer":"$20$"},{"title":"挑好算的次序","prompt":"$\\iint_R y\\,e^{xy}\\,dA$，$R=[0,1]\\times[0,1]$。","steps":["先 $dy$ 的話，內層 $\\int y\\,e^{xy}\\,dy$ 要分部積分，而且之後還要對 $x$ 積一個不好看的式子。","改成先 $dx$：$y$ 是常數，$\\int_0^1 y\\,e^{xy}\\,dx=\\left[e^{xy}\\right]_{x=0}^{x=1}=e^y-1$（$e^{xy}$ 對 $x$ 微分正好是 $y\\,e^{xy}$）。","外層 $\\int_0^1(e^y-1)\\,dy=(e-1)-1=e-2$。"],"answer":"$e-2$"},{"title":"可分離：拆成兩個一維積分","prompt":"$\\iint_R y^2\\cos x\\,dA$，$R=\\left[0,\\frac{\\pi}{2}\\right]\\times[0,3]$。","steps":["$R$ 是矩形，$y^2\\cos x=(\\cos x)(y^2)$，可分離。","$\\int_0^{\\pi/2}\\cos x\\,dx=1$，$\\int_0^3 y^2\\,dy=9$。","相乘得 $9$。"],"answer":"$9$"}],"pitfalls":["上下限配錯層：內層的 $dy$ 要配內層的上下限。","內層算完還留著 $y$，表示上下限沒代進去。","停在內層就交答案：結果還是 $x$ 的函數，要再積外層。","在非矩形區域上也想拆成兩個積分相乘。"],"checks":[{"ask":"$\\int_0^1\\int_0^2(x+y)\\,dy\\,dx$ 的內層 $\\int_0^2(x+y)\\,dy$ 是？","options":[{"label":"$2x+2$","correct":true},{"label":"$x+2$","why":"$x$ 對 $y$ 積分是 $xy$，代 $0$ 到 $2$ 得 $2x$，不是 $x$。常數也要乘上 $y$ 方向的長度。"},{"label":"$2x+y$","why":"代完上下限之後 $y$ 應該消失：$\\int_0^2 y\\,dy=2$。"}]},{"ask":"承上題，整個累次積分的值是？","options":[{"label":"$3$","correct":true},{"label":"$2x+2$","why":"那是內層的結果，還要對 $x$ 從 $0$ 積到 $1$。"},{"label":"$1$","why":"$\\int_0^1 2x\\,dx=1$ 只是其中一項，$\\int_0^1 2\\,dx=2$ 也要加上去。"}]},{"ask":"$R$ 是矩形、$f$ 在 $R$ 上連續。先 $dy$ 後 $dx$ 與先 $dx$ 後 $dy$ 兩個累次積分：","options":[{"label":"一定相等","correct":true},{"label":"一般不相等，要看 $f$","why":"Fubini 定理保證矩形上的連續函數兩種次序相等；不相等的例子要 $f$ 無界之類的壞情況。"},{"label":"只有 $f$ 可分離時才相等","why":"可分離是「拆成兩個積分相乘」的條件，跟次序能不能換無關。"}]},{"ask":"$\\iint_R x^2y\\,dA$，$R=[0,1]\\times[0,2]$，是？","options":[{"label":"$\\frac{2}{3}$","correct":true},{"label":"$\\frac{1}{6}$","why":"$y$ 的範圍是 $0$ 到 $2$：$\\int_0^2 y\\,dy=2$，不是 $\\frac{1}{2}$。"},{"label":"$\\frac{7}{3}$","why":"可分離是相乘不是相加：$\\frac{1}{3}\\times2$，不是 $\\frac{1}{3}+2$。"}]}],"practice":[{"id":"int-021","core":true},{"id":"lec-19-m1","core":true},{"id":"int-026","core":true},{"id":"rel-adv-014","core":true},{"id":"burst-boss3-int-002","challenge":true,"note":"挑戰：拆開之後是兩個 $\\int_0^1 x^a(\\ln x)^n\\,dx$ 型的瑕積分，各自重複分部積分（等於 $\\frac{(-1)^n n!}{(a+1)^{n+1}}$）。"}]},"nonrectangular-regions":{"id":"nonrectangular-regions","prerequisites":["iterated-integral","area-between-curves"],"next":["change-order"],"related":["area-dy","double-integral"],"objectives":["畫出區域，判斷用鉛直線掃（先 $dy$）還是水平線掃（先 $dx$）比較順。","寫出內層上下限是曲線、外層上下限是常數的累次積分。","知道一種寫法要切成好幾塊時，換另一種寫法可能只要一塊。"],"concept":[{"heading":"① 矩形不夠用","body":["實際的區域常是兩條曲線夾出來的，例如 $y=x^2$ 與 $y=x$ 之間。這時不能再寫 $\\int_a^b\\int_c^d$，因為 $y$ 的範圍會隨 $x$ 改變。","想法不變：還是由內往外的累次積分。差別只在內層的上下限不再是固定的數，而是曲線；整個課的功夫，都花在把這兩條曲線找對。"]},{"heading":"② 鉛直線掃描（先 $dy$ 後 $dx$）","body":["固定一個 $x$，畫一條鉛直線穿過區域。它從下界曲線 $y=g_1(x)$ 進入、從上界曲線 $y=g_2(x)$ 離開。這兩條曲線就是內層的上下限。再看 $x$ 從哪裡掃到哪裡，那是外層的上下限 $a$、$b$。","例：$y=x^2$ 與 $y=x$ 之間。$x=0.5$ 的鉛直線從 $y=0.25$ 進、從 $y=0.5$ 出；一般的 $x$ 從 $y=x^2$ 進、從 $y=x$ 出，而 $x$ 從 $0$ 掃到 $1$。","這種區域 $D=\\{a\\le x\\le b,\\ g_1(x)\\le y\\le g_2(x)\\}$ 有時叫做第一型區域。"],"tex":["\\iint_D f\\,dA=\\int_a^b\\!\\int_{g_1(x)}^{g_2(x)} f(x,y)\\,dy\\,dx"]},{"heading":"③ 水平線掃描（先 $dx$ 後 $dy$）","body":["反過來，固定 $y$ 畫水平線，從左界 $x=h_1(y)$ 進、右界 $x=h_2(y)$ 出，$y$ 從 $c$ 掃到 $d$。這是第二型區域。左右界要寫成「$x={}$ $y$ 的函數」，常常要先把曲線方程式解成 $x$。"],"tex":["\\iint_D f\\,dA=\\int_c^d\\!\\int_{h_1(y)}^{h_2(y)} f(x,y)\\,dx\\,dy"]},{"heading":"④ 四個步驟","body":["1. 畫圖，找出邊界曲線的交點。","2. 選掃描方向：掃過去的每一條線，都要從「同一條」曲線進、從「同一條」曲線出。中途換曲線，就要切塊，或改用另一個方向。","3. 寫限：內層是曲線（可以含外層變數），外層一定是常數。","4. 由內往外積。最後的答案是一個數，不能含 $x$ 或 $y$。"]},{"heading":"⑤ 定義上發生了什麼（給想知道的人）","body":["把 $f$ 在 $D$ 外面補成 $0$，得到一個定義在大矩形 $R$ 上的函數 $F$，定義 $\\iint_D f\\,dA=\\iint_R F\\,dA$。$F$ 在 $D$ 的邊界上可能跳躍，但邊界是有限條連續曲線時，這個積分仍然存在，而且 Fubini 照樣能用：對固定的 $x$，$F$ 只在 $g_1(x)$ 到 $g_2(x)$ 之間不是 $0$，內層積分自然變成 $\\int_{g_1(x)}^{g_2(x)}$。"],"collapsible":true}],"workedExamples":[{"title":"兩條曲線之間（鉛直線）","prompt":"$\\iint_D xy\\,dA$，$D$ 是 $y=x^2$ 與 $y=x$ 圍成的區域。","steps":["交點：$x^2=x$，得 $x=0$、$x=1$。在 $0<x<1$ 時 $x^2<x$，所以 $y=x$ 在上、$y=x^2$ 在下。","鉛直線從 $y=x^2$ 進、從 $y=x$ 出：$\\int_0^1\\int_{x^2}^{x}xy\\,dy\\,dx$。","內層：$x\\cdot\\left[\\frac{y^2}{2}\\right]_{x^2}^{x}=\\frac{x(x^2-x^4)}{2}=\\frac{x^3-x^5}{2}$。","外層：$\\frac{1}{2}\\left(\\frac{1}{4}-\\frac{1}{6}\\right)=\\frac{1}{2}\\left(\\frac{1}{12}\\right)=\\frac{1}{24}$。"],"answer":"$\\frac{1}{24}$"},{"title":"鉛直線要切塊，水平線一塊就好","prompt":"$\\iint_D y\\,dA$，$D$ 是 $x=y^2$ 與 $x=y+2$ 圍成的區域。","steps":["交點：$y^2=y+2$，即 $(y-2)(y+1)=0$，$y=-1$ 或 $2$，對應點 $(1,-1)$、$(4,2)$。","用鉛直線：$x$ 在 $0$ 到 $1$ 時，下界是拋物線的下半支 $y=-\\sqrt x$；$x$ 在 $1$ 到 $4$ 時，下界換成直線 $y=x-2$。下界中途換曲線，要切兩塊。","改用水平線：每條水平線都從拋物線 $x=y^2$ 進、從直線 $x=y+2$ 出，$y$ 從 $-1$ 到 $2$。一塊就好：$\\int_{-1}^{2}\\int_{y^2}^{y+2}y\\,dx\\,dy$。","內層：$y(y+2-y^2)=y^2+2y-y^3$。","外層：$\\left[\\frac{y^3}{3}+y^2-\\frac{y^4}{4}\\right]_{-1}^{2}=\\left(\\frac{8}{3}+4-4\\right)-\\left(-\\frac{1}{3}+1-\\frac{1}{4}\\right)=\\frac{8}{3}-\\frac{5}{12}=\\frac{9}{4}$。"],"answer":"$\\frac{9}{4}$"},{"title":"同一個三角形，兩種寫法","prompt":"$\\iint_T y\\,dA$，$T$ 是頂點 $(0,0)$、$(2,0)$、$(2,1)$ 的三角形。","steps":["斜邊過 $(0,0)$ 與 $(2,1)$：$y=\\frac{x}{2}$，也就是 $x=2y$。","鉛直線：$x$ 從 $0$ 到 $2$，$y$ 從 $0$ 到 $\\frac{x}{2}$。$\\int_0^2\\int_0^{x/2}y\\,dy\\,dx=\\int_0^2\\frac{x^2}{8}\\,dx=\\frac{8}{24}=\\frac{1}{3}$。","水平線：$y$ 從 $0$ 到 $1$，$x$ 從斜邊 $2y$ 到右邊 $x=2$。$\\int_0^1\\int_{2y}^{2}y\\,dx\\,dy=\\int_0^1 y(2-2y)\\,dy=1-\\frac{2}{3}=\\frac{1}{3}$。"],"answer":"$\\frac{1}{3}$"}],"pitfalls":["沒畫圖就寫上下限，上下界放反（$0<x<1$ 時 $x^2$ 比 $x$ 小）。","外層上下限寫成含變數的式子，算完答案還留著 $x$ 或 $y$。","先 $dx$ 時忘了把邊界曲線解成 $x=h(y)$。","掃描線中途換了邊界曲線卻沒切塊。"],"checks":[{"ask":"$D$ 由 $y=x^2$ 與 $y=x$ 圍成。用鉛直線掃，內層 $y$ 的範圍是？","options":[{"label":"$x^2\\le y\\le x$","correct":true},{"label":"$x\\le y\\le x^2$","why":"$0<x<1$ 時 $x^2$ 比 $x$ 小，例如 $x=0.5$ 時 $x^2=0.25$。下界是 $x^2$。"},{"label":"$0\\le y\\le 1$","why":"那是整塊區域 $y$ 的總範圍。內層要寫「這一條鉛直線」上的範圍，會隨 $x$ 改變。"}]},{"ask":"下面哪一個寫法一定有問題？","options":[{"label":"$\\int_0^x\\int_0^1 f\\,dy\\,dx$","correct":true},{"label":"$\\int_0^1\\int_x^1 f\\,dy\\,dx$","why":"這是合法的：外層是常數 $0$ 到 $1$，內層隨 $x$ 變。"},{"label":"$\\int_0^1\\int_{y^2}^{y}f\\,dx\\,dy$","why":"這是合法的水平線寫法：$0\\le y\\le 1$ 時 $y^2\\le y$。"}]},{"ask":"$\\int_0^1\\int_0^x 2y\\,dy\\,dx$ 是？","options":[{"label":"$\\frac{1}{3}$","correct":true},{"label":"$1$","why":"那是把內層上限當成 $1$。內層是 $\\int_0^x 2y\\,dy=x^2$，再積得 $\\frac{1}{3}$。"},{"label":"$x^2$","why":"那是內層的結果，還要對 $x$ 從 $0$ 積到 $1$。"}]},{"ask":"$\\int_0^1\\int_0^x 1\\,dy\\,dx$ 代表哪塊區域的面積？","options":[{"label":"頂點 $(0,0)$、$(1,0)$、$(1,1)$ 的三角形","correct":true},{"label":"頂點 $(0,0)$、$(0,1)$、$(1,1)$ 的三角形","why":"那塊是 $y$ 從 $x$ 到 $1$，在 $y=x$ 上方。這裡 $y$ 從 $0$ 到 $x$，在 $y=x$ 下方。"},{"label":"單位正方形","why":"內層 $y$ 只到 $x$，不是到 $1$，所以只有正方形的一半。"}]}],"practice":[{"id":"int-023","core":true},{"id":"int-024","core":true},{"id":"exam-multi-006","core":true},{"id":"int-036","core":true},{"id":"depth-int-022","core":true},{"id":"int-034","note":"先畫出區域：它是四分之一圓。"},{"id":"rel-hard-mv-001"}]},"change-order":{"id":"change-order","prerequisites":["nonrectangular-regions"],"next":["polar-double-integral"],"related":["iterated-integral","u-sub-definite"],"objectives":["從一個累次積分的上下限還原出區域 $D$，再用另一個方向重新描述同一塊 $D$。","看到內層沒有初等反導函數（像 $e^{y^2}$、$\\sin(y^2)$）時，想到交換次序。","處理換次序後要切塊、或兩塊合成一塊的情形。"],"concept":[{"heading":"① 為什麼要換","body":["$\\int_0^1\\int_x^1 e^{y^2}\\,dy\\,dx$：內層要對 $y$ 積 $e^{y^2}$，可是 $e^{y^2}$ 沒有初等反導函數，卡住了。","但區域沒變，只是換個方向切。〈累次積分〉的 Fubini 說，連續函數在同一塊區域上換次序，值不變。換完之後，常常會多出一個剛好能配合換元的因子。"]},{"heading":"② 不是把上下限對調","body":["最常見的錯：把 $\\int_0^1\\int_x^1\\dots\\,dy\\,dx$ 直接改寫成 $\\int_x^1\\int_0^1\\dots\\,dx\\,dy$。外層出現了 $x$，答案會帶著變數，完全不對。","正確做法一定要經過「區域」這一步：上下限 $\\to$ 畫出 $D$ $\\to$ 用另一個方向描述 $D$ $\\to$ 新的上下限。"]},{"heading":"③ 三個步驟","body":["1. 讀上下限，寫成不等式：例如 $0\\le x\\le 1$、$x\\le y\\le 1$。","2. 畫出 $D$，標出頂點：這裡是 $(0,0)$、$(0,1)$、$(1,1)$ 的三角形，在 $y=x$ 上方。","3. 換成水平線：$y$ 從 $0$ 到 $1$；每條水平線從 $x=0$ 進、從 $x=y$ 出。所以 $0\\le y\\le 1$、$0\\le x\\le y$。","於是 $\\int_0^1\\int_x^1 e^{y^2}\\,dy\\,dx=\\int_0^1\\int_0^y e^{y^2}\\,dx\\,dy=\\int_0^1 y\\,e^{y^2}\\,dy$。多出來的 $y$ 正好讓 $u=y^2$ 能用。"]},{"heading":"④ 切塊與合併","body":["換方向之後，掃描線可能中途換邊界曲線，這時要切成兩塊；反過來，原本兩塊加起來的積分，換個方向也可能合成一塊。判斷方法一樣：看每條掃描線是不是從同一條曲線進、同一條曲線出。"]}],"workedExamples":[{"title":"內層卡住：$\\sin(y^2)$","prompt":"$\\int_0^1\\int_x^1\\sin(y^2)\\,dy\\,dx$","steps":["$\\sin(y^2)$ 對 $y$ 沒有初等反導函數，先 $dy$ 做不下去。","區域：$0\\le x\\le 1$、$x\\le y\\le 1$，是頂點 $(0,0)$、$(0,1)$、$(1,1)$ 的三角形。","改成水平線：$0\\le y\\le 1$、$0\\le x\\le y$。積分變成 $\\int_0^1\\int_0^y\\sin(y^2)\\,dx\\,dy$。","內層對 $x$ 積，$\\sin(y^2)$ 是常數：結果 $y\\sin(y^2)$。","外層令 $u=y^2$，$du=2y\\,dy$：$\\int_0^1 y\\sin(y^2)\\,dy=\\frac{1}{2}\\int_0^1\\sin u\\,du=\\frac{1-\\cos 1}{2}$。"],"answer":"$\\frac{1-\\cos 1}{2}$"},{"title":"根號在下限","prompt":"$\\int_0^1\\int_{\\sqrt y}^{1}\\sqrt{x^3+1}\\,dx\\,dy$","steps":["$\\sqrt{x^3+1}$ 對 $x$ 沒有初等反導函數。","區域：$0\\le y\\le 1$、$\\sqrt y\\le x\\le 1$。$x\\ge\\sqrt y$ 等價於 $y\\le x^2$（兩邊非負，可以平方），所以 $D$ 是 $y=x^2$ 下方、$0\\le x\\le 1$ 的部分。","改成鉛直線：$0\\le x\\le 1$、$0\\le y\\le x^2$。積分變成 $\\int_0^1 x^2\\sqrt{x^3+1}\\,dx$。","令 $u=x^3+1$，$du=3x^2\\,dx$：$\\frac{1}{3}\\int_1^2\\sqrt u\\,du=\\frac{2}{9}(2\\sqrt2-1)$。"],"answer":"$\\frac{2}{9}(2\\sqrt2-1)$"},{"title":"兩塊合成一塊","prompt":"把 $\\int_0^1\\int_0^y x\\,dx\\,dy+\\int_1^2\\int_0^{2-y}x\\,dx\\,dy$ 寫成一個累次積分並求值。","steps":["第一塊：$0\\le y\\le 1$、$0\\le x\\le y$。第二塊：$1\\le y\\le 2$、$0\\le x\\le 2-y$。","合起來是頂點 $(0,0)$、$(1,1)$、$(0,2)$ 的三角形：左邊是 $y$ 軸，右邊由 $y=x$ 與 $y=2-x$ 兩條線組成，所以水平線要切兩塊。","改成鉛直線：$x$ 從 $0$ 到 $1$，每條鉛直線從 $y=x$ 進、從 $y=2-x$ 出。一塊就好：$\\int_0^1\\int_x^{2-x}x\\,dy\\,dx$。","內層 $x(2-2x)$，外層 $\\int_0^1(2x-2x^2)\\,dx=1-\\frac{2}{3}=\\frac{1}{3}$。"],"answer":"$\\int_0^1\\int_x^{2-x}x\\,dy\\,dx=\\frac{1}{3}$"}],"pitfalls":["直接把內外層的上下限對調，沒有畫區域。","$\\sqrt y\\le x$ 換成 $y\\le x^2$ 時，沒有確認兩邊都非負。","換次序之後新的掃描線中途換邊界，卻沒切塊。","以為換次序會改變答案：換的只是切法，區域與值都不變。"],"checks":[{"ask":"$\\int_0^2\\int_0^x f\\,dy\\,dx$ 換成先 $dx$，正確的是？","options":[{"label":"$\\int_0^2\\int_y^2 f\\,dx\\,dy$","correct":true},{"label":"$\\int_0^x\\int_0^2 f\\,dx\\,dy$","why":"這是直接對調上下限，外層出現了變數。要先畫出區域：$(0,0)$、$(2,0)$、$(2,2)$ 的三角形。"},{"label":"$\\int_0^2\\int_0^y f\\,dx\\,dy$","why":"這是三角形的另一半（$y=x$ 上方）。原區域在 $y=x$ 下方，水平線從 $x=y$ 進、$x=2$ 出。"}]},{"ask":"$\\int_0^1\\int_x^1 e^{y^2}\\,dy\\,dx$ 為什麼要換次序？","options":[{"label":"$e^{y^2}$ 對 $y$ 沒有初等反導函數；換序後多一個 $y$，可以換元","correct":true},{"label":"換次序可以讓答案變小、比較好算","why":"Fubini 保證換次序值不變。換的理由是算得動，不是答案改變。"},{"label":"$e^{y^2}$ 在這個區域上不連續","why":"$e^{y^2}$ 處處連續。卡住的是反導函數寫不出來，不是連續性。"}]},{"ask":"$\\int_0^1\\int_y^1 f\\,dx\\,dy$ 的區域是？","options":[{"label":"頂點 $(0,0)$、$(1,0)$、$(1,1)$ 的三角形","correct":true},{"label":"頂點 $(0,0)$、$(0,1)$、$(1,1)$ 的三角形","why":"$x$ 從 $y$ 到 $1$ 表示點在 $y=x$ 的右邊（$x\\ge y$），也就是 $y=x$ 下方那一半。"},{"label":"單位正方形","why":"內層 $x$ 從 $y$ 開始，不是從 $0$ 開始，只佔正方形的一半。"}]},{"ask":"$\\int_0^{\\sqrt\\pi}\\int_x^{\\sqrt\\pi}\\sin(y^2)\\,dy\\,dx$ 是？","options":[{"label":"$1$","correct":true},{"label":"$0$","why":"換序後是 $\\int_0^{\\sqrt\\pi}y\\sin(y^2)\\,dy=\\frac{1-\\cos\\pi}{2}$，$\\cos\\pi=-1$，所以是 $\\frac{1+1}{2}$。"},{"label":"$2$","why":"$u=y^2$ 時 $du=2y\\,dy$，$y\\,dy=\\frac{du}{2}$，前面要乘 $\\frac{1}{2}$。"}]}],"practice":[{"id":"lec-19-m2","core":true},{"id":"lec-19-q1b","core":true},{"id":"lec-19-q1c","core":true},{"id":"int-031","note":"先畫區域，再試試另一個次序是不是一樣。"},{"id":"depth-int-022"}]},"polar-double-integral":{"id":"polar-double-integral","prerequisites":["polar-coordinates","polar-area","nonrectangular-regions"],"next":["jacobian-geometry"],"related":["gaussian-integral","change-of-variables"],"objectives":["說得出 $dA=r\\,dr\\,d\\theta$ 裡那個 $r$ 從哪裡來：外圈的小塊比內圈大。","把圓盤、圓環、扇形寫成 $r$、$\\theta$ 的範圍，並把被積函數換成 $r$、$\\theta$。","看到 $x^2+y^2$ 或圓形邊界時，想到改用極座標。"],"concept":[{"heading":"① 圓形區域在直角座標裡很難寫","body":["單位圓盤用直角座標寫是 $\\int_{-1}^{1}\\int_{-\\sqrt{1-x^2}}^{\\sqrt{1-x^2}}\\dots\\,dy\\,dx$，上下限帶根號，被積函數若也有 $x^2+y^2$，就更難積。","用〈極座標〉描述，同一塊圓盤只是 $0\\le r\\le 1$、$0\\le\\theta\\le 2\\pi$，像一個矩形。"]},{"heading":"② 小塊的面積：為什麼多一個 $r$","body":["用同心圓與放射線把區域切開，每一小塊是「極座標矩形」：徑向寬 $\\Delta r$，角度張開 $\\Delta\\theta$。","它近似一個長方形：一邊是 $\\Delta r$，另一邊是半徑 $r$ 的圓上、角度 $\\Delta\\theta$ 對應的弧長 $r\\Delta\\theta$。所以面積 $\\approx r\\,\\Delta r\\,\\Delta\\theta$。","直觀上：同樣的 $\\Delta\\theta$，離原點越遠，張出來的弧越長，小塊越大。這個 $r$ 就是放大倍率。","以上是直觀，不是證明：小塊的兩條邊其實是彎的圓弧，「近似長方形」需要交代誤差。下面可展開的段落說明，取中間半徑時這個面積其實完全精確。"]},{"heading":"③ 公式","body":["$x=r\\cos\\theta$、$y=r\\sin\\theta$，$x^2+y^2=r^2$，$dA=r\\,dr\\,d\\theta$。區域寫成 $\\alpha\\le\\theta\\le\\beta$、$r_1(\\theta)\\le r\\le r_2(\\theta)$："],"tex":["\\iint_D f(x,y)\\,dA=\\int_\\alpha^\\beta\\!\\int_{r_1(\\theta)}^{r_2(\\theta)} f(r\\cos\\theta,\\,r\\sin\\theta)\\,r\\,dr\\,d\\theta"]},{"heading":"④ 三步驟","body":["1. 畫區域，寫出 $\\theta$ 的範圍（外層，常數）與 $r$ 的範圍（內層，可以隨 $\\theta$ 變）。","2. 被積函數換掉：$x\\to r\\cos\\theta$、$y\\to r\\sin\\theta$、$x^2+y^2\\to r^2$。","3. 補上 $dA=r\\,dr\\,d\\theta$ 的 $r$，再積分。","$f=1$ 時，$\\iint r\\,dr\\,d\\theta=\\frac{1}{2}\\int r_2(\\theta)^2\\,d\\theta$（$r_1=0$ 時），就是〈極座標面積〉的公式。"]},{"heading":"⑤ $r\\,\\Delta r\\,\\Delta\\theta$ 其實是精確的（給想知道的人）","body":["極座標矩形 $r_1\\le r\\le r_2$、$\\theta_0\\le\\theta\\le\\theta_0+\\Delta\\theta$ 的面積是兩個扇形相減：$\\frac{1}{2}(r_2^2-r_1^2)\\Delta\\theta=\\frac{1}{2}(r_2+r_1)(r_2-r_1)\\Delta\\theta=\\bar r\\,\\Delta r\\,\\Delta\\theta$，其中 $\\bar r$ 是 $r_1$、$r_2$ 的平均。","所以取每一塊的中間半徑，Riemann 和裡的面積完全沒有誤差；剩下的只是 $f$ 取樣的誤差，切細就消失。下一課〈Jacobian 的幾何意義〉會把這個 $r$ 推廣到任意的座標變換。"],"collapsible":true}],"workedExamples":[{"title":"上半圓環","prompt":"$\\iint_D(3x+4y^2)\\,dA$，$D$ 是上半平面中 $1\\le x^2+y^2\\le 4$ 的部分。","steps":["範圍：$1\\le r\\le 2$、$0\\le\\theta\\le\\pi$（上半平面）。","被積函數：$3r\\cos\\theta+4r^2\\sin^2\\theta$。乘上 $dA$ 的 $r$：$(3r^2\\cos\\theta+4r^3\\sin^2\\theta)\\,dr\\,d\\theta$。","內層對 $r$：$\\left[r^3\\cos\\theta+r^4\\sin^2\\theta\\right]_1^2=7\\cos\\theta+15\\sin^2\\theta$。","外層：$\\int_0^\\pi 7\\cos\\theta\\,d\\theta=0$；$\\int_0^\\pi 15\\sin^2\\theta\\,d\\theta=15\\cdot\\frac{\\pi}{2}$。合計 $\\frac{15\\pi}{2}$。"],"answer":"$\\frac{15\\pi}{2}$"},{"title":"拋物面下的體積","prompt":"$z=1-x^2-y^2$ 與 $xy$ 平面圍成的立體體積。","steps":["$z\\ge 0$ 的部分是 $x^2+y^2\\le 1$，也就是單位圓盤：$0\\le r\\le 1$、$0\\le\\theta\\le 2\\pi$。","高度 $1-r^2$，體積 $=\\int_0^{2\\pi}\\int_0^1(1-r^2)\\,r\\,dr\\,d\\theta$。","內層 $\\int_0^1(r-r^3)\\,dr=\\frac{1}{2}-\\frac{1}{4}=\\frac{1}{4}$。外層乘 $2\\pi$，得 $\\frac{\\pi}{2}$。"],"answer":"$\\frac{\\pi}{2}$"},{"title":"多出來的 $r$ 讓積分變得可做","prompt":"$\\iint_D e^{-(x^2+y^2)}\\,dA$，$D$ 是單位圓盤。","steps":["直角座標下 $e^{-x^2}$ 沒有初等反導函數，做不動。","極座標：$\\int_0^{2\\pi}\\int_0^1 e^{-r^2}\\,r\\,dr\\,d\\theta$。","內層令 $u=r^2$，$du=2r\\,dr$：$\\int_0^1 e^{-r^2}\\,r\\,dr=\\frac{1}{2}(1-e^{-1})$。","外層乘 $2\\pi$：$\\pi\\left(1-\\frac{1}{e}\\right)$。"],"answer":"$\\pi\\left(1-\\frac{1}{e}\\right)$","note":"把半徑 $1$ 換成 $R$、讓 $R\\to\\infty$，得到 $\\pi$。這就是〈Gaussian 積分〉$\\int e^{-x^2}\\,dx=\\sqrt\\pi$ 的出發點。"}],"pitfalls":["漏掉 $dA$ 的 $r$：這是本課最常見的錯。","$x^2+y^2\\le 9$ 寫成 $0\\le r\\le 9$；應該是 $r\\le 3$。","上半平面寫成 $0\\le\\theta\\le 2\\pi$；$\\theta$ 的範圍要對照圖形。","被積函數只換了一半，留著 $x$ 或 $y$。"],"checks":[{"ask":"極座標下 $dA$ 等於？","options":[{"label":"$r\\,dr\\,d\\theta$","correct":true},{"label":"$dr\\,d\\theta$","why":"漏了 $r$。同樣的 $\\Delta\\theta$，外圈的弧長 $r\\Delta\\theta$ 比內圈長，小塊面積跟 $r$ 成正比。"},{"label":"$r^2\\,dr\\,d\\theta$","why":"$r^2$ 常常來自被積函數 $x^2+y^2$，不是 $dA$ 本身。$dA$ 只有一個 $r$。"}]},{"ask":"第一象限、$x^2+y^2\\le 9$ 的四分之一圓盤，$r$ 與 $\\theta$ 的範圍是？","options":[{"label":"$0\\le r\\le 3$、$0\\le\\theta\\le\\frac{\\pi}{2}$","correct":true},{"label":"$0\\le r\\le 9$、$0\\le\\theta\\le\\frac{\\pi}{2}$","why":"$x^2+y^2\\le 9$ 是 $r^2\\le 9$，半徑是 $3$。"},{"label":"$0\\le r\\le 3$、$0\\le\\theta\\le 2\\pi$","why":"那是整個圓盤。第一象限只有 $\\theta$ 從 $0$ 到 $\\frac{\\pi}{2}$。"}]},{"ask":"用極座標算 $\\iint_{x^2+y^2\\le1}1\\,dA$，結果是？","options":[{"label":"$\\pi$","correct":true},{"label":"$2\\pi$","why":"漏了 $r$：$\\int_0^1 dr=1$，乘 $2\\pi$ 得 $2\\pi$。正確是 $\\int_0^1 r\\,dr=\\frac{1}{2}$。"},{"label":"$\\frac{1}{2}$","why":"內層 $\\frac{1}{2}$ 之後還要乘外層 $\\int_0^{2\\pi}d\\theta=2\\pi$。"}]},{"ask":"$\\iint_{x^2+y^2\\le4}(x^2+y^2)\\,dA$ 是？","options":[{"label":"$8\\pi$","correct":true},{"label":"$\\frac{16\\pi}{3}$","why":"漏了 $dA$ 的 $r$，只積了 $r^2$：$\\int_0^2 r^2\\,dr=\\frac{8}{3}$。被積函數 $r^2$ 再乘 $r$ 是 $r^3$，$\\int_0^2 r^3\\,dr=4$。"},{"label":"$4\\pi$","why":"那是 $\\iint x^2\\,dA$，只有 $x^2+y^2$ 的一半（$x^2$ 與 $y^2$ 對稱，各佔一半）。"}]}],"practice":[{"id":"int-035","core":true},{"id":"lec-19-m3","core":true},{"id":"int-025","core":true},{"id":"int-032","core":true},{"id":"lec-19-m4","core":true},{"id":"lec-19-q2a","core":true},{"id":"lec-19-q2b"},{"id":"int-033"},{"id":"rel-hard-mv-009"},{"id":"rel-hard-mv-002"},{"id":"lec-19-q2c","challenge":true,"note":"挑戰：體積 $=2\\times\\iint\\sqrt{4-r^2}$，$r$ 從 $1$ 到 $2$。"},{"id":"world-090","challenge":true,"note":"挑戰：令 $I=\\int_0^\\infty e^{-x^2}\\,dx$，算 $I^2$ 寫成第一象限上的二重積分，再換極座標。"}]},"jacobian-geometry":{"id":"jacobian-geometry","prerequisites":["polar-double-integral","multivariable-linearization"],"next":["jacobian-determinant"],"related":["change-of-variables","r2-r3"],"objectives":["說出一個座標變換把小正方形變成近似平行四邊形，面積放大倍率是 |行列式|。","會算線性變換把單位正方形送去的平行四邊形面積。","認出極座標的 $r$ 就是這個放大倍率的特例。"],"concept":[{"heading":"① 先看線性變換","body":["$T(u,v)=(au+bv,cu+dv)$。$uv$ 平面的單位正方形，兩條邊是 $(1,0)$ 與 $(0,1)$，被送到 $(a,c)$ 與 $(b,d)$。正方形變成以這兩個向量為邊的平行四邊形。","平行四邊形面積是 $|ad-bc|$。所以這個變換把每一塊面積都放大 $|ad-bc|$ 倍，處處一樣。"],"tex":["\\text{面積放大倍率}=\\left|\\det\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}\\right|=|ad-bc|"]},{"heading":"② 行列式的正負號","body":["$ad-bc$ 可能是負的，例如 $(u,v)\\mapsto(v,u)$，行列式 $-1$。負號表示圖形被翻面（逆時針變順時針），面積本身不會是負的，所以放大倍率取絕對值。"]},{"heading":"③ 非線性變換：每一點各有各的倍率","body":["一般的變換 $x=x(u,v)$、$y=y(u,v)$ 會把方格扭成彎的。但放大到夠小的一格，它看起來幾乎是線性的（跟〈多變數線性近似〉同一個道理）。","從 $(u,v)$ 走 $\\Delta u$，像點大約移動 $(x_u,y_u)\\,\\Delta u$；走 $\\Delta v$，大約移動 $(x_v,y_v)\\,\\Delta v$。小方格 $\\Delta u\\times\\Delta v$ 變成以這兩個向量為邊的近似平行四邊形，面積約 $|x_uy_v-x_vy_u|\\,\\Delta u\\,\\Delta v$。","這個 $x_uy_v-x_vy_u$ 叫做 Jacobian，記成 $\\frac{\\partial(x,y)}{\\partial(u,v)}$。它隨點改變：有的地方放大，有的地方縮小。這是直觀，不是證明；誤差要比 $\\Delta u\\Delta v$ 小，需要偏導數連續，下一課〈Jacobian 行列式〉再整理。"]},{"heading":"④ 回頭看極座標","body":["$x=r\\cos\\theta$、$y=r\\sin\\theta$。算出 $\\frac{\\partial(x,y)}{\\partial(r,\\theta)}=r$（範例 2）。這正是〈極座標二重積分〉裡 $dA=r\\,dr\\,d\\theta$ 的那個 $r$：在半徑 $r$ 的地方，$\\Delta r\\times\\Delta\\theta$ 的小矩形被放大 $r$ 倍。"]}],"workedExamples":[{"title":"線性變換的面積","prompt":"$T(u,v)=(2u+v,u+3v)$。單位正方形 $[0,1]^2$ 被送到的平行四邊形面積是？","steps":["四個頂點的像：$(0,0)\\to(0,0)$，$(1,0)\\to(2,1)$，$(1,1)\\to(3,4)$，$(0,1)\\to(1,3)$。","放大倍率 $|ad-bc|=|2\\cdot3-1\\cdot1|=5$。","用鞋帶公式驗算頂點 $(0,0)$、$(2,1)$、$(3,4)$、$(1,3)$：$\\frac{1}{2}|0+(8-3)+(9-4)+0|=5$。"],"answer":"$5$"},{"title":"極座標的放大倍率","prompt":"$x=r\\cos\\theta$、$y=r\\sin\\theta$，求 $\\frac{\\partial(x,y)}{\\partial(r,\\theta)}$。","steps":["$x_r=\\cos\\theta$，$x_\\theta=-r\\sin\\theta$；$y_r=\\sin\\theta$，$y_\\theta=r\\cos\\theta$。","$x_ry_\\theta-x_\\theta y_r=\\cos\\theta\\cdot r\\cos\\theta-(-r\\sin\\theta)\\cdot\\sin\\theta=r(\\cos^2\\theta+\\sin^2\\theta)=r$。","所以在 $r=2$ 附近，一個 $\\Delta r\\times\\Delta\\theta$ 的小矩形，面積約 $2\\,\\Delta r\\,\\Delta\\theta$。"],"answer":"$r$"},{"title":"把圓拉成橢圓","prompt":"$x=3u$、$y=2v$。單位圓盤 $u^2+v^2\\le 1$ 被送到哪裡？面積多少？","steps":["$u=\\frac{x}{3}$、$v=\\frac{y}{2}$，代入 $u^2+v^2\\le 1$ 得 $\\frac{x^2}{9}+\\frac{y^2}{4}\\le 1$，是半軸 $3$、$2$ 的橢圓。","Jacobian $=3\\cdot2-0\\cdot0=6$，處處一樣。","圓盤面積 $\\pi$，放大 $6$ 倍：橢圓面積 $6\\pi$。"],"answer":"橢圓 $\\frac{x^2}{9}+\\frac{y^2}{4}\\le 1$，面積 $6\\pi$"}],"pitfalls":["把負的行列式直接當面積；面積要取絕對值。","以為非線性變換的放大倍率處處一樣；它隨點改變。","把 $x$ 方向與 $y$ 方向的倍率相加；面積倍率是相乘（更一般是行列式）。"],"checks":[{"ask":"$T(u,v)=(u+v,u-v)$ 把單位正方形送去的圖形面積是？","options":[{"label":"$2$","correct":true},{"label":"$-2$","why":"行列式 $1\\cdot(-1)-1\\cdot1=-2$，負號只代表翻面，面積是 $2$。"},{"label":"$1$","why":"這不只是旋轉；兩條邊變成 $(1,1)$ 與 $(1,-1)$，長度都是 $\\sqrt2$，面積 $2$。"}]},{"ask":"某點的 $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=3$，意思是？","options":[{"label":"那一點附近的小塊面積被放大約 $3$ 倍","correct":true},{"label":"整個區域的面積是 $3$","why":"Jacobian 是逐點的倍率，會隨點改變。總面積要把它積分起來。"},{"label":"那一點附近的曲線長度被放大 $3$ 倍","why":"行列式量的是面積的倍率，不是長度。同一個變換在不同方向可以拉長不同倍數。"}]},{"ask":"極座標在 $r=3$ 附近，一個 $\\Delta r\\times\\Delta\\theta$ 的小矩形對應的 $xy$ 面積約是？","options":[{"label":"$3\\,\\Delta r\\,\\Delta\\theta$","correct":true},{"label":"$\\Delta r\\,\\Delta\\theta$","why":"忽略了放大倍率 $r$。離原點越遠，同樣的 $\\Delta\\theta$ 張出越長的弧。"},{"label":"$9\\,\\Delta r\\,\\Delta\\theta$","why":"倍率是 $r$ 不是 $r^2$。"}]},{"ask":"$x=2u$、$y=5v$ 的面積放大倍率是？","options":[{"label":"$10$","correct":true},{"label":"$7$","why":"兩個方向的倍率要相乘，不是相加：寬變 $2$ 倍、高變 $5$ 倍，面積變 $10$ 倍。"},{"label":"$2.5$","why":"沒有相除的道理；行列式是 $2\\cdot5-0\\cdot0=10$。"}]}],"practice":[{"id":"gap-int-cov-002","core":true},{"id":"lec-19-m5","core":true},{"id":"der-071"},{"id":"gap-int-cov-001"}]},"jacobian-determinant":{"id":"jacobian-determinant","prerequisites":["jacobian-geometry","partial-derivatives"],"next":["change-of-variables"],"related":["multivariable-chain-rule","spherical-coordinates","cylindrical-coordinates"],"objectives":["照定義算 $2\\times2$ 的 Jacobian $\\frac{\\partial(x,y)}{\\partial(u,v)}$。","已知 $u$、$v$ 是 $x$、$y$ 的函數時，用倒數關係 $\\frac{\\partial(x,y)}{\\partial(u,v)}=1\\big/\\frac{\\partial(u,v)}{\\partial(x,y)}$，不必先解出 $x$、$y$。","知道三變數的 Jacobian 也是行列式，柱座標是 $r$、球座標是 $\\rho^2\\sin\\varphi$。"],"concept":[{"heading":"① 定義","body":["變換 $x=x(u,v)$、$y=y(u,v)$，偏導數連續。把四個偏導數排成矩陣：第一列是 $x$ 對 $u$、$v$ 的偏導，第二列是 $y$ 對 $u$、$v$ 的偏導。它的行列式就是 Jacobian（下式）。","上一課看到，$|J|$ 是 $(u,v)$ 附近小方格被放大的倍率；$J$ 的正負號表示有沒有翻面。"],"tex":["\\frac{\\partial(x,y)}{\\partial(u,v)}=\\det\\begin{pmatrix}x_u&x_v\\\\y_u&y_v\\end{pmatrix}=x_u\\,y_v-x_v\\,y_u"]},{"heading":"② 計算步驟","body":["1. 寫出 $x$、$y$ 各自對 $u$、$v$ 的四個偏導數。","2. 交叉相乘相減：主對角線 $x_uy_v$，減去反對角線 $x_vy_u$。","3. 化簡。答案通常還是 $u$、$v$ 的函數。","例：$x=2u+v$、$y=u-v$。$x_u=2$、$x_v=1$、$y_u=1$、$y_v=-1$，$J=2\\cdot(-1)-1\\cdot1=-3$。面積放大 $|J|=3$ 倍，而且翻面。"]},{"heading":"③ 反方向：倒數關係","body":["很多題目給的是 $u=u(x,y)$、$v=v(x,y)$（從區域邊界讀出來的），要的卻是 $\\frac{\\partial(x,y)}{\\partial(u,v)}$。不必先解出 $x$、$y$，直接取倒數（下式）。","直觀理由：從 $(x,y)$ 到 $(u,v)$ 把面積放大 $k$ 倍，反過來就縮小成 $\\frac{1}{k}$ 倍。正式的理由是〈多變數連鎖律〉：兩個變換合成是恆等映射，兩個 Jacobian 矩陣相乘是單位矩陣，行列式相乘等於 $1$。條件是 $J\\ne 0$。"],"tex":["\\frac{\\partial(x,y)}{\\partial(u,v)}=\\frac{1}{\\partial(u,v)/\\partial(x,y)}"]},{"heading":"④ 三個變數","body":["$x$、$y$、$z$ 都是 $u$、$v$、$w$ 的函數時，Jacobian 是 $3\\times3$ 的行列式，$|J|$ 是小方塊的體積放大倍率。兩個以後會一直用到：〈柱座標〉的 Jacobian 是 $r$，〈球座標〉的是 $\\rho^2\\sin\\varphi$。"],"tex":["\\frac{\\partial(x,y,z)}{\\partial(u,v,w)}=\\det\\begin{pmatrix}x_u&x_v&x_w\\\\y_u&y_v&y_w\\\\z_u&z_v&z_w\\end{pmatrix}"]}],"workedExamples":[{"title":"照定義算","prompt":"$x=u^2-v^2$、$y=2uv$，求 $\\frac{\\partial(x,y)}{\\partial(u,v)}$。","steps":["$x_u=2u$，$x_v=-2v$；$y_u=2v$，$y_v=2u$。","$x_uy_v-x_vy_u=2u\\cdot2u-(-2v)(2v)=4u^2+4v^2$。"],"answer":"$4(u^2+v^2)$"},{"title":"兩種方法對答案","prompt":"$u=x+y$、$v=x-y$，求 $\\frac{\\partial(x,y)}{\\partial(u,v)}$。","steps":["方法一：解出 $x=\\frac{u+v}{2}$、$y=\\frac{u-v}{2}$。$x_u=\\frac{1}{2}$、$x_v=\\frac{1}{2}$、$y_u=\\frac{1}{2}$、$y_v=-\\frac{1}{2}$。$J=\\left(\\frac{1}{2}\\right)\\left(-\\frac{1}{2}\\right)-\\left(\\frac{1}{2}\\right)\\left(\\frac{1}{2}\\right)=-\\frac{1}{2}$。","方法二：$\\frac{\\partial(u,v)}{\\partial(x,y)}=1\\cdot(-1)-1\\cdot1=-2$，取倒數得 $-\\frac{1}{2}$。","兩種一樣。用來換變數時取絕對值 $\\frac{1}{2}$。"],"answer":"$-\\frac{1}{2}$（絕對值 $\\frac{1}{2}$）"},{"title":"解不出來也沒關係","prompt":"$u=xy$、$v=\\frac{y}{x}$（$x,y>0$），求 $\\frac{\\partial(x,y)}{\\partial(u,v)}$。","steps":["先算反方向：$u_x=y$、$u_y=x$；$v_x=-\\frac{y}{x^2}$、$v_y=\\frac{1}{x}$。","$\\frac{\\partial(u,v)}{\\partial(x,y)}=y\\cdot\\frac{1}{x}-x\\cdot\\left(-\\frac{y}{x^2}\\right)=\\frac{y}{x}+\\frac{y}{x}=\\frac{2y}{x}=2v$。","取倒數：$\\frac{\\partial(x,y)}{\\partial(u,v)}=\\frac{1}{2v}$。","驗算：其實可以解出 $x=\\sqrt{u/v}$、$y=\\sqrt{uv}$，直接算也是 $\\frac{1}{2v}$。但倒數法完全不需要這一步。"],"answer":"$\\frac{1}{2v}$"}],"pitfalls":["要的是 $\\frac{\\partial(x,y)}{\\partial(u,v)}$，卻交出 $\\frac{\\partial(u,v)}{\\partial(x,y)}$，差了一個倒數。","交叉相乘用成相加：$x_uy_v+x_vy_u$。","求倒數之後忘了把結果改寫成 $u$、$v$（例如 $\\frac{2y}{x}$ 要寫成 $2v$）。","換變數時用 $J$ 本身而不是 $|J|$。"],"checks":[{"ask":"$x=3u+v$、$y=u+2v$，$\\frac{\\partial(x,y)}{\\partial(u,v)}$ 是？","options":[{"label":"$5$","correct":true},{"label":"$7$","why":"那是 $3\\cdot2+1\\cdot1$，用了相加。行列式是主對角線減反對角線：$6-1$。"},{"label":"$-5$","why":"順序反了：是 $x_uy_v-x_vy_u=6-1$，不是 $1-6$。"}]},{"ask":"已知 $\\frac{\\partial(u,v)}{\\partial(x,y)}=4$（處處），那 $\\frac{\\partial(x,y)}{\\partial(u,v)}$ 是？","options":[{"label":"$\\frac{1}{4}$","correct":true},{"label":"$4$","why":"這是反方向的 Jacobian。從 $(x,y)$ 到 $(u,v)$ 放大 $4$ 倍，反過來是縮小成 $\\frac{1}{4}$。"},{"label":"$-4$","why":"倒數不會變號；兩者相乘等於 $1$。"}]},{"ask":"$x=r\\cos\\theta$、$y=r\\sin\\theta$ 的 $\\frac{\\partial(x,y)}{\\partial(r,\\theta)}$ 是？","options":[{"label":"$r$","correct":true},{"label":"$1$","why":"$\\cos^2\\theta+\\sin^2\\theta=1$ 前面還有一個 $r$：$r\\cos^2\\theta+r\\sin^2\\theta=r$。"},{"label":"$r^2$","why":"四個偏導裡只有 $x_\\theta$、$y_\\theta$ 帶 $r$，每一項只乘到一次 $r$。"}]},{"ask":"換變數公式裡乘的是什麼？","options":[{"label":"$\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|$","correct":true},{"label":"$\\frac{\\partial(x,y)}{\\partial(u,v)}$，正負號要保留","why":"負號只表示翻面。面積是正的，所以取絕對值。"},{"label":"$\\left|\\frac{\\partial(u,v)}{\\partial(x,y)}\\right|$","why":"方向反了。$dA=dx\\,dy$ 要換成 $du\\,dv$，倍率是 $x$、$y$ 對 $u$、$v$ 的 Jacobian。"}]}],"practice":[{"id":"der-034","core":true},{"id":"der-069","core":true},{"id":"rel-adv-005"},{"id":"rel-hard-mv-005"},{"id":"der-072"},{"id":"lec-19-q4b"},{"id":"gap-int-cov-001"},{"id":"der-070","challenge":true,"note":"挑戰：兩層變換，Jacobian 相乘（連鎖律）。"},{"id":"der-074","challenge":true,"note":"挑戰：合成映射的 Jacobian 行列式等於各自行列式相乘。"}]},"change-of-variables":{"id":"change-of-variables","prerequisites":["jacobian-determinant","u-sub-definite"],"next":["triple-integral"],"related":["polar-double-integral","jacobian-geometry"],"objectives":["寫出二重積分的變數變換公式，並說出每一部分的來源（新區域、代換後的被積函數、$|J|$）。","從區域的邊界方程式選出新變數 $u$、$v$，把區域變成矩形或簡單形狀。","記得公式成立的條件：變換在區域內部一對一、Jacobian 不為 0。"],"concept":[{"heading":"① 一維的換元，二維再來一次","body":["〈定積分換元〉：$x=g(u)$，$dx=g'(u)\\,du$，上下限跟著換。二維也一樣有三件事要換：區域、被積函數、面積元素。","面積元素怎麼換，前兩課已經準備好了：$uv$ 平面上一個 $du\\,dv$ 的小方格，被送到 $xy$ 平面後面積約 $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|du\\,dv$。"]},{"heading":"② 公式","body":["下式右邊三個部分各有來源：$S$ 是同一塊區域在 $uv$ 平面的樣子；$f$ 裡的 $x$、$y$ 全部換成 $u$、$v$ 的式子；$|J|$ 是每個小方格的面積放大倍率，取絕對值是因為面積不能是負的。極座標正是 $|J|=r$ 的情形。","設 $x=x(u,v)$、$y=y(u,v)$ 把 $uv$ 平面的區域 $S$ 送到 $xy$ 平面的區域 $R$："],"tex":["\\iint_R f(x,y)\\,dA=\\iint_S f\\big(x(u,v),\\,y(u,v)\\big)\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|du\\,dv"]},{"heading":"③ 怎麼選 $u$、$v$","body":["最常見的線索是區域的邊界。$R$ 由 $x-2y=0$、$x-2y=4$、$3x-y=1$、$3x-y=8$ 四條線圍成：令 $u=x-2y$、$v=3x-y$，四條邊就變成 $u=0$、$u=4$、$v=1$、$v=8$，$S$ 是矩形。","第二個線索是被積函數：裡面一直出現 $x+y$、$x-y$，就讓它們當新變數。","這種題通常給的是 $u$、$v$ 用 $x$、$y$ 表示，所以 Jacobian 用〈Jacobian 行列式〉的倒數關係算最快。"]},{"heading":"④ 四個步驟","body":["1. 選 $u$、$v$。2. 把 $R$ 的每一條邊界換成 $u$、$v$，畫出 $S$。3. 算 $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|$。4. 被積函數換成 $u$、$v$，乘上 $|J|$，在 $S$ 上積分。"]},{"heading":"⑤ 公式成立的條件（給想知道的人）","body":["變換的偏導數連續，在 $S$ 的內部一對一，Jacobian 在 $S$ 的內部不為 $0$；$S$、$R$ 的邊界是有限條光滑曲線。邊界上壞掉（不一對一或 $J=0$）沒關係，因為邊界的面積是 $0$。","極座標就是例子：$r=0$ 時 $J=0$，$\\theta=0$ 與 $\\theta=2\\pi$ 也重疊，但這些都只在邊界上，所以〈極座標二重積分〉照樣成立。"],"collapsible":true}],"workedExamples":[{"title":"斜的平行四邊形","prompt":"$\\iint_R\\frac{x-2y}{3x-y}\\,dA$，$R$ 由 $x-2y=0$、$x-2y=4$、$3x-y=1$、$3x-y=8$ 圍成。","steps":["令 $u=x-2y$、$v=3x-y$。$S=[0,4]\\times[1,8]$。","$\\frac{\\partial(u,v)}{\\partial(x,y)}=1\\cdot(-1)-(-2)\\cdot3=5$，所以 $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=\\frac{1}{5}$。","被積函數是 $\\frac{u}{v}$。積分 $=\\int_1^8\\int_0^4\\frac{u}{v}\\cdot\\frac{1}{5}\\,du\\,dv$。","可分離：$\\frac{1}{5}\\cdot\\left(\\int_0^4 u\\,du\\right)\\left(\\int_1^8\\frac{dv}{v}\\right)=\\frac{1}{5}\\cdot8\\cdot\\ln 8=\\frac{24\\ln 2}{5}$。"],"answer":"$\\frac{8}{5}\\ln 8=\\frac{24\\ln 2}{5}$"},{"title":"新區域不是矩形","prompt":"$\\iint_R\\cos\\left(\\frac{x-y}{x+y}\\right)dA$，$R$ 是頂點 $(1,0)$、$(2,0)$、$(0,2)$、$(0,1)$ 的梯形。","steps":["被積函數裡有 $x-y$、$x+y$：令 $u=x-y$、$v=x+y$。$\\frac{\\partial(u,v)}{\\partial(x,y)}=-2$，$|J|=\\frac{1}{2}$。","四條邊：$x+y=1\\to v=1$；$x+y=2\\to v=2$；$y=0\\to u=v$；$x=0\\to u=-v$。","$S$：$1\\le v\\le 2$、$-v\\le u\\le v$。","$\\int_1^2\\int_{-v}^{v}\\cos\\left(\\frac{u}{v}\\right)\\frac{1}{2}\\,du\\,dv$。內層：$\\frac{1}{2}\\cdot v\\left[\\sin\\frac{u}{v}\\right]_{-v}^{v}=\\frac{1}{2}\\cdot2v\\sin 1=v\\sin 1$。","外層 $\\int_1^2 v\\sin 1\\,dv=\\frac{3}{2}\\sin 1$。"],"answer":"$\\frac{3}{2}\\sin 1$"},{"title":"橢圓：拉伸後的極座標","prompt":"$\\iint_E x^2\\,dA$，$E$：$\\frac{x^2}{9}+\\frac{y^2}{4}\\le 1$。","steps":["令 $x=3r\\cos\\theta$、$y=2r\\sin\\theta$，$E$ 變成 $0\\le r\\le 1$、$0\\le\\theta\\le 2\\pi$。","Jacobian：$x_ry_\\theta-x_\\theta y_r=3\\cos\\theta\\cdot2r\\cos\\theta+3r\\sin\\theta\\cdot2\\sin\\theta=6r$。","$\\int_0^{2\\pi}\\int_0^1 9r^2\\cos^2\\theta\\cdot6r\\,dr\\,d\\theta=54\\cdot\\frac{1}{4}\\cdot\\pi=\\frac{27\\pi}{2}$。"],"answer":"$\\frac{27\\pi}{2}$"}],"pitfalls":["忘了乘 $|J|$，等於假設面積沒有被放大。","乘成 $\\left|\\frac{\\partial(u,v)}{\\partial(x,y)}\\right|$，差了一個倒數。","只換了被積函數，區域還用舊的 $x$、$y$ 範圍。","選的 $u$、$v$ 不獨立（例如 $u=x+y$、$v=2x+2y$），Jacobian 是 $0$，不能用。"],"checks":[{"ask":"$R$：$0\\le x+y\\le 1$、$0\\le x-y\\le 1$。用 $u=x+y$、$v=x-y$，$\\iint_R 1\\,dA$ 是？","options":[{"label":"$\\frac{1}{2}$","correct":true},{"label":"$1$","why":"那是 $S$ 的面積，忘了乘 $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=\\frac{1}{2}$。"},{"label":"$2$","why":"乘成了 $\\left|\\frac{\\partial(u,v)}{\\partial(x,y)}\\right|=2$。要的是 $x$、$y$ 對 $u$、$v$ 的 Jacobian，是它的倒數。"}]},{"ask":"$R$ 由 $x+2y=0$、$x+2y=3$、$x-y=1$、$x-y=4$ 圍成，最自然的換法是？","options":[{"label":"$u=x+2y$、$v=x-y$","correct":true},{"label":"$u=x$、$v=y$","why":"這等於沒換，區域還是斜的平行四邊形。"},{"label":"$u=x+2y$、$v=2x+4y$","why":"$v$ 是 $u$ 的 $2$ 倍，兩個新變數不獨立，Jacobian 為 $0$，不能當座標。"}]},{"ask":"變數變換公式要求變換滿足哪一個條件？","options":[{"label":"在新區域的內部一對一，而且 Jacobian 不為 0","correct":true},{"label":"必須是線性變換","why":"極座標 $x=r\\cos\\theta$ 就不是線性，公式照樣成立。"},{"label":"Jacobian 必須是常數","why":"極座標的 Jacobian 是 $r$，會變；公式裡本來就是逐點乘 $|J|$。"}]},{"ask":"用 $x=au$、$y=bv$（$a,b>0$）求橢圓 $\\frac{x^2}{a^2}+\\frac{y^2}{b^2}\\le 1$ 的面積：","options":[{"label":"$\\pi ab$","correct":true},{"label":"$\\pi(a+b)$","why":"倍率是 Jacobian $ab$，相乘不是相加。"},{"label":"$\\pi a^2b^2$","why":"Jacobian 是 $a\\cdot b-0\\cdot0=ab$，不是 $a^2b^2$。"}]}],"practice":[{"id":"gap-int-cov-002","core":true},{"id":"lec-19-q4a","core":true},{"id":"lec-19-q4c","core":true},{"id":"lec-19-m5","core":true},{"id":"rel-hard-mv-008"},{"id":"rel-boss-010","challenge":true,"note":"挑戰：令 $x=uv$、$y=u(1-v)$，三角形變成正方形。"}]},"triple-integral":{"id":"triple-integral","prerequisites":["nonrectangular-regions","r2-r3"],"next":["cylindrical-coordinates"],"related":["center-of-mass","change-of-variables","surface-area"],"objectives":["說出 $\\iiint_E f\\,dV$ 的意思：$f$ 是密度時是質量，$f=1$ 時是體積。","把立體寫成「$z$ 夾在兩張曲面之間、$(x,y)$ 落在投影區域 $D$」，把三重積分化成 $D$ 上的二重積分。","依區域形狀挑積分次序，由內往外一層一層積。"],"concept":[{"heading":"① 再加一個維度","body":["二重積分是平面區域切小塊、每塊乘上 $f$ 再加起來。三重積分把立體 $E$ 切成小方塊，每塊體積 $\\Delta V=\\Delta x\\,\\Delta y\\,\\Delta z$，乘上 $f$ 在塊裡某點的值，加起來取極限。","沒有「高度」可以畫了，換個方式想：$f$ 是密度（每單位體積的質量），$\\iiint_E f\\,dV$ 就是總質量。$f=1$ 時是 $E$ 的體積。"]},{"heading":"② 盒子：三層都是常數","body":["$E=[a,b]\\times[c,d]\\times[p,q]$，$f$ 連續時三重積分等於任何次序的累次積分（Fubini 的三維版），一共 6 種次序。由內往外，每一層都把外面的變數當常數。"]},{"heading":"③ 一般的立體：先找上下兩張曲面","body":["最常用的描述：$E$ 在 $xy$ 平面上的投影是 $D$，而且每一點 $(x,y)$ 正上方，$E$ 從下曲面 $z=u_1(x,y)$ 進入、從上曲面 $z=u_2(x,y)$ 離開。","於是最內層對 $z$ 積，上下限是這兩張曲面；積完剩下的就是 $D$ 上的二重積分，接著用〈非矩形區域〉的方法寫 $D$。"],"tex":["\\iiint_E f\\,dV=\\iint_D\\left[\\int_{u_1(x,y)}^{u_2(x,y)} f(x,y,z)\\,dz\\right]dA"]},{"heading":"④ 找 $D$ 的方法","body":["$D$ 是立體的「影子」。上下兩張曲面相交的地方，就是影子的邊界：令 $u_1(x,y)=u_2(x,y)$。例：$z=x^2+y^2$ 與 $z=2-x^2-y^2$ 交在 $x^2+y^2=1$，$D$ 是單位圓盤。","有時立體往 $xz$ 或 $yz$ 平面投影比較簡單，那就讓 $y$ 或 $x$ 當最內層。原則一樣：最內層是「穿過立體的一條線」從哪裡進、從哪裡出。"]}],"workedExamples":[{"title":"盒子","prompt":"$\\iiint_B xyz^2\\,dV$，$B=[0,1]\\times[-1,2]\\times[0,3]$。","steps":["盒子上的可分離函數，三個一維積分相乘。","$\\int_0^1 x\\,dx=\\frac{1}{2}$；$\\int_{-1}^{2}y\\,dy=\\frac{4-1}{2}=\\frac{3}{2}$；$\\int_0^3 z^2\\,dz=9$。","相乘：$\\left(\\frac{1}{2}\\right)\\left(\\frac{3}{2}\\right)(9)=\\frac{27}{4}$。"],"answer":"$\\frac{27}{4}$"},{"title":"四面體的體積","prompt":"$\\frac{x}{1}+\\frac{y}{2}+\\frac{z}{3}\\le 1$ 在第一卦限的四面體體積。","steps":["下曲面 $z=0$，上曲面是平面：$z=3\\left(1-x-\\frac{y}{2}\\right)$。","投影 $D$：令 $z=0$，得 $x+\\frac{y}{2}\\le 1$，也就是第一象限裡 $0\\le x\\le 1$、$0\\le y\\le 2(1-x)$ 的三角形。","$V=\\int_0^1\\int_0^{2(1-x)}\\int_0^{3(1-x-y/2)}dz\\,dy\\,dx=\\int_0^1\\int_0^{2(1-x)}3\\left(1-x-\\frac{y}{2}\\right)dy\\,dx$。","內層對 $y$：$3\\left[(1-x)y-\\frac{y^2}{4}\\right]_0^{2(1-x)}=3\\left[2(1-x)^2-(1-x)^2\\right]=3(1-x)^2$。","外層 $\\int_0^1 3(1-x)^2\\,dx=1$。跟公式「三軸截距相乘除以 6」$=\\frac{1\\cdot2\\cdot3}{6}=1$ 一致。"],"answer":"$1$"},{"title":"上下限一層套一層","prompt":"$\\int_0^1\\int_0^x\\int_0^{xy}1\\,dz\\,dy\\,dx$","steps":["最內層：$\\int_0^{xy}dz=xy$。","中間層：$\\int_0^x xy\\,dy=x\\cdot\\frac{x^2}{2}=\\frac{x^3}{2}$。","外層：$\\int_0^1\\frac{x^3}{2}\\,dx=\\frac{1}{8}$。"],"answer":"$\\frac{1}{8}$"}],"pitfalls":["最內層寫成 $z$ 的總範圍（像 $0$ 到 $2$），沒有隨 $(x,y)$ 改變。","投影區域 $D$ 找錯：上下曲面的交線才是 $D$ 的邊界。","外層上下限含變數，答案還留著 $x$、$y$ 或 $z$。","把 $\\iiint 1\\,dV$ 當成表面積；它是體積。"],"checks":[{"ask":"$\\iiint_E 1\\,dV$ 代表？","options":[{"label":"$E$ 的體積","correct":true},{"label":"$E$ 的表面積","why":"每個小方塊貢獻的是它的體積 $\\Delta V$，加起來是體積。表面積要用〈曲面面積〉。"},{"label":"$E$ 在 $xy$ 平面上的投影面積","why":"那是 $\\iint_D 1\\,dA$。三重積分還有 $z$ 方向的長度要乘。"}]},{"ask":"$E$ 在 $z=x^2+y^2$ 之上、$z=2-x^2-y^2$ 之下。最內層 $z$ 的範圍是？","options":[{"label":"$x^2+y^2\\le z\\le 2-x^2-y^2$","correct":true},{"label":"$2-x^2-y^2\\le z\\le x^2+y^2$","why":"在投影區域內，$x^2+y^2$ 是下面那張（例如原點 $0<2$），上下顛倒了。"},{"label":"$0\\le z\\le 2$","why":"那是整個立體 $z$ 的總範圍；每一根鉛直線實際上從 $x^2+y^2$ 進、從 $2-x^2-y^2$ 出。"}]},{"ask":"承上題，投影區域 $D$ 是？","options":[{"label":"$x^2+y^2\\le 1$","correct":true},{"label":"$x^2+y^2\\le 2$","why":"那是上曲面碰到 $z=0$ 的地方，但立體的下底不是 $z=0$。令兩曲面相等：$2(x^2+y^2)=2$。"},{"label":"$x^2+y^2\\le 4$","why":"沒有理由出現 $4$；邊界由兩張曲面的交線決定，交在 $x^2+y^2=1$。"}]},{"ask":"$\\iiint_{[0,2]^3}xyz\\,dV$ 是？","options":[{"label":"$8$","correct":true},{"label":"$6$","why":"三個 $\\int_0^2(\\cdot)\\,d(\\cdot)=2$ 要相乘，不是相加。"},{"label":"$2$","why":"只算了其中一個因子 $\\int_0^2 x\\,dx=2$，另外兩個也是 $2$。"}]}],"practice":[{"id":"gap-int-triple-001","core":true},{"id":"gap-int-triple-002","core":true},{"id":"gap-int-triple-004","core":true},{"id":"gap-int-triple-003","core":true},{"id":"lec-19-q3a","core":true},{"id":"rel-boss-011"},{"id":"rel-hard-mv-010","challenge":true,"note":"挑戰：三層多項式積分，耐心展開；答案可用 Dirichlet 公式 $\\frac{a!\\,b!\\,c!}{(a+b+c+3)!}$ 核對。"}]},"cylindrical-coordinates":{"id":"cylindrical-coordinates","prerequisites":["triple-integral","polar-double-integral"],"next":["spherical-coordinates"],"related":["jacobian-determinant","polar-coordinates"],"objectives":["把 $(x,y,z)$ 換成 $(r,\\theta,z)$，並寫出 $dV=r\\,dz\\,dr\\,d\\theta$。","把圓柱、圓錐、拋物面這些繞 $z$ 軸對稱的曲面寫成 $r$、$z$ 的關係。","判斷什麼時候用柱座標最省事。"],"concept":[{"heading":"① 底面用極座標，高度照舊","body":["柱座標就是「$xy$ 平面用〈極座標〉，$z$ 不動」：$x=r\\cos\\theta$、$y=r\\sin\\theta$、$z=z$。$x^2+y^2=r^2$。","名字來自 $r={}$ 常數 的曲面：那是一個以 $z$ 軸為中心的圓柱面。","水管、杯子、旋轉出來的碗，這些繞一根軸對稱的東西，用「離軸多遠、轉了幾度、多高」描述最自然，這三個數就是 $r$、$\\theta$、$z$。"]},{"heading":"② 體積元素","body":["想像一個小塊：底面是極座標小格，徑向寬 $dr$、弧長 $r\\,d\\theta$，再往上拉出 $dz$ 的厚度。底面積 $r\\,dr\\,d\\theta$（〈極座標二重積分〉）乘高度 $dz$，所以 $dV=r\\,dz\\,dr\\,d\\theta$。","用〈Jacobian 行列式〉算也一樣：$\\frac{\\partial(x,y,z)}{\\partial(r,\\theta,z)}=r$。$z$ 方向沒有被拉伸，放大倍率全部來自底面。"],"tex":["\\iiint_E f\\,dV=\\int_\\alpha^\\beta\\!\\int_{r_1(\\theta)}^{r_2(\\theta)}\\!\\int_{u_1}^{u_2} f(r\\cos\\theta,\\,r\\sin\\theta,\\,z)\\,r\\,dz\\,dr\\,d\\theta"]},{"heading":"③ 常見曲面的柱座標樣子","body":["圓柱面 $x^2+y^2=4\\to r=2$。","圓錐面 $z=\\sqrt{x^2+y^2}\\to z=r$。","拋物面 $z=x^2+y^2\\to z=r^2$。","半平面 $y=x$（$x>0$）$\\to\\theta=\\frac{\\pi}{4}$。","這些都只用到 $x^2+y^2$，所以換成 $r$ 之後一下子變簡單。"]},{"heading":"④ 步驟與適用時機","body":["跟〈三重積分〉一樣先找上下兩張曲面當 $z$ 的上下限（寫成 $r$、$\\theta$ 的函數），再把投影 $D$ 寫成極座標範圍，最後補上 $r$。","立體繞 $z$ 軸對稱、或被積函數含 $x^2+y^2$ 時用柱座標。區域是盒子或四面體這種平面圍成的形狀，直角座標比較簡單；以原點為中心的球，〈球座標〉更直接。"]}],"workedExamples":[{"title":"圓錐的體積","prompt":"圓錐面 $z=\\sqrt{x^2+y^2}$ 與平面 $z=2$ 圍成的立體體積。","steps":["柱座標：下曲面 $z=r$，上曲面 $z=2$。","投影：兩曲面交在 $r=2$，所以 $0\\le r\\le 2$、$0\\le\\theta\\le 2\\pi$。","$V=\\int_0^{2\\pi}\\int_0^2\\int_r^2 r\\,dz\\,dr\\,d\\theta=2\\pi\\int_0^2(2-r)\\,r\\,dr$。","$\\int_0^2(2r-r^2)\\,dr=4-\\frac{8}{3}=\\frac{4}{3}$，乘 $2\\pi$ 得 $\\frac{8\\pi}{3}$。","驗算：底半徑 $2$、高 $2$ 的圓錐，$\\frac{1}{3}\\pi\\cdot2^2\\cdot2=\\frac{8\\pi}{3}$。"],"answer":"$\\frac{8\\pi}{3}$"},{"title":"密度隨離軸距離增加","prompt":"$E$ 在圓柱 $x^2+y^2\\le 1$ 內、拋物面 $z=1-x^2-y^2$ 之上、平面 $z=4$ 之下，密度 $\\sqrt{x^2+y^2}$。求質量。","steps":["柱座標：$z$ 從 $1-r^2$ 到 $4$；$0\\le r\\le 1$、$0\\le\\theta\\le 2\\pi$；密度 $\\sqrt{x^2+y^2}=r$。","$m=\\int_0^{2\\pi}\\int_0^1\\int_{1-r^2}^{4}r\\cdot r\\,dz\\,dr\\,d\\theta$。注意兩個 $r$：一個是密度，一個是 $dV$。","最內層：$r^2(4-(1-r^2))=r^2(3+r^2)=3r^2+r^4$。","$\\int_0^1(3r^2+r^4)\\,dr=1+\\frac{1}{5}=\\frac{6}{5}$，乘 $2\\pi$ 得 $\\frac{12\\pi}{5}$。"],"answer":"$\\frac{12\\pi}{5}$"},{"title":"被積函數含 $x^2+y^2$","prompt":"$\\iiint_E(x^2+y^2)\\,dV$，$E$：$x^2+y^2\\le 4$、$0\\le z\\le 3$。","steps":["柱座標：$0\\le r\\le 2$、$0\\le\\theta\\le 2\\pi$、$0\\le z\\le 3$；$x^2+y^2=r^2$。","被積函數 $r^2$ 乘上 $dV$ 的 $r$：$\\int_0^{2\\pi}\\int_0^2\\int_0^3 r^3\\,dz\\,dr\\,d\\theta$。","三層都是常數上下限，可分離：$2\\pi\\cdot\\left(\\int_0^2 r^3\\,dr\\right)\\cdot3=2\\pi\\cdot4\\cdot3=24\\pi$。"],"answer":"$24\\pi$","note":"這種積分是均勻圓柱對 $z$ 軸的轉動慣量（密度為 $1$）。"}],"pitfalls":["漏了 $dV$ 的 $r$。","密度或被積函數裡也有 $r$ 時，跟 $dV$ 的 $r$ 合併成 $r^2$，只寫了一個。","把圓錐 $z=r$ 跟拋物面 $z=r^2$ 搞混。","$z$ 的上下限用常數，沒寫成 $r$ 的函數。"],"checks":[{"ask":"柱座標的 $dV$ 是？","options":[{"label":"$r\\,dz\\,dr\\,d\\theta$","correct":true},{"label":"$dz\\,dr\\,d\\theta$","why":"漏了 $r$。底面的小塊面積是 $r\\,dr\\,d\\theta$，外圈比內圈大。"},{"label":"$r^2\\,dz\\,dr\\,d\\theta$","why":"那是把被積函數的 $r$ 也算進去了。$dV$ 本身只有一個 $r$；$r^2\\sin\\varphi$ 那種是球座標。"}]},{"ask":"圓錐面 $z=\\sqrt{x^2+y^2}$ 用柱座標寫是？","options":[{"label":"$z=r$","correct":true},{"label":"$z=r^2$","why":"那是拋物面 $z=x^2+y^2$。這裡有開根號，$\\sqrt{r^2}=r$（$r\\ge 0$）。"},{"label":"$r=1$","why":"$r={}$ 常數 是圓柱面，不是圓錐。"}]},{"ask":"下列哪一種立體最適合用柱座標？","options":[{"label":"繞 $z$ 軸對稱的立體，例如拋物面與平面圍成的碗","correct":true},{"label":"長方體 $[0,1]\\times[0,2]\\times[0,3]$","why":"邊界都是座標平面，直角座標三層都是常數，最簡單。"},{"label":"平面 $x+y+z=1$ 與三個座標平面圍成的四面體","why":"邊界是平面，直角座標的上下限是一次式；換成柱座標反而出現 $r\\cos\\theta+r\\sin\\theta$。"}]},{"ask":"用柱座標算半徑 $3$、高 $2$ 的圓柱體積 $\\int_0^{2\\pi}\\int_0^3\\int_0^2 r\\,dz\\,dr\\,d\\theta$：","options":[{"label":"$18\\pi$","correct":true},{"label":"$12\\pi$","why":"漏了 $r$：$\\int_0^3 dr=3$。正確是 $\\int_0^3 r\\,dr=\\frac{9}{2}$，再乘 $2$ 與 $2\\pi$。"},{"label":"$36\\pi$","why":"多乘了一個 $r$：$\\int_0^3 r^2\\,dr=9$。$dV$ 只有一個 $r$。"}]}],"practice":[{"id":"gap-int-triple-005","core":true},{"id":"lec-19-q3b","core":true},{"id":"lec-19-q2c","challenge":true,"note":"挑戰：球被挖掉圓柱，$z$ 從 $-\\sqrt{4-r^2}$ 到 $\\sqrt{4-r^2}$，$r$ 從 $1$ 到 $2$。"}]},"spherical-coordinates":{"id":"spherical-coordinates","prerequisites":["cylindrical-coordinates","jacobian-determinant"],"next":["vector-field"],"related":["triple-integral","parametric-surfaces"],"objectives":["用 $(\\rho,\\varphi,\\theta)$ 描述空間中的點，知道 $\\varphi$ 是從 $z$ 軸正向量起的角，範圍 $0$ 到 $\\pi$。","說出 $dV=\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta$ 的三個邊長從哪裡來。","把球、圓錐、冰淇淋筒形狀的區域寫成球座標的範圍並積分。"],"concept":[{"heading":"① 三個數：多遠、多斜、轉多少","body":["$\\rho={}$ 點到原點的距離（$\\rho\\ge 0$）。$\\varphi={}$ 從 $z$ 軸正向往下量到這個點的角（$0\\le\\varphi\\le\\pi$：$\\varphi=0$ 是北極方向，$\\frac{\\pi}{2}$ 是 $xy$ 平面，$\\pi$ 是南極方向）。$\\theta={}$ 跟柱座標一樣，繞 $z$ 軸轉的角。","注意：有些物理書把 $\\theta$、$\\varphi$ 的名字對調。本課程一律用上面的約定。"],"tex":["x=\\rho\\sin\\varphi\\cos\\theta,\\quad y=\\rho\\sin\\varphi\\sin\\theta,\\quad z=\\rho\\cos\\varphi,\\quad x^2+y^2+z^2=\\rho^2"]},{"heading":"② 小塊的三條邊","body":["$\\rho$ 增加 $\\Delta\\rho$：沿半徑走，長度 $\\Delta\\rho$。","$\\varphi$ 增加 $\\Delta\\varphi$：沿著半徑 $\\rho$ 的經線（大圓）走，長度 $\\rho\\Delta\\varphi$。","$\\theta$ 增加 $\\Delta\\theta$：沿著緯線走。緯線是一個圓，半徑是點到 $z$ 軸的距離 $\\rho\\sin\\varphi$，所以長度 $\\rho\\sin\\varphi\\,\\Delta\\theta$。","三條邊互相垂直，小塊近似一個長方體：$\\Delta V\\approx\\rho^2\\sin\\varphi\\,\\Delta\\rho\\,\\Delta\\varphi\\,\\Delta\\theta$。這是直觀，不是證明；用〈Jacobian 行列式〉算 $\\frac{\\partial(x,y,z)}{\\partial(\\rho,\\varphi,\\theta)}$ 的 $3\\times3$ 行列式，確實得到 $\\rho^2\\sin\\varphi$。"],"tex":["dV=\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta"]},{"heading":"③ 常見曲面","body":["球面 $x^2+y^2+z^2=a^2\\to\\rho=a$。","圓錐面 $z=\\sqrt{x^2+y^2}\\to\\varphi=\\frac{\\pi}{4}$（跟 $z$ 軸夾 $45^\\circ$）。","$xy$ 平面 $\\to\\varphi=\\frac{\\pi}{2}$；上半空間 $z\\ge 0\\to 0\\le\\varphi\\le\\frac{\\pi}{2}$。","立體以原點為中心、邊界是球面或圓錐面，或被積函數含 $x^2+y^2+z^2$ 時，用球座標。"]}],"workedExamples":[{"title":"球的體積","prompt":"半徑 $3$ 的球 $x^2+y^2+z^2\\le 9$ 的體積。","steps":["範圍：$0\\le\\rho\\le 3$、$0\\le\\varphi\\le\\pi$、$0\\le\\theta\\le 2\\pi$。三層上下限都是常數，可分離。","$\\int_0^3\\rho^2\\,d\\rho=9$；$\\int_0^\\pi\\sin\\varphi\\,d\\varphi=2$；$\\int_0^{2\\pi}d\\theta=2\\pi$。","相乘：$9\\cdot2\\cdot2\\pi=36\\pi$。跟 $\\frac{4}{3}\\pi\\cdot27=36\\pi$ 一致。"],"answer":"$36\\pi$"},{"title":"冰淇淋筒","prompt":"在圓錐 $z=\\sqrt{x^2+y^2}$ 上方、單位球 $x^2+y^2+z^2\\le 1$ 內部的立體體積。","steps":["圓錐上方是「跟 $z$ 軸夾角小於 $45^\\circ$」：$0\\le\\varphi\\le\\frac{\\pi}{4}$。球內：$0\\le\\rho\\le 1$。$\\theta$ 繞一整圈。","$V=\\int_0^{2\\pi}\\int_0^{\\pi/4}\\int_0^1\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta=2\\pi\\cdot\\frac{1}{3}\\cdot\\left[-\\cos\\varphi\\right]_0^{\\pi/4}$。","$\\left[-\\cos\\varphi\\right]_0^{\\pi/4}=1-\\frac{\\sqrt2}{2}$。","$V=\\frac{2\\pi}{3}\\left(1-\\frac{\\sqrt2}{2}\\right)=\\frac{\\pi(2-\\sqrt2)}{3}$。"],"answer":"$\\frac{\\pi(2-\\sqrt2)}{3}$"},{"title":"被積函數只跟距離有關","prompt":"$\\iiint_B e^{(x^2+y^2+z^2)^{3/2}}\\,dV$，$B$ 是單位球。","steps":["$(x^2+y^2+z^2)^{3/2}=\\rho^3$。積分 $=\\int_0^{2\\pi}\\int_0^\\pi\\int_0^1 e^{\\rho^3}\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta$。","最內層：令 $u=\\rho^3$，$du=3\\rho^2\\,d\\rho$：$\\int_0^1 e^{\\rho^3}\\rho^2\\,d\\rho=\\frac{e-1}{3}$。$dV$ 裡的 $\\rho^2$ 剛好配成換元。","乘上 $\\int\\sin\\varphi\\,d\\varphi=2$ 與 $2\\pi$：$\\frac{4\\pi(e-1)}{3}$。"],"answer":"$\\frac{4\\pi(e-1)}{3}$"}],"pitfalls":["漏了 $\\sin\\varphi$，或把 $\\rho^2$ 寫成 $\\rho$。","$\\varphi$ 積到 $2\\pi$：$\\varphi$ 只從 $0$ 到 $\\pi$，繞一圈的是 $\\theta$。","把 $\\theta$ 跟 $\\varphi$ 的角色搞混：圓錐是 $\\varphi={}$ 常數，不是 $\\theta={}$ 常數。","上半球寫成 $0\\le\\varphi\\le\\pi$。上半是 $0\\le\\varphi\\le\\frac{\\pi}{2}$。"],"checks":[{"ask":"球座標的 $dV$ 是？","options":[{"label":"$\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta$","correct":true},{"label":"$\\rho^2\\,d\\rho\\,d\\varphi\\,d\\theta$","why":"漏了 $\\sin\\varphi$。緯線圓的半徑是 $\\rho\\sin\\varphi$，靠近兩極時這條邊很短，小塊很小。"},{"label":"$\\rho\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta$","why":"經線方向的邊 $\\rho\\Delta\\varphi$ 也帶一個 $\\rho$，一共是 $\\rho^2$。"}]},{"ask":"圓錐面 $z=\\sqrt{x^2+y^2}$ 用球座標寫是？","options":[{"label":"$\\varphi=\\frac{\\pi}{4}$","correct":true},{"label":"$\\theta=\\frac{\\pi}{4}$","why":"$\\theta={}$ 常數 是一片繞 $z$ 軸的半平面。圓錐是「跟 $z$ 軸夾角固定」，那是 $\\varphi$。"},{"label":"$\\rho=1$","why":"$\\rho={}$ 常數 是球面。"}]},{"ask":"整顆球的 $\\varphi$ 範圍是？","options":[{"label":"$0\\le\\varphi\\le\\pi$","correct":true},{"label":"$0\\le\\varphi\\le 2\\pi$","why":"$\\varphi$ 從北極量到南極，$\\pi$ 就走完了；再走下去每個點會被算兩次。繞一圈的是 $\\theta$。"},{"label":"$0\\le\\varphi\\le\\frac{\\pi}{2}$","why":"那只到 $xy$ 平面，是上半球。"}]},{"ask":"$\\int_0^{2\\pi}\\int_0^\\pi\\int_0^2\\rho^2\\sin\\varphi\\,d\\rho\\,d\\varphi\\,d\\theta$ 是？","options":[{"label":"$\\frac{32\\pi}{3}$","correct":true},{"label":"$\\frac{16\\pi^2}{3}$","why":"漏了 $\\sin\\varphi$：$\\int_0^\\pi d\\varphi=\\pi$。正確是 $\\int_0^\\pi\\sin\\varphi\\,d\\varphi=2$。"},{"label":"$\\frac{16\\pi}{3}$","why":"那是上半球（$\\varphi$ 只到 $\\frac{\\pi}{2}$，$\\int\\sin\\varphi\\,d\\varphi=1$）。這裡 $\\varphi$ 到 $\\pi$。"}]}],"practice":[{"id":"gap-int-triple-006","core":true},{"id":"rel-hard-mv-004","core":true},{"id":"rel-hard-mv-003","core":true},{"id":"rel-boss-012","core":true},{"id":"lec-19-q3c"}]},"vector-field":{"id":"vector-field","prerequisites":["r2-r3","parametric-curves"],"next":["gradient-field"],"related":["gradient","work-line-integral","flux"],"objectives":["說出向量場是「每一點配一支箭頭」，並在幾個點上畫出它。","認得三種基本的樣子：均勻、向外發散、繞圈旋轉。","驗證一條曲線是不是向量場的流線：曲線的速度處處等於該點的箭頭。"],"concept":[{"heading":"① 每一點一支箭頭","body":["天氣圖上的風：每個地點都有一個風向與風速，畫成一支箭頭。把這個想法寫成函數：輸入一個點，輸出一個向量。","平面上寫成 $\\mathbf F(x,y)=\\langle P(x,y),Q(x,y)\\rangle$，空間中 $\\mathbf F(x,y,z)=\\langle P,Q,R\\rangle$。$P$、$Q$、$R$ 是普通的多變數函數，叫做分量。（向量也常寫成 $(P,Q)$，意思一樣。）"]},{"heading":"② 怎麼畫","body":["挑幾個點，算出 $\\mathbf F$，從那個點出發畫箭頭。箭頭太長會疊在一起，所以常常把所有箭頭等比例縮短；方向與相對長短才是重點。","例：$\\mathbf F=\\langle -y,x\\rangle$。在 $(1,0)$ 是 $\\langle 0,1\\rangle$（朝上），在 $(0,1)$ 是 $\\langle -1,0\\rangle$（朝左），在 $(-1,0)$ 是 $\\langle 0,-1\\rangle$（朝下）。連起來看，箭頭繞著原點逆時針轉。"]},{"heading":"③ 三種基本的樣子","body":["均勻場 $\\langle 0,1\\rangle$：到處都一樣，像穩定的風。","發散場 $\\langle x,y\\rangle$：每一點都從原點往外指，離越遠越長。","旋轉場 $\\langle -y,x\\rangle$：箭頭跟位置向量垂直（$\\langle -y,x\\rangle\\cdot\\langle x,y\\rangle=0$），長度等於到原點的距離，像一個轉盤上每一點的速度。","物理上的例子：流體速度場、重力場 $\\mathbf F=-GMm\\frac{\\mathbf r}{|\\mathbf r|^3}$（指向中心、大小與距離平方成反比）、電場。"]},{"heading":"④ 流線","body":["放一顆小粒子讓它順著場漂：它的路徑 $\\mathbf r(t)$ 處處滿足 $\\mathbf r'(t)=\\mathbf F(\\mathbf r(t))$，也就是速度永遠等於所在位置的箭頭。這條路徑叫流線（場線）。","之後的課會一直問兩件事：沿著一條曲線，場幫忙還是扯後腿（〈功的線積分〉）；穿過一張曲面，流出去多少（〈通量〉）。"]}],"workedExamples":[{"title":"旋轉場的兩個性質","prompt":"$\\mathbf F=\\langle -y,x\\rangle$。說明 $\\mathbf F$ 在每一點都跟位置向量垂直，而且 $|\\mathbf F|$ 等於到原點的距離。","steps":["位置向量是 $\\langle x,y\\rangle$。點積 $\\langle -y,x\\rangle\\cdot\\langle x,y\\rangle=-xy+xy=0$，所以互相垂直。","$|\\mathbf F|=\\sqrt{(-y)^2+x^2}=\\sqrt{x^2+y^2}$，正好是 $(x,y)$ 到原點的距離。","結論：箭頭都沿著以原點為中心的圓的切線方向，越外圈越長。"],"answer":"$\\mathbf F\\cdot\\langle x,y\\rangle=0$，$|\\mathbf F|=\\sqrt{x^2+y^2}$"},{"title":"驗證一條流線","prompt":"證明 $\\mathbf r(t)=\\langle 2\\cos t,2\\sin t\\rangle$ 是 $\\mathbf F=\\langle -y,x\\rangle$ 的流線。","steps":["速度：$\\mathbf r'(t)=\\langle -2\\sin t,2\\cos t\\rangle$。","在 $\\mathbf r(t)$ 這一點，$x=2\\cos t$、$y=2\\sin t$，$\\mathbf F=\\langle -y,x\\rangle=\\langle -2\\sin t,2\\cos t\\rangle$。","兩者處處相等，所以 $\\mathbf r(t)$ 是流線：半徑 $2$ 的圓，逆時針繞。"],"answer":"$\\mathbf r'(t)=\\mathbf F(\\mathbf r(t))$，是流線"},{"title":"重力型的場","prompt":"$\\mathbf F(x,y,z)=-\\frac{\\langle x,y,z\\rangle}{(x^2+y^2+z^2)^{3/2}}$。求 $\\mathbf F(0,0,2)$ 與它的長度。","steps":["在 $(0,0,2)$：$x^2+y^2+z^2=4$，$4^{3/2}=8$。","$\\mathbf F=-\\frac{\\langle 0,0,2\\rangle}{8}=\\left\\langle 0,0,-\\frac{1}{4}\\right\\rangle$，指向原點。","長度 $\\frac{1}{4}=\\frac{1}{2^2}$：大小與距離平方成反比。"],"answer":"$\\left\\langle 0,0,-\\frac{1}{4}\\right\\rangle$，長度 $\\frac{1}{4}$"}],"pitfalls":["把分量放錯位置：$\\langle P,Q\\rangle$ 的第一個是 $x$ 方向。","代點時代錯變數：$\\mathbf F=\\langle y,0\\rangle$ 在 $(3,2)$ 是 $\\langle 2,0\\rangle$。","箭頭從原點畫出去，而不是從那個點畫出去。","以為向量場的箭頭都是單位長度。"],"checks":[{"ask":"$\\mathbf F=\\langle y,0\\rangle$ 在點 $(3,2)$ 的值是？","options":[{"label":"$\\langle 2,0\\rangle$","correct":true},{"label":"$\\langle 3,0\\rangle$","why":"第一個分量是 $y$，不是 $x$。在 $(3,2)$ 的 $y$ 是 $2$。"},{"label":"$\\langle 0,2\\rangle$","why":"分量的位置放反了：$P=y$ 在前面（$x$ 方向），$Q=0$ 在後面。"}]},{"ask":"哪一個場的箭頭處處從原點往外指？","options":[{"label":"$\\langle x,y\\rangle$","correct":true},{"label":"$\\langle -y,x\\rangle$","why":"它跟位置向量垂直，箭頭繞著原點轉，不往外。"},{"label":"$\\langle y,x\\rangle$","why":"在 $(1,-1)$ 它是 $\\langle -1,1\\rangle$，指向原點那一側，不是往外。"}]},{"ask":"$\\mathbf F=\\langle -y,x\\rangle$ 在 $(3,4)$ 的箭頭長度是？","options":[{"label":"$5$","correct":true},{"label":"$7$","why":"長度是 $\\sqrt{4^2+3^2}$，不是分量的絕對值相加。"},{"label":"$1$","why":"向量場的箭頭不一定是單位向量；這個場的長度等於到原點的距離。"}]},{"ask":"向量場 $\\mathbf F$ 的流線是指？","options":[{"label":"一條曲線，在每一點的切線方向（速度）都等於 $\\mathbf F$","correct":true},{"label":"$\\mathbf F$ 的等高線","why":"向量場本身沒有「高度」可以畫等高線。梯度場的場線跟位勢的等高線垂直，兩者不是同一個東西。"},{"label":"把每支箭頭的尖端連起來的曲線","why":"箭頭的長短是縮放過的，尖端連線沒有意義。流線是粒子順著箭頭走出來的路徑。"}]}],"practice":[]},"gradient-field":{"id":"gradient-field","prerequisites":["vector-field","gradient","clairaut"],"next":["scalar-line-integral"],"related":["level-curves","conservative-fields","potential-function"],"objectives":["把一個函數 $f$ 的梯度 $\\nabla f$ 看成向量場，並說出它跟等高線的關係。","用交叉偏導數 $P_y$ 與 $Q_x$ 判斷一個場「不可能」是梯度場。","知道「是不是梯度場」為什麼重要：之後的線積分會因此變簡單。"],"concept":[{"heading":"① 梯度本身就是一個向量場","body":["〈梯度〉：$f(x,y)$ 在每一點有一個梯度 $\\nabla f=\\langle f_x,f_y\\rangle$。每一點配一個向量，這就是一個向量場，叫做 $f$ 的梯度場。","例：$f=x^2+y^2$，$\\nabla f=\\langle 2x,2y\\rangle$，正好是上一課的發散場放大 $2$ 倍。","三個變數也一樣：$\\nabla f=\\langle f_x,f_y,f_z\\rangle$ 是空間中的向量場，箭頭垂直於等值面 $f=c$。"]},{"heading":"② 圖像：垂直於等高線、指向上坡","body":["把 $f$ 當成地形高度。梯度場的箭頭處處垂直於等高線（〈圖形與等高線〉），指向 $f$ 增加的方向；等高線越密，坡越陡，箭頭越長。","所以畫梯度場有一個捷徑：先畫 $f$ 的等高線，再畫垂直穿過它們、往高處指的箭頭。"]},{"heading":"③ 反過來問：給一個場，它是誰的梯度？","body":["如果 $\\mathbf F=\\langle P,Q\\rangle=\\nabla f$，就說 $\\mathbf F$ 是梯度場，$f$ 叫做 $\\mathbf F$ 的位勢函數。這是之後〈保守場〉與〈位勢函數〉的主題。","物理書常寫 $\\mathbf F=-\\nabla U$（$U$ 是位能，力指向位能下降的方向）。數學上通常不帶負號，兩者只差 $f=-U$。"]},{"heading":"④ 一個必要條件：交叉偏導相等","body":["若 $\\mathbf F=\\nabla f$，$P=f_x$、$Q=f_y$，那 $P_y=f_{xy}$、$Q_x=f_{yx}$。$f$ 的二階偏導連續時，〈Clairaut 定理〉說兩者相等。所以：","$P_y\\ne Q_x$，$\\mathbf F$ 一定不是梯度場。","反過來，$P_y=Q_x$ 還不夠保證是梯度場，還要看定義域有沒有「洞」，這是〈保守場〉要處理的事。"]}],"workedExamples":[{"title":"算一個梯度場","prompt":"$f(x,y)=x^2y+y^3$，寫出梯度場 $\\nabla f$。","steps":["$f_x$：把 $y$ 當常數，得 $2xy$。","$f_y$：把 $x$ 當常數，得 $x^2+3y^2$。","$\\nabla f=\\langle 2xy,x^2+3y^2\\rangle$。"],"answer":"$\\langle 2xy,x^2+3y^2\\rangle$"},{"title":"垂直於等高線","prompt":"$f=x^2+y^2$。在 $(1,2)$ 驗證 $\\nabla f$ 跟經過該點的等高線垂直。","steps":["$\\nabla f(1,2)=\\langle 2,4\\rangle$。","經過 $(1,2)$ 的等高線是圓 $x^2+y^2=5$。圓在 $(1,2)$ 的切線方向跟半徑 $\\langle 1,2\\rangle$ 垂直，可以取 $\\langle -2,1\\rangle$。","$\\langle 2,4\\rangle\\cdot\\langle -2,1\\rangle=-4+4=0$，互相垂直。$\\langle 2,4\\rangle$ 指向圓外，也就是 $f$ 變大的方向。"],"answer":"點積為 $0$，垂直"},{"title":"不可能是梯度場","prompt":"$\\mathbf F=\\langle y,-x\\rangle$ 是不是某個 $f$ 的梯度場？","steps":["$P=y$、$Q=-x$。$P_y=1$，$Q_x=-1$。","兩者不相等。如果 $\\mathbf F=\\nabla f$ 且 $f$ 的二階偏導連續，必須 $P_y=Q_x$，矛盾。","所以 $\\mathbf F$ 不是任何（二階偏導連續的）$f$ 的梯度場。它是順時針繞圈的旋轉場。"],"answer":"不是"}],"pitfalls":["把 $\\nabla f$ 的兩個分量放反：第一個是 $f_x$。","以為梯度箭頭沿著等高線走；它是垂直穿過等高線。","看到 $P_y=Q_x$ 就斷定是梯度場，沒看定義域。","檢查時比的是 $P$ 與 $Q$ 本身，而不是交叉偏導數。"],"checks":[{"ask":"$\\nabla(xy)$ 是？","options":[{"label":"$\\langle y,x\\rangle$","correct":true},{"label":"$\\langle x,y\\rangle$","why":"$f_x$ 是把 $y$ 當常數對 $x$ 微分，得 $y$，放在第一個分量。"},{"label":"$\\langle 1,1\\rangle$","why":"$xy$ 對 $x$ 微分是 $y$，不是 $1$。"}]},{"ask":"梯度場 $\\nabla f$ 的箭頭跟 $f$ 的等高線是什麼關係？","options":[{"label":"垂直，指向 $f$ 增加的一側","correct":true},{"label":"相切，沿著等高線走","why":"沿著等高線走 $f$ 不變，變化率是 $0$；梯度指的是變化最快的方向，跟等高線垂直。"},{"label":"垂直，指向 $f$ 減少的一側","why":"梯度指向上坡。指向下坡的是 $-\\nabla f$。"}]},{"ask":"下列哪一個一定不是梯度場？","options":[{"label":"$\\langle -y,x\\rangle$","correct":true},{"label":"$\\langle y,x\\rangle$","why":"它是 $\\nabla(xy)$：$P_y=1=Q_x$。"},{"label":"$\\langle 2x,2y\\rangle$","why":"它是 $\\nabla(x^2+y^2)$。"}]},{"ask":"$\\mathbf F=\\langle P,Q\\rangle=\\nabla f$（$f$ 的二階偏導連續），為什麼 $P_y=Q_x$？","options":[{"label":"$P_y=f_{xy}$、$Q_x=f_{yx}$，混合偏導相等（Clairaut）","correct":true},{"label":"因為 $P=Q$","why":"$P$ 與 $Q$ 通常不相等（例如 $\\nabla(x^2y)=\\langle 2xy,x^2\\rangle$），相等的是交叉偏導數。"},{"label":"因為梯度場一定是常數場","why":"$\\nabla(x^2+y^2)=\\langle 2x,2y\\rangle$ 就不是常數。"}]}],"practice":[{"id":"exam-multi-003","core":true},{"id":"lec-20-m1","core":true},{"id":"vc-nab-006","note":"梯度的長度就是最大的方向變化率。"}]},"scalar-line-integral":{"id":"scalar-line-integral","prerequisites":["parametric-arc-length","parametric-curves"],"next":["work-line-integral"],"related":["center-of-mass"],"objectives":["說出 $\\int_C f\\,ds$ 的意思：沿曲線把「密度 $\\times$ 一小段長度」加起來，像一條鐵絲的質量。","把曲線參數化，用 $ds=|\\mathbf r'(t)|\\,dt$ 化成一般的定積分。","知道純量線積分跟曲線走的方向、參數化的選法都無關。"],"concept":[{"heading":"① 一條粗細不均的鐵絲","body":["鐵絲彎成曲線 $C$，每一點的線密度是 $f(x,y)$（每單位長度的質量）。總質量怎麼算？把鐵絲切成很多小段，每段長 $\\Delta s$，質量約 $f\\cdot\\Delta s$，加起來取極限。這就是 $\\int_C f\\,ds$。","$f=1$ 時，$\\int_C 1\\,ds$ 就是曲線的長度。$f\\ge 0$ 時另一個圖像：沿著 $C$ 立起一道高度 $f$ 的圍籬，積分是圍籬的面積。"]},{"heading":"② 化成定積分：$ds=|\\mathbf r'(t)|\\,dt$","body":["用參數式 $\\mathbf r(t)=\\langle x(t),y(t)\\rangle$，$a\\le t\\le b$ 描述 $C$。〈參數式弧長〉告訴我們：$t$ 增加 $dt$ 時，點走了 $|\\mathbf r'(t)|\\,dt$ 那麼長，$|\\mathbf r'(t)|=\\sqrt{x'^2+y'^2}$ 是速率。","被積函數 $f$ 也要代成 $t$：$f(x(t),y(t))$。於是："],"tex":["\\int_C f\\,ds=\\int_a^b f\\big(x(t),y(t)\\big)\\,\\big|\\mathbf r'(t)\\big|\\,dt"]},{"heading":"③ 三步驟","body":["1. 參數化 $C$，寫出 $t$ 的範圍。常用：線段 $(x_0,y_0)\\to(x_1,y_1)$ 用 $\\mathbf r(t)=(1-t)\\langle x_0,y_0\\rangle+t\\langle x_1,y_1\\rangle$，$0\\le t\\le 1$；半徑 $a$ 的圓用 $\\langle a\\cos t,a\\sin t\\rangle$；函數圖形 $y=g(x)$ 用 $\\langle t,g(t)\\rangle$。","2. 算 $|\\mathbf r'(t)|$。","3. 代入、積分。空間曲線一樣，只是多一個 $z(t)$。"]},{"heading":"④ 跟方向、參數化都無關","body":["$ds$ 是長度，永遠是正的。所以同一條曲線從哪一頭走到哪一頭，結果都一樣；換一個參數化（走快一點、慢一點），$|\\mathbf r'(t)|$ 跟 $dt$ 的變化互相抵消，結果也不變。","這一點下一課的〈功的線積分〉就不一樣了：那裡走反方向會變號。","$C$ 由幾段組成時（例如三角形的三個邊），每段各自參數化，積分相加。"]}],"workedExamples":[{"title":"上半圓","prompt":"$\\int_C(2+x^2y)\\,ds$，$C$ 是單位圓的上半部。","steps":["參數化：$\\mathbf r(t)=\\langle\\cos t,\\sin t\\rangle$，$0\\le t\\le\\pi$。","$\\mathbf r'(t)=\\langle -\\sin t,\\cos t\\rangle$，$|\\mathbf r'(t)|=1$。","$\\int_0^\\pi(2+\\cos^2t\\sin t)\\,dt=2\\pi+\\left[-\\frac{\\cos^3t}{3}\\right]_0^\\pi=2\\pi+\\frac{2}{3}$。"],"answer":"$2\\pi+\\frac{2}{3}$"},{"title":"線段：速率不是 $1$","prompt":"$\\int_C xy\\,ds$，$C$ 是從 $(0,0)$ 到 $(3,4)$ 的線段。","steps":["$\\mathbf r(t)=\\langle 3t,4t\\rangle$，$0\\le t\\le 1$。$|\\mathbf r'(t)|=\\sqrt{9+16}=5$。","$xy=12t^2$。","$\\int_0^1 12t^2\\cdot5\\,dt=60\\cdot\\frac{1}{3}=20$。","從 $(3,4)$ 走回 $(0,0)$：$\\mathbf r(t)=\\langle 3-3t,4-4t\\rangle$，速率還是 $5$，算出來一樣是 $20$。"],"answer":"$20$"},{"title":"分段的曲線","prompt":"$\\int_C(x+y)\\,ds$，$C$ 是頂點 $(0,0)$、$(1,0)$、$(0,1)$ 的三角形邊界。","steps":["三條邊各自參數化，最後相加。方向不影響純量線積分，每段挑順手的方向就好。","$C_1$：$(0,0)\\to(1,0)$，$\\mathbf r=\\langle t,0\\rangle$，$|\\mathbf r'|=1$，$x+y=t$。$\\int_0^1 t\\,dt=\\frac{1}{2}$。","$C_2$：$(1,0)\\to(0,1)$，$\\mathbf r=\\langle 1-t,t\\rangle$，$|\\mathbf r'|=\\sqrt2$，$x+y=1$。$\\int_0^1\\sqrt2\\,dt=\\sqrt2$。","$C_3$：$(0,1)\\to(0,0)$，$\\mathbf r=\\langle 0,1-t\\rangle$，$|\\mathbf r'|=1$，$x+y=1-t$。$\\int_0^1(1-t)\\,dt=\\frac{1}{2}$。","合計 $1+\\sqrt2$。"],"answer":"$1+\\sqrt2$"}],"pitfalls":["漏了 $|\\mathbf r'(t)|$，直接把 $ds$ 換成 $dt$。","$|\\mathbf r'(t)|$ 忘了開根號，乘成 $x'^2+y'^2$。","$f$ 沒有代成 $t$ 的函數，留著 $x$、$y$ 就積分。","以為走反方向會變號；純量線積分不會。"],"checks":[{"ask":"$\\mathbf r(t)=\\langle 3\\cos t,3\\sin t\\rangle$ 時，$ds$ 等於？","options":[{"label":"$3\\,dt$","correct":true},{"label":"$dt$","why":"只有單位圓的速率是 $1$。半徑 $3$ 時 $|\\mathbf r'(t)|=\\sqrt{9\\sin^2t+9\\cos^2t}=3$。"},{"label":"$9\\,dt$","why":"那是 $|\\mathbf r'(t)|^2$，忘了開根號。"}]},{"ask":"同一條曲線改成反方向走，$\\int_C f\\,ds$ 會？","options":[{"label":"不變","correct":true},{"label":"變號","why":"變號的是向量場的線積分 $\\int\\mathbf F\\cdot d\\mathbf r$。$ds$ 是長度，永遠是正的。"},{"label":"變成 $0$","why":"沒有理由抵消：每一小段的 $f\\,\\Delta s$ 都一樣，只是加的順序不同。"}]},{"ask":"$C$ 是半徑 $3$ 的整個圓，$\\int_C 1\\,ds$ 是？","options":[{"label":"$6\\pi$","correct":true},{"label":"$2\\pi$","why":"漏了 $|\\mathbf r'(t)|=3$：$\\int_0^{2\\pi}3\\,dt=6\\pi$，就是圓周長。"},{"label":"$9\\pi$","why":"那是圓的面積公式 $\\pi r^2$。$\\int 1\\,ds$ 是長度，不是面積。"}]},{"ask":"$C$ 是從 $(0,0)$ 到 $(3,4)$ 的線段，$\\int_C y\\,ds$ 是？","options":[{"label":"$10$","correct":true},{"label":"$2$","why":"漏了 $|\\mathbf r'(t)|=5$：$\\int_0^1 4t\\,dt=2$，還要乘 $5$。"},{"label":"$50$","why":"乘了 $|\\mathbf r'(t)|^2=25$，沒開根號。"}]}],"practice":[{"id":"vc-line-001","core":true},{"id":"vc-line-002","core":true},{"id":"vc-line-003","core":true},{"id":"lec-20-q1a","core":true},{"id":"vc-line-004","note":"空間螺旋線：$|\\mathbf r'(t)|=\\sqrt2$。"}]},"work-line-integral":{"id":"work-line-integral","prerequisites":["scalar-line-integral","vector-field","work"],"next":["conservative-fields"],"related":["path-independence"],"objectives":["說出 $\\int_C\\mathbf F\\cdot d\\mathbf r$ 是「沿著路徑，力在前進方向上的分量 $\\times$ 一小段距離」的總和。","用參數式算：$\\int_a^b\\mathbf F(\\mathbf r(t))\\cdot\\mathbf r'(t)\\,dt$；也會讀 $\\int_C P\\,dx+Q\\,dy$ 的寫法。","知道走反方向會變號，而且同樣的起點終點、不同的路徑，答案可能不同。"],"concept":[{"heading":"① 從「力 $\\times$ 距離」開始","body":["〈功〉：定力沿直線，功 $={}$ 力 $\\times$ 距離。力的方向跟位移不同時，只有沿著位移的分量在做功：$W=\\mathbf F\\cdot\\mathbf d$（點積）。","現在力是一個場 $\\mathbf F(x,y)$，路徑是曲線 $C$。切成很多小段，每段位移 $\\Delta\\mathbf r$，功約 $\\mathbf F\\cdot\\Delta\\mathbf r$，加起來取極限，記成 $\\int_C\\mathbf F\\cdot d\\mathbf r$。"]},{"heading":"② 化成定積分","body":["參數化 $\\mathbf r(t)$，$a\\le t\\le b$，方向跟 $C$ 一致（$t$ 增加就是往前走）。$d\\mathbf r=\\mathbf r'(t)\\,dt$。$\\mathbf F$ 要先代進曲線上的點："],"tex":["\\int_C \\mathbf F\\cdot d\\mathbf r=\\int_a^b \\mathbf F\\big(\\mathbf r(t)\\big)\\cdot\\mathbf r'(t)\\,dt"]},{"heading":"③ 另外兩種寫法","body":["$\\mathbf F=\\langle P,Q\\rangle$、$d\\mathbf r=\\langle dx,dy\\rangle$，點積展開成 $\\int_C P\\,dx+Q\\,dy$。看到這種寫法，就代 $x=x(t)$、$y=y(t)$、$dx=x'(t)\\,dt$、$dy=y'(t)\\,dt$。","也可以寫成 $\\int_C\\mathbf F\\cdot\\mathbf T\\,ds$，$\\mathbf T$ 是單位切向量：只取 $\\mathbf F$ 沿著前進方向的分量，再做〈純量線積分〉。這個寫法最能看出意義：$\\mathbf F$ 跟路徑垂直的地方不做功。"]},{"heading":"④ 方向很重要","body":["反方向走，每一段 $d\\mathbf r$ 都變號，所以 $\\int_{-C}\\mathbf F\\cdot d\\mathbf r=-\\int_C\\mathbf F\\cdot d\\mathbf r$。這跟純量線積分不同。","只要方向相同，換參數化（走快走慢）答案不變。","但同樣起點終點、不同路徑，答案一般不同（範例 2）。哪些場「只看起點終點」，是〈路徑無關〉的主題。"]}],"workedExamples":[{"title":"順著旋轉場繞一圈","prompt":"$\\oint_C\\mathbf F\\cdot d\\mathbf r$，$\\mathbf F=\\langle -y,x\\rangle$，$C$ 是單位圓，逆時針。","steps":["$\\mathbf r(t)=\\langle\\cos t,\\sin t\\rangle$，$0\\le t\\le 2\\pi$（逆時針）。$\\mathbf r'(t)=\\langle -\\sin t,\\cos t\\rangle$。","曲線上 $\\mathbf F=\\langle -\\sin t,\\cos t\\rangle$。","$\\mathbf F\\cdot\\mathbf r'=\\sin^2t+\\cos^2t=1$。","$\\int_0^{2\\pi}1\\,dt=2\\pi$。力處處順著前進方向推，所以功是正的。"],"answer":"$2\\pi$"},{"title":"同樣起點終點，不同路徑","prompt":"$\\int_C y^2\\,dx+x\\,dy$，從 $(0,0)$ 到 $(1,1)$。(a) 沿 $y=x$；(b) 沿 $y=x^2$；(c) 沿 $y=x$ 但從 $(1,1)$ 走回 $(0,0)$。","steps":["(a) $\\mathbf r(t)=\\langle t,t\\rangle$：$dx=dy=dt$。$\\int_0^1(t^2+t)\\,dt=\\frac{1}{3}+\\frac{1}{2}=\\frac{5}{6}$。","(b) $\\mathbf r(t)=\\langle t,t^2\\rangle$：$dx=dt$、$dy=2t\\,dt$。$y^2\\,dx+x\\,dy=t^4\\,dt+t\\cdot2t\\,dt$。$\\int_0^1(t^4+2t^2)\\,dt=\\frac{1}{5}+\\frac{2}{3}=\\frac{13}{15}$。","(a) 與 (b) 起點終點一樣，答案不同：這個場的功跟路徑有關。","(c) 是 (a) 反過來走：$-\\frac{5}{6}$。"],"answer":"(a) $\\frac{5}{6}$　(b) $\\frac{13}{15}$　(c) $-\\frac{5}{6}$"}],"pitfalls":["把 $d\\mathbf r$ 寫成 $|\\mathbf r'(t)|\\,dt$，做成純量線積分。","$\\mathbf F$ 沒代成 $t$ 就跟 $\\mathbf r'(t)$ 點積，或拿位置 $\\mathbf r(t)$ 去點積。","參數方向跟題目指定的方向相反，忘了補負號。","$\\int P\\,dx+Q\\,dy$ 只換了 $dx$，忘了 $dy$ 也要換成 $y'(t)\\,dt$。"],"checks":[{"ask":"同一條路徑改成反方向走，$\\int_C\\mathbf F\\cdot d\\mathbf r$ 會？","options":[{"label":"變號","correct":true},{"label":"不變","why":"不變的是純量線積分 $\\int f\\,ds$。這裡每一段位移 $d\\mathbf r$ 都反向，點積都變號。"},{"label":"變成 $0$","why":"去程與回程合起來才是 $0$；單獨反向只是變號。"}]},{"ask":"$\\mathbf F$ 在路徑上每一點都跟路徑垂直，功是？","options":[{"label":"$0$","correct":true},{"label":"$|\\mathbf F|$ 乘以路徑長","why":"那是 $\\mathbf F$ 處處順著路徑時的值。垂直時 $\\mathbf F\\cdot\\mathbf T=0$，完全不做功。"},{"label":"無法判斷","why":"$\\mathbf F\\cdot\\mathbf T$ 處處為 $0$，積分就是 $0$，不需要其他資訊。"}]},{"ask":"$\\oint_C x\\,dy$，$C$：$\\mathbf r(t)=\\langle\\cos t,\\sin t\\rangle$，$0\\le t\\le 2\\pi$，是？","options":[{"label":"$\\pi$","correct":true},{"label":"$0$","why":"$x\\,dy=\\cos t\\cdot\\cos t\\,dt=\\cos^2t\\,dt$，不是 $\\cos t\\,dt$；$\\cos^2t$ 不會抵消。"},{"label":"$2\\pi$","why":"$\\cos^2t$ 在一圈上的平均是 $\\frac{1}{2}$，不是 $1$：$\\int_0^{2\\pi}\\cos^2t\\,dt=\\pi$。"}]},{"ask":"$\\int_C\\mathbf F\\cdot d\\mathbf r$ 用參數式寫，被積函數是？","options":[{"label":"$\\mathbf F(\\mathbf r(t))\\cdot\\mathbf r'(t)$","correct":true},{"label":"$\\mathbf F(\\mathbf r(t))\\,|\\mathbf r'(t)|$","why":"那是把 $d\\mathbf r$ 當成 $ds$ 的純量寫法，而且 $\\mathbf F$ 是向量，不能直接乘一個長度當答案。"},{"label":"$\\mathbf F(t)\\cdot\\mathbf r(t)$","why":"$\\mathbf F$ 要先代進曲線上的點 $\\mathbf r(t)$；跟它點積的是速度 $\\mathbf r'(t)$，不是位置 $\\mathbf r(t)$。"}]}],"practice":[{"id":"vc-work-001","core":true},{"id":"vc-work-003","core":true},{"id":"vc-work-004","core":true},{"id":"lec-20-q1b","core":true},{"id":"lec-20-q1c","core":true},{"id":"vc-work-002"}]},"conservative-fields":{"id":"conservative-fields","prerequisites":["gradient-field","work-line-integral"],"next":["potential-function"],"related":["path-independence","green-theorem","curl","clairaut"],"objectives":["說出保守場的定義（$\\mathbf F=\\nabla f$），以及它跟「繞一圈功為 $0$」「功只看起點終點」的關係。","用 $P_y=Q_x$（三維：三組交叉偏導相等）檢驗，並說清楚這個檢驗什麼時候夠、什麼時候不夠。","認得反例 $\\mathbf F=\\frac{\\langle -y,x\\rangle}{x^2+y^2}$：交叉偏導相等，繞原點一圈卻得 $2\\pi$。"],"concept":[{"heading":"① 定義","body":["在一個區域 $D$ 上，如果存在函數 $f$ 使得 $\\mathbf F=\\nabla f$，就說 $\\mathbf F$ 在 $D$ 上是保守場，$f$ 是它的位勢函數。","「保守」這個名字來自物理：重力、彈力這類力做的功可以全部存回位能，繞一圈回到原點，能量不多也不少。"]},{"heading":"② 三件事彼此等價","body":["設 $D$ 是開集而且連通（任兩點可以用 $D$ 裡的路徑連起來），$\\mathbf F$ 在 $D$ 上連續。下面三件事彼此等價：","(1) $\\mathbf F$ 在 $D$ 上是保守場。(2) $D$ 裡的線積分 $\\int_C\\mathbf F\\cdot d\\mathbf r$ 只跟起點、終點有關。(3) $D$ 裡任何封閉曲線上 $\\oint_C\\mathbf F\\cdot d\\mathbf r=0$。","(1) $\\Rightarrow$ (2) 與 (2) $\\Rightarrow$ (1) 都在〈路徑無關〉說明；(2) $\\Leftrightarrow$ (3) 是因為兩條同起點同終點的路徑，一去一回正好接成一條封閉曲線。"]},{"heading":"③ 檢驗：交叉偏導","body":["〈梯度場〉已經看過：$\\mathbf F=\\langle P,Q\\rangle=\\nabla f$（$f$ 的二階偏導連續）一定有 $P_y=Q_x$。這是必要條件：不相等就一定不保守。","什麼時候它也是充分條件？當 $D$ 是單連通區域、$P$、$Q$ 的一階偏導連續時：$P_y=Q_x$ 就保證 $\\mathbf F$ 在 $D$ 上保守。","單連通的白話：$D$ 連通，而且 $D$ 裡任何一條封閉曲線都能在 $D$ 裡面連續縮成一點。平面上就是「沒有洞」。整個平面、上半平面、圓盤都是；去掉原點的平面、圓環都不是。","三維：$\\mathbf F=\\langle P,Q,R\\rangle$，條件是 $P_y=Q_x$、$P_z=R_x$、$Q_z=R_y$，合起來就是〈旋度〉為 $0$。注意：$\\mathbb{R}^3$ 去掉一個點仍然單連通，去掉一整條直線就不是。"]},{"heading":"④ 洞為什麼會壞事","body":["$\\mathbf F=\\frac{\\langle -y,x\\rangle}{x^2+y^2}$ 在原點沒有定義，$D={}$ 平面去掉原點。算出來 $P_y=Q_x$，但沿單位圓逆時針一圈的功是 $2\\pi\\ne 0$（範例 2），所以它在 $D$ 上不保守。","直觀理由要等〈Green 定理〉：$\\oint$ 等於曲線圍住的區域上 $Q_x-P_y$ 的積分，前提是那整塊區域都在 $\\mathbf F$ 的定義範圍內。圓圍住了原點，原點不在 $D$ 裡，Green 用不上，交叉偏導相等也就推不出 $0$。"]}],"workedExamples":[{"title":"檢驗一個平面場","prompt":"$\\mathbf F=\\langle 2xy+3,x^2-4y\\rangle$ 在 $\\mathbb{R}^2$ 上是不是保守場？","steps":["$P=2xy+3$，$P_y=2x$。$Q=x^2-4y$，$Q_x=2x$。","$P_y=Q_x$ 處處成立，$P$、$Q$ 的偏導連續。","定義域是整個 $\\mathbb{R}^2$，單連通。所以 $\\mathbf F$ 是保守場。下一課〈位勢函數〉會把 $f$ 找出來。"],"answer":"是"},{"title":"交叉偏導相等，卻不保守","prompt":"$\\mathbf F=\\left\\langle -\\frac{y}{x^2+y^2},\\frac{x}{x^2+y^2}\\right\\rangle$，定義在平面去掉原點。檢查 $P_y$ 與 $Q_x$，再算沿單位圓逆時針一圈的功。","steps":["$P_y$：商的微分，$\\frac{-(x^2+y^2)+y\\cdot2y}{(x^2+y^2)^2}=\\frac{y^2-x^2}{(x^2+y^2)^2}$。","$Q_x$：$\\frac{(x^2+y^2)-x\\cdot2x}{(x^2+y^2)^2}=\\frac{y^2-x^2}{(x^2+y^2)^2}$。兩者相等。","單位圓 $\\mathbf r(t)=\\langle\\cos t,\\sin t\\rangle$：$x^2+y^2=1$，$\\mathbf F=\\langle -\\sin t,\\cos t\\rangle$，$\\mathbf r'=\\langle -\\sin t,\\cos t\\rangle$，$\\mathbf F\\cdot\\mathbf r'=1$。","$\\oint=\\int_0^{2\\pi}1\\,dt=2\\pi\\ne 0$。封閉曲線功不為 $0$，$\\mathbf F$ 在這個定義域上不是保守場。問題出在原點這個洞。"],"answer":"$P_y=Q_x$，但 $\\oint=2\\pi$，不保守"}],"pitfalls":["拿 $P$ 與 $Q$ 比大小；要比的是 $P_y$ 與 $Q_x$。","看到 $P_y=Q_x$ 就說保守，沒檢查定義域有沒有洞。","$P_y\\ne Q_x$ 卻還去找位勢函數：一定找不到。","以為「去掉一個點」在三維也會壞事；$\\mathbb{R}^3$ 去掉一點仍然單連通。"],"checks":[{"ask":"$\\mathbf F=\\langle y,x\\rangle$ 在 $\\mathbb{R}^2$ 上是保守場嗎？","options":[{"label":"是：$P_y=Q_x=1$，而且 $\\mathbb{R}^2$ 單連通","correct":true},{"label":"不是，因為 $P\\ne Q$","why":"檢驗比的是交叉偏導 $P_y$ 與 $Q_x$，不是 $P$ 與 $Q$ 本身。"},{"label":"無法判斷，必須先找到 $f$","why":"在單連通區域上，$P_y=Q_x$ 加上偏導連續就足以保證保守，不必先找 $f$（雖然 $f=xy$ 很好找）。"}]},{"ask":"$\\mathbf F=\\frac{\\langle -y,x\\rangle}{x^2+y^2}$ 有 $P_y=Q_x$，沿單位圓一圈卻得 $2\\pi$。正確的結論是？","options":[{"label":"$\\mathbf F$ 在平面去掉原點上不是保守場；$P_y=Q_x$ 在有洞的區域上不夠","correct":true},{"label":"一定是算錯了，答案應該是 $0$","why":"計算沒錯：$\\mathbf F\\cdot\\mathbf r'$ 在單位圓上恆為 $1$。交叉偏導相等只在單連通區域上保證保守。"},{"label":"$P_y=Q_x$ 就保證保守，所以 $\\mathbf F$ 是保守場","why":"封閉曲線上的功不是 $0$，直接違反保守場的性質。缺的條件是單連通。"}]},{"ask":"下列哪一個區域是單連通的？","options":[{"label":"上半平面 $y>0$","correct":true},{"label":"平面去掉原點","why":"繞原點的圓縮不成一點（會卡在洞上）。"},{"label":"圓環 $1<x^2+y^2<4$","why":"中間有洞，繞一圈的曲線縮不掉。"}]},{"ask":"$\\mathbf F=\\langle ay+x,3x+y\\rangle$ 在 $\\mathbb{R}^2$ 上是保守場，$a$ 是多少？","options":[{"label":"$3$","correct":true},{"label":"$1$","why":"$P_y=a$、$Q_x=3$，要相等。$1$ 是 $P$ 裡 $x$ 的係數，跟檢驗無關。"},{"label":"$0$","why":"$a=0$ 時 $P_y=0\\ne Q_x=3$，反而不保守。"}]}],"practice":[{"id":"lec-20-m1","core":true},{"id":"vc-cons-003","core":true},{"id":"vc-nab-011","core":true,"note":"三維：算旋度，三個分量都是 $0$。"},{"id":"rel-hard-der-009","core":true,"note":"算出來是 $0$；想想為什麼這個場仍然不是保守場。"},{"id":"mob-nabla-009"},{"id":"lec-20-m5"}]},"potential-function":{"id":"potential-function","prerequisites":["conservative-fields","partial-derivatives"],"next":["path-independence"],"related":["exact-equations"],"objectives":["用「先對 $x$ 積分、留一個 $g(y)$、再對 $y$ 微分比對」的方法找出位勢函數 $f$。","三個變數時把同樣的方法多做一輪。","比對時若 $g'$ 出現 $x$，知道這代表 $\\mathbf F$ 不是保守場。"],"concept":[{"heading":"① 目標","body":["已經用〈保守場〉的檢驗確定 $\\mathbf F=\\langle P,Q\\rangle$ 是保守場，現在要找 $f$ 使得 $f_x=P$、$f_y=Q$。這等於同時解兩個偏微分方程。","$f$ 只決定到差一個常數：$f$ 與 $f+5$ 的梯度一樣。","找到 $f$ 有什麼好處？下一課〈路徑無關〉會說：$\\int_C\\mathbf F\\cdot d\\mathbf r=f($終點$)-f($起點$)$。線積分不用參數化，代兩個點就好。"]},{"heading":"② 積分「常數」其實是函數","body":["從 $f_x=P$ 出發，對 $x$ 積分。關鍵：對 $x$ 偏微分時，任何只含 $y$ 的東西都會變成 $0$。所以積分出來的「常數」可以是任意的 $g(y)$：","$f(x,y)=\\int P\\,dx+g(y)$。","這個 $g(y)$ 還不知道是誰，要靠第二個條件 $f_y=Q$ 決定。"]},{"heading":"③ 四個步驟（二維）","body":["1. 檢驗 $P_y=Q_x$（不相等就停，不存在 $f$）。","2. $f=\\int P\\,dx+g(y)$。","3. 把這個 $f$ 對 $y$ 偏微分，令它等於 $Q$，解出 $g'(y)$。$g'(y)$ 只能含 $y$；如果還有 $x$，表示前面算錯或 $\\mathbf F$ 根本不保守。","4. 積出 $g(y)$，寫出 $f$，最後驗算 $\\nabla f=\\mathbf F$。"]},{"heading":"④ 三維：多一輪","body":["$f=\\int P\\,dx+g(y,z)$，「常數」變成 $y$、$z$ 的函數。","對 $y$ 微分比對 $Q$，得到 $g_y$，積出 $g=\\dots+h(z)$。","再對 $z$ 微分比對 $R$，決定 $h(z)$。每一輪都把「還不知道的部分」縮小一個變數。"]},{"heading":"⑤ 跟其他課的關係","body":["同一套「積分、留函數、微分比對」的操作，在微分方程裡解〈正合方程〉時會再出現一次。"],"collapsible":true}],"workedExamples":[{"title":"二維","prompt":"$\\mathbf F=\\langle 2xy+3,x^2-4y\\rangle$。找位勢函數 $f$。","steps":["檢驗：$P_y=2x=Q_x$。","對 $x$ 積分：$f=\\int(2xy+3)\\,dx=x^2y+3x+g(y)$。","對 $y$ 微分：$f_y=x^2+g'(y)$。令它等於 $Q=x^2-4y$，得 $g'(y)=-4y$（只含 $y$，沒問題）。","$g(y)=-2y^2+K$。取 $K=0$：$f=x^2y+3x-2y^2$。","驗算：$f_x=2xy+3$，$f_y=x^2-4y$。"],"answer":"$f=x^2y+3x-2y^2$（$+$ 常數）"},{"title":"三維","prompt":"$\\mathbf F=\\langle y^2,2xy+e^{3z},3y\\,e^{3z}\\rangle$。找位勢函數 $f$。","steps":["對 $x$ 積分：$f=xy^2+g(y,z)$。","對 $y$ 微分比對 $Q$：$2xy+g_y=2xy+e^{3z}$，得 $g_y=e^{3z}$，所以 $g=y\\,e^{3z}+h(z)$。","現在 $f=xy^2+y\\,e^{3z}+h(z)$。對 $z$ 微分比對 $R$：$3y\\,e^{3z}+h'(z)=3y\\,e^{3z}$，$h'=0$，$h$ 是常數。","$f=xy^2+y\\,e^{3z}$。驗算三個偏導數都對。"],"answer":"$f=xy^2+y\\,e^{3z}$（$+$ 常數）"},{"title":"找不到的時候會發生什麼","prompt":"$\\mathbf F=\\langle y,2x\\rangle$。硬做位勢函數會怎樣？","steps":["對 $x$ 積分：$f=xy+g(y)$。","對 $y$ 微分：$x+g'(y)$，令它等於 $2x$，得 $g'(y)=x$。","$g'(y)$ 應該只跟 $y$ 有關，卻出現 $x$：矛盾，不存在這樣的 $f$。","跟交叉偏導的檢驗一致：$P_y=1\\ne Q_x=2$。先檢驗，可以省掉這一趟。"],"answer":"不存在位勢函數"}],"pitfalls":["對 $x$ 積分後只加常數 $C$，而不是 $g(y)$。","把 $\\int P\\,dx$ 與 $\\int Q\\,dy$ 直接相加：兩邊都有的項（像 $x^2y$）會被算兩次。","$g'(y)$ 裡還有 $x$ 卻繼續積下去。","忘了最後驗算 $\\nabla f=\\mathbf F$。"],"checks":[{"ask":"$\\mathbf F=\\langle 2x,2y\\rangle$ 的位勢函數是？","options":[{"label":"$x^2+y^2$","correct":true},{"label":"$2x+2y$","why":"那是把分量加起來。要的是 $f_x=2x$、$f_y=2y$ 的 $f$。"},{"label":"$x^2y^2$","why":"$\\nabla(x^2y^2)=\\langle 2xy^2,2x^2y\\rangle$，不是 $\\langle 2x,2y\\rangle$。"}]},{"ask":"$f_x=P$，對 $x$ 積分之後要加上的是？","options":[{"label":"$g(y)$：一個只含 $y$ 的函數","correct":true},{"label":"常數 $C$","why":"對 $x$ 偏微分時，任何只含 $y$ 的函數都變成 $0$，所以「常數」可以是任意的 $g(y)$。"},{"label":"$g(x)$","why":"含 $x$ 的函數對 $x$ 偏微分不會消失，不能當成積分「常數」。"}]},{"ask":"比對時得到 $g'(y)=x$，代表？","options":[{"label":"$\\mathbf F$ 不是保守場（或前面算錯），不存在位勢函數","correct":true},{"label":"再對 $y$ 積一次，得 $g=xy$","why":"$g$ 規定只能含 $y$。出現 $x$ 表示兩個條件 $f_x=P$、$f_y=Q$ 互相矛盾。"},{"label":"把 $g$ 改成 $g(x,y)$ 就好","why":"這樣 $f_x$ 也會跟著變，第一個條件 $f_x=P$ 就被破壞了。"}]},{"ask":"$\\mathbf F=\\langle y\\cos(xy),x\\cos(xy)\\rangle$ 的位勢函數是？","options":[{"label":"$\\sin(xy)$","correct":true},{"label":"$\\cos(xy)$","why":"$\\nabla\\cos(xy)=-\\sin(xy)\\langle y,x\\rangle$，函數與正負號都不對。"},{"label":"$xy\\sin(xy)$","why":"它對 $x$ 的偏導是 $y\\sin(xy)+xy^2\\cos(xy)$，不是 $y\\cos(xy)$。"}]}],"practice":[{"id":"lec-20-q2b","core":true},{"id":"vc-cons-001","core":true,"note":"先找 $f$，再用 $f($終點$)-f($起點$)$（下一課的方法）。"},{"id":"vc-cons-004","core":true}]},"path-independence":{"id":"path-independence","prerequisites":["potential-function","multivariable-chain-rule","ftc-part2"],"next":["green-theorem"],"related":["conservative-fields","work-line-integral","fundamental-theorems-unified","total-differential"],"objectives":["會用線積分基本定理：$\\int_C\\nabla f\\cdot d\\mathbf r=f($終點$)-f($起點$)$，並說出它的證明只用連鎖律加微積分基本定理。","知道保守場沿封閉曲線的功是 $0$，而且反過來，路徑無關的場一定保守。","看到功跟路徑有關，能斷定場不保守。"],"concept":[{"heading":"① 一維的基本定理，搬到曲線上","body":["〈微積分基本定理 II〉：$\\int_a^b F'(x)\\,dx=F(b)-F(a)$。導數積起來，只剩兩端的值。","直觀：沿著曲線走一小步 $\\Delta\\mathbf r$，$f$ 大約變化 $\\nabla f\\cdot\\Delta\\mathbf r$（〈全微分〉）。把每一小步的變化加起來，就是 $f$ 從起點到終點總共變了多少，中間怎麼繞都一樣。","曲線版：$C$ 是從 $A$ 到 $B$ 的分段光滑曲線，$f$ 的梯度在一個包含 $C$ 的開集上連續。那麼"],"tex":["\\int_C \\nabla f\\cdot d\\mathbf r=f(B)-f(A)"]},{"heading":"② 為什麼：兩行證明","body":["參數化 $\\mathbf r(t)$，$a\\le t\\le b$，$\\mathbf r(a)=A$、$\\mathbf r(b)=B$。由〈多變數連鎖律〉，$\\frac{d}{dt}f(\\mathbf r(t))=f_x\\,x'+f_y\\,y'=\\nabla f(\\mathbf r(t))\\cdot\\mathbf r'(t)$。","所以 $\\int_C\\nabla f\\cdot d\\mathbf r=\\int_a^b\\frac{d}{dt}f(\\mathbf r(t))\\,dt=f(\\mathbf r(b))-f(\\mathbf r(a))$，最後一步就是一維的基本定理。分段光滑時每段做一次，中間的端點互相抵消。"]},{"heading":"③ 三個推論","body":["路徑無關：保守場 $\\mathbf F=\\nabla f$ 的功只看起點與終點，跟中間怎麼走無關。","封閉曲線：起點等於終點，所以 $\\oint_C\\nabla f\\cdot d\\mathbf r=0$。","物理：重力做的功 $={}$ 位能的減少量，跟走哪條路無關，這就是能量守恆。","實際做題：先確認 $\\mathbf F$ 保守、找到 $f$（〈位勢函數〉），然後代兩個點。不必參數化。"]},{"heading":"④ 反方向也成立：路徑無關 $\\Rightarrow$ 保守（給想知道的人）","body":["設 $D$ 是開集而且連通，$\\mathbf F$ 連續，而且 $\\mathbf F$ 在 $D$ 裡的線積分跟路徑無關。固定一點 $A$，定義 $f(x,y)={}$ 從 $A$ 到 $(x,y)$ 的任一路徑上 $\\int\\mathbf F\\cdot d\\mathbf r$（路徑無關，所以定義合理）。","算 $f_x$：從 $(x,y)$ 再水平走一小段到 $(x+h,y)$，$f(x+h,y)-f(x,y)=\\int_x^{x+h}P(s,y)\\,ds$，除以 $h$ 讓 $h\\to0$，得 $f_x=P$。同理 $f_y=Q$。所以 $\\mathbf F=\\nabla f$。","這說明〈保守場〉那三件事確實等價。"],"collapsible":true}],"workedExamples":[{"title":"代兩個點","prompt":"$\\int_C(2xy+3)\\,dx+(x^2-4y)\\,dy$，$C$ 是從 $(0,0)$ 到 $(1,2)$ 的任意平滑曲線。","steps":["上一課找過位勢函數：$f=x^2y+3x-2y^2$。","答案 $=f(1,2)-f(0,0)=(2+3-8)-0=-3$。","驗算：沿直線 $\\mathbf r(t)=\\langle t,2t\\rangle$ 硬算，被積函數 $(4t^2+3)\\cdot1+(t^2-8t)\\cdot2=6t^2-16t+3$，$\\int_0^1={}$ $2-8+3=-3$。一樣。"],"answer":"$-3$"},{"title":"路徑很醜也不怕","prompt":"$\\int_C y\\,e^{xy}\\,dx+x\\,e^{xy}\\,dy$，$C$：$\\mathbf r(t)=\\langle t^2,t^3+1\\rangle$，$0\\le t\\le 1$。","steps":["認出 $\\langle y\\,e^{xy},x\\,e^{xy}\\rangle=\\nabla(e^{xy})$。整個平面上 $f=e^{xy}$ 的梯度連續。","起點 $\\mathbf r(0)=(0,1)$，終點 $\\mathbf r(1)=(1,2)$。","答案 $=e^{1\\cdot2}-e^{0\\cdot1}=e^2-1$。","如果硬代參數式，要積 $(t^3+1)e^{t^2(t^3+1)}\\cdot2t+t^2e^{t^2(t^3+1)}\\cdot3t^2$，非常難看；數值上兩者一致。"],"answer":"$e^2-1$"},{"title":"重力場的功","prompt":"$\\mathbf F=-\\frac{\\langle x,y,z\\rangle}{(x^2+y^2+z^2)^{3/2}}$。把質點從 $(0,0,2)$ 沿任意不經過原點的路徑移到 $(0,0,1)$，$\\mathbf F$ 做的功是？","steps":["$\\mathbf F=\\nabla f$，其中 $f=\\frac{1}{\\sqrt{x^2+y^2+z^2}}$（對 $x$ 偏微分得 $-\\frac{x}{(x^2+y^2+z^2)^{3/2}}$，$y$、$z$ 同理）。","$f$ 的梯度在 $\\mathbb{R}^3$ 去掉原點上連續，路徑不經過原點，可以用基本定理。","功 $=f(0,0,1)-f(0,0,2)=1-\\frac{1}{2}=\\frac{1}{2}$。往中心靠近，引力做正功。"],"answer":"$\\frac{1}{2}$"}],"pitfalls":["還沒確認 $\\mathbf F$ 是梯度場，就直接代端點。","寫成 $f($起點$)-f($終點$)$，正負號反了。","以為所有梯度場的線積分都是 $0$：只有封閉曲線才是 $0$。","位勢函數只在部分區域有定義時（例如 $\\arctan\\frac{y}{x}$），路徑跑出那個區域還照用。"],"checks":[{"ask":"$f=x^2+y^2$，$C$ 從 $(1,0)$ 到 $(0,3)$。$\\int_C\\nabla f\\cdot d\\mathbf r$ 是？","options":[{"label":"$8$","correct":true},{"label":"$10$","why":"是相減不是相加：$f(0,3)-f(1,0)=9-1$。"},{"label":"$0$","why":"只有起點等於終點（封閉曲線）才是 $0$。"}]},{"ask":"$\\mathbf F=\\langle y,-x\\rangle$ 沿單位圓逆時針從 $(1,0)$ 到 $(0,1)$ 的功是 $-\\frac{\\pi}{2}$，沿線段是 $-1$。結論是？","options":[{"label":"$\\mathbf F$ 不是保守場","correct":true},{"label":"其中一個一定算錯了","why":"兩個都對。同起點終點卻不同答案，正好說明 $\\mathbf F$ 跟路徑有關。"},{"label":"功只看端點，所以兩個都應該是 $-1$","why":"只看端點是保守場才有的性質。這個場 $P_y=1$、$Q_x=-1$，不保守。"}]},{"ask":"$f$ 的梯度在整個平面連續，$C$ 是任意封閉曲線。$\\oint_C\\nabla f\\cdot d\\mathbf r$ 是？","options":[{"label":"$0$","correct":true},{"label":"$2\\pi$","why":"$2\\pi$ 出現在有洞的反例裡；這裡 $f$ 處處好好的，起點等於終點，差是 $0$。"},{"label":"要看 $C$ 的形狀","why":"基本定理說只看端點，封閉曲線的兩端是同一點。"}]},{"ask":"在右半平面 $x>0$，$\\frac{\\langle -y,x\\rangle}{x^2+y^2}=\\nabla\\arctan\\frac{y}{x}$。下列何者正確？","options":[{"label":"路徑整條落在右半平面時，功只看端點","correct":true},{"label":"沿單位圓一整圈的功也是 $0$","why":"單位圓會穿過 $x\\le 0$，那裡 $\\arctan\\frac{y}{x}$ 不能當這個場的位勢函數；實際算出來是 $2\\pi$。"},{"label":"它在平面去掉原點上是保守場","why":"繞原點一圈的功是 $2\\pi\\ne 0$，所以在那個區域上不保守；位勢只在右半平面這種沒有繞過原點的區域上存在。"}]}],"practice":[{"id":"mob-nabla-007","core":true},{"id":"vc-work-001","core":true,"note":"$y\\,dx+x\\,dy$ 是誰的全微分？"},{"id":"vc-cons-002","core":true},{"id":"lec-20-q2c","core":true},{"id":"lec-20-m5"},{"id":"mob-tech-013"}]},"green-theorem":{"id":"green-theorem","prerequisites":["work-line-integral","nonrectangular-regions","conservative-fields"],"next":["parametric-surfaces"],"related":["curl","stokes-theorem","divergence","polar-double-integral"],"objectives":["寫出 Green 定理並說出所有條件：簡單封閉、分段光滑、正向（逆時針）、$P$、$Q$ 在包含整塊區域的開集上偏導連續。","用它把封閉曲線上的線積分換成二重積分（或反過來），包括用線積分算面積。","處理順時針、以及區域裡有奇異點的情況。"],"concept":[{"heading":"① 直觀：小漩渦加起來","body":["把 $D$ 切成很多小方格。在每個小方格的邊界上逆時針繞一圈，算 $\\mathbf F=\\langle P,Q\\rangle$ 的功（環流）。可以算出，小方格的環流約等於 $(Q_x-P_y)\\times{}$ 小方格面積；$Q_x-P_y$ 量的是那一點附近的場「轉了多少」。","把所有小方格的環流加起來：相鄰兩格共用的邊，一格往這邊走、另一格往那邊走，互相抵消。最後只剩最外圍的邊界。於是：外圍一圈的環流 $={}$ 所有小漩渦的總和。","這是直觀，不是證明：它沒交代「小方格的環流約等於 $(Q_x-P_y)\\times{}$ 面積」的誤差，也沒處理彎曲的邊界。"]},{"heading":"② 定理","body":["條件：$C$ 是分段光滑的簡單封閉曲線（自己不相交），圍出區域 $D$；$C$ 取正向，也就是沿著 $C$ 走時 $D$ 在左手邊（對一般的外圍邊界就是逆時針）；$P$、$Q$ 的一階偏導在一個包含 $D$（連同邊界）的開集上連續。那麼"],"tex":["\\oint_C P\\,dx+Q\\,dy=\\iint_D\\left(\\frac{\\partial Q}{\\partial x}-\\frac{\\partial P}{\\partial y}\\right)dA"]},{"heading":"③ 怎麼用","body":["線積分很難、$Q_x-P_y$ 很簡單時：換成二重積分。常見情形是 $P$、$Q$ 裡有 $e^{\\sin x}$、$\\sqrt{y^4+1}$ 這種東西，偏微分之後卻消失。","順時針：先照逆時針算，再加負號。","算面積：挑 $Q_x-P_y=1$ 的 $P$、$Q$，例如 $\\oint x\\,dy$、$-\\oint y\\,dx$ 或 $\\frac{1}{2}\\oint(x\\,dy-y\\,dx)$，三個都等於 $D$ 的面積。","跟〈保守場〉的關係：在單連通區域上 $Q_x-P_y=0$，任何封閉曲線的環流都是 $0$。"]},{"heading":"④ 證明的骨架與兩個延伸（給想知道的人）","body":["$D$ 同時是鉛直線型與水平線型區域時，把定理拆成兩半證明：$-\\iint P_y\\,dA=\\oint P\\,dx$ 與 $\\iint Q_x\\,dA=\\oint Q\\,dy$。以前者為例，$D=\\{a\\le x\\le b,\\ g_1(x)\\le y\\le g_2(x)\\}$，內層 $\\int P_y\\,dy=P(x,g_2(x))-P(x,g_1(x))$，再比對下緣（向右走）與上緣（向左走）兩段的 $\\oint P\\,dx$，左右兩條鉛直邊上 $dx=0$。一般區域切成這種小塊，共用邊抵消。","有洞的區域：邊界包含外圈（逆時針）與內圈（順時針），$D$ 仍然在左手邊，定理照樣成立。","通量形式：外法向量 $\\mathbf n$，$\\oint_C\\mathbf F\\cdot\\mathbf n\\,ds=\\iint_D(P_x+Q_y)\\,dA$。這是〈散度〉在平面上的版本。"],"collapsible":true}],"workedExamples":[{"title":"三角形：兩邊都算一次","prompt":"$\\oint_C x^4\\,dx+xy\\,dy$，$C$ 是頂點 $(0,0)$、$(1,0)$、$(0,1)$ 的三角形，逆時針。","steps":["$P=x^4$、$Q=xy$。$Q_x-P_y=y-0=y$。","$\\iint_D y\\,dA=\\int_0^1\\int_0^{1-x}y\\,dy\\,dx=\\int_0^1\\frac{(1-x)^2}{2}\\,dx=\\frac{1}{6}$。","驗算，三條邊直接算：$(0,0)\\to(1,0)$ 上 $y=0$，只剩 $\\int_0^1 x^4\\,dx=\\frac{1}{5}$。$(1,0)\\to(0,1)$ 用 $\\mathbf r=\\langle 1-t,t\\rangle$：$\\int_0^1\\left[-(1-t)^4+(1-t)t\\right]dt=-\\frac{1}{5}+\\frac{1}{6}$。$(0,1)\\to(0,0)$ 上 $x=0$，被積函數為 $0$。","合計 $\\frac{1}{5}-\\frac{1}{5}+\\frac{1}{6}=\\frac{1}{6}$。一樣。"],"answer":"$\\frac{1}{6}$"},{"title":"線積分很醜，二重積分很乾淨","prompt":"$\\oint_C(3y-e^{\\sin x})\\,dx+(7x+\\sqrt{y^4+1})\\,dy$，$C$ 是圓 $x^2+y^2=9$，逆時針。","steps":["直接參數化會遇到 $e^{\\sin(3\\cos t)}$，積不出來。","$Q_x-P_y=7-3=4$。$e^{\\sin x}$ 對 $y$ 偏微分是 $0$，$\\sqrt{y^4+1}$ 對 $x$ 偏微分也是 $0$。","$P$、$Q$ 在整個平面偏導連續，條件成立。$\\iint_D 4\\,dA=4\\times($圓面積 $9\\pi)=36\\pi$。"],"answer":"$36\\pi$","note":"claim 是沿圓直接數值積分，用來確認 Green 的答案。"},{"title":"順時針","prompt":"$\\oint_C y\\,dx-x\\,dy$，$C$ 是單位圓，順時針。","steps":["先當逆時針算：$P=y$、$Q=-x$，$Q_x-P_y=-1-1=-2$，$\\iint(-2)\\,dA=-2\\pi$。","順時針是反方向，加負號：$2\\pi$。","驗算：順時針 $\\mathbf r(t)=\\langle\\cos t,-\\sin t\\rangle$，$y\\,dx-x\\,dy=(-\\sin t)(-\\sin t)\\,dt-\\cos t\\,(-\\cos t)\\,dt=dt$，$\\int_0^{2\\pi}dt=2\\pi$。"],"answer":"$2\\pi$"}],"pitfalls":["算成 $P_y-Q_x$ 或 $Q_x+P_y$：是 $Q$ 對 $x$ 減 $P$ 對 $y$。","曲線是順時針卻沒有加負號。","曲線沒有封閉（例如只有半圓）就直接用 Green；要先補一段封閉，再扣掉補的那段。","區域裡有 $P$、$Q$ 沒定義的點（像原點）還照用。"],"checks":[{"ask":"Green 定理裡的「正向」是指？","options":[{"label":"沿著 $C$ 走時，$D$ 在左手邊（外圍邊界就是逆時針）","correct":true},{"label":"一律順時針","why":"方向反了。順時針走時 $D$ 在右手邊，答案會差一個負號。"},{"label":"從 $x$ 最小的點開始走","why":"從哪裡開始走不影響封閉曲線的積分，重要的是繞的方向。"}]},{"ask":"$C$ 是簡單封閉曲線、逆時針，$\\oint_C x\\,dy$ 等於？","options":[{"label":"$C$ 圍住的面積","correct":true},{"label":"$0$","why":"$P=0$、$Q=x$，$Q_x-P_y=1$，不是 $0$。"},{"label":"面積的 $2$ 倍","why":"$\\frac{1}{2}\\oint(x\\,dy-y\\,dx)$ 才需要乘 $\\frac{1}{2}$；$\\oint x\\,dy$ 本身的 $Q_x-P_y$ 就是 $1$。"}]},{"ask":"$\\oint_C y\\,dx+x\\,dy$，$C$ 是單位圓逆時針，是？","options":[{"label":"$0$","correct":true},{"label":"$2\\pi$","why":"$Q_x-P_y=1-1=0$。算成 $Q_x+P_y$ 才會得到 $2\\times{}$ 面積。"},{"label":"$-2\\pi$","why":"$y\\,dx+x\\,dy=d(xy)$ 是全微分，任何封閉曲線上都是 $0$。"}]},{"ask":"$\\oint_C\\frac{-y\\,dx+x\\,dy}{x^2+y^2}$，$C$ 是單位圓。可以用 Green 定理說它等於 $0$ 嗎？","options":[{"label":"不行：原點在 $D$ 裡，$P$、$Q$ 在那裡沒有定義，條件不成立（實際值是 $2\\pi$）","correct":true},{"label":"可以，因為 $Q_x-P_y=0$","why":"$Q_x-P_y=0$ 只在原點以外成立；Green 要求偏導在整個 $D$ 上連續，原點不行。"},{"label":"可以，答案是 $2$ 倍面積 $2\\pi$","why":"數字碰巧對，理由錯：$Q_x-P_y$ 不是 $2$。這題不能用 Green，要直接參數化。"}]}],"practice":[{"id":"lec-20-q3a","core":true},{"id":"vc-green-002","core":true},{"id":"vc-green-004","core":true},{"id":"lec-20-q3c","core":true},{"id":"vc-green-001","core":true},{"id":"vc-green-006","core":true},{"id":"lec-20-m4"},{"id":"lec-20-q3b"},{"id":"vc-work-002"},{"id":"vc-green-003"},{"id":"vc-green-005","note":"二重積分用極座標。"},{"id":"vc-green-008"},{"id":"vc-green-007","challenge":true,"note":"挑戰：$e^{x^2}$、$\\ln(1+y^2)$ 在偏微分時消失。"},{"id":"vc-flux-001","challenge":true,"note":"挑戰：通量形式 $\\oint\\mathbf F\\cdot\\mathbf n\\,ds=\\iint(P_x+Q_y)\\,dA$（見可展開段落）。"}]},"parametric-surfaces":{"id":"parametric-surfaces","prerequisites":["parametric-curves","tangent-plane","spherical-coordinates"],"next":["surface-area"],"related":["cylindrical-coordinates"],"objectives":["用 $\\mathbf r(u,v)$ 描述平面、函數圖形、圓柱、球面、圓錐這些曲面，並寫出參數的範圍。","算出兩個切向量 $\\mathbf r_u$、$\\mathbf r_v$ 與法向量 $\\mathbf r_u\\times\\mathbf r_v$。","用法向量寫出參數曲面的切平面。"],"concept":[{"heading":"① 曲線用一個參數，曲面用兩個","body":["〈參數曲線〉$\\mathbf r(t)$ 是一個參數掃出一條線。曲面要兩個參數：$\\mathbf r(u,v)=\\langle x(u,v),y(u,v),z(u,v)\\rangle$，$(u,v)$ 在 $uv$ 平面的某個區域 $D$ 裡變動，像點掃出一整片。","固定 $v$、只動 $u$，掃出曲面上的一條曲線；固定 $u$、只動 $v$，掃出另一條。這兩族曲線叫格線，把曲面織成一張網。"]},{"heading":"② 常見曲面的參數式","body":["函數圖形 $z=g(x,y)$：$\\mathbf r(x,y)=\\langle x,y,g(x,y)\\rangle$，參數就是 $x$、$y$。","平面：$\\mathbf r(u,v)=\\mathbf r_0+u\\mathbf a+v\\mathbf b$，過 $\\mathbf r_0$、由兩個不平行的向量 $\\mathbf a$、$\\mathbf b$ 張開。","圓柱面 $x^2+y^2=a^2$：$\\mathbf r(\\theta,z)=\\langle a\\cos\\theta,a\\sin\\theta,z\\rangle$，借用〈柱座標〉。","球面 $x^2+y^2+z^2=a^2$：$\\mathbf r(\\varphi,\\theta)=\\langle a\\sin\\varphi\\cos\\theta,a\\sin\\varphi\\sin\\theta,a\\cos\\varphi\\rangle$，$0\\le\\varphi\\le\\pi$、$0\\le\\theta\\le 2\\pi$，借用〈球座標〉把 $\\rho$ 固定成 $a$。","圓錐面 $z=\\sqrt{x^2+y^2}$：以 $(s,\\theta)$ 為參數，$\\langle s\\cos\\theta,s\\sin\\theta,s\\rangle$，$s\\ge 0$。"]},{"heading":"③ 切向量與法向量","body":["沿 $u$ 方向的格線，切向量是 $\\mathbf r_u=\\frac{\\partial\\mathbf r}{\\partial u}$；沿 $v$ 方向是 $\\mathbf r_v$。兩者都貼在曲面上。","它們的外積 $\\mathbf r_u\\times\\mathbf r_v$ 同時垂直於兩者，所以垂直於曲面：這是法向量。$\\mathbf r_u\\times\\mathbf r_v\\ne\\mathbf 0$ 的地方，曲面是光滑的，可以寫切平面：$\\mathbf n\\cdot(\\mathbf r-\\mathbf r_0)=0$。","$|\\mathbf r_u\\times\\mathbf r_v|$ 還有另一個用處：它是 $\\mathbf r_u$、$\\mathbf r_v$ 張成的平行四邊形面積，下一課〈曲面面積〉就靠它。"]}],"workedExamples":[{"title":"同一張曲面，兩種參數化","prompt":"把拋物面 $z=x^2+y^2$ 在 $z\\le 4$ 的部分參數化。","steps":["當成函數圖形：$\\mathbf r(x,y)=\\langle x,y,x^2+y^2\\rangle$，$(x,y)$ 在圓盤 $x^2+y^2\\le 4$。","用極座標的 $(r,\\theta)$ 當參數：$\\langle r\\cos\\theta,r\\sin\\theta,r^2\\rangle$，$0\\le r\\le 2$、$0\\le\\theta\\le 2\\pi$。參數區域變成矩形。","檢查：$x^2+y^2=r^2\\cos^2\\theta+r^2\\sin^2\\theta=r^2=z$，點確實在拋物面上。"],"answer":"$\\langle r\\cos\\theta,r\\sin\\theta,r^2\\rangle$，$0\\le r\\le 2$、$0\\le\\theta\\le 2\\pi$"},{"title":"球面","prompt":"寫出半徑 $2$ 的球面參數式，並確認點都在球面上。","steps":["$\\mathbf r(\\varphi,\\theta)=\\langle 2\\sin\\varphi\\cos\\theta,2\\sin\\varphi\\sin\\theta,2\\cos\\varphi\\rangle$，$0\\le\\varphi\\le\\pi$、$0\\le\\theta\\le 2\\pi$。","$x^2+y^2=4\\sin^2\\varphi\\,(\\cos^2\\theta+\\sin^2\\theta)=4\\sin^2\\varphi$。","加上 $z^2=4\\cos^2\\varphi$：總和 $4(\\sin^2\\varphi+\\cos^2\\varphi)=4$。","$\\varphi$ 固定的格線是緯線圈，$\\theta$ 固定的格線是經線。"],"answer":"$\\langle 2\\sin\\varphi\\cos\\theta,2\\sin\\varphi\\sin\\theta,2\\cos\\varphi\\rangle$"},{"title":"圓柱面的法向量與切平面","prompt":"$\\mathbf r(\\theta,z)=\\langle\\cos\\theta,\\sin\\theta,z\\rangle$。求 $\\mathbf r_\\theta\\times\\mathbf r_z$，以及在 $\\theta=0$、$z=1$ 的切平面。","steps":["$\\mathbf r_\\theta=\\langle -\\sin\\theta,\\cos\\theta,0\\rangle$，$\\mathbf r_z=\\langle 0,0,1\\rangle$。","外積：$\\langle\\cos\\theta\\cdot1-0\\cdot0,0\\cdot0-(-\\sin\\theta)\\cdot1,0\\rangle=\\langle\\cos\\theta,\\sin\\theta,0\\rangle$。它從 $z$ 軸往外指，長度 $1$。","$\\theta=0$、$z=1$ 的點是 $(1,0,1)$，法向量 $\\langle 1,0,0\\rangle$。","切平面：$1\\cdot(x-1)+0+0=0$，也就是 $x=1$。"],"answer":"$\\mathbf r_\\theta\\times\\mathbf r_z=\\langle\\cos\\theta,\\sin\\theta,0\\rangle$；切平面 $x=1$"}],"pitfalls":["圓柱面少了 $z$ 參數，寫成只有一個圓。","球面的 $\\varphi$ 寫到 $2\\pi$，或把 $\\varphi$、$\\theta$ 的角色對調。","以為 $\\mathbf r_u\\cdot\\mathbf r_v$ 是法向量；法向量要用外積。","外積的順序對調，法向量指向反面（下一課開始，方向會很重要）。"],"checks":[{"ask":"$\\mathbf r(u,v)=\\langle u,v,3-u-v\\rangle$ 描述的是？","options":[{"label":"平面 $x+y+z=3$","correct":true},{"label":"一條直線","why":"有兩個獨立的參數，掃出來的是二維的曲面，不是一維的線。"},{"label":"球面","why":"$x$、$y$ 是任意的 $u$、$v$，$z=3-x-y$ 是一次式，所以是平面。"}]},{"ask":"圓柱面 $x^2+y^2=9$ 的參數式是？","options":[{"label":"$\\langle 3\\cos\\theta,3\\sin\\theta,z\\rangle$","correct":true},{"label":"$\\langle 3\\cos\\theta,3\\sin\\theta,0\\rangle$","why":"只有一個參數 $\\theta$，掃出來是 $xy$ 平面上的一個圓。圓柱還要沿 $z$ 方向延伸。"},{"label":"$\\langle 9\\cos\\theta,9\\sin\\theta,z\\rangle$","why":"$x^2+y^2=9$ 的半徑是 $3$，不是 $9$。"}]},{"ask":"$\\mathbf r_u\\times\\mathbf r_v$ 在幾何上是？","options":[{"label":"曲面在那一點的法向量","correct":true},{"label":"曲面在那一點的切向量","why":"$\\mathbf r_u$、$\\mathbf r_v$ 本身是切向量；它們的外積垂直於兩者，所以垂直於曲面。"},{"label":"一定是零向量","why":"只有在不光滑的地方（像球面的南北極、圓錐的尖端）才會是 $\\mathbf 0$。"}]},{"ask":"球面參數式 $\\langle a\\sin\\varphi\\cos\\theta,a\\sin\\varphi\\sin\\theta,a\\cos\\varphi\\rangle$ 中，固定 $\\varphi$、讓 $\\theta$ 變動，得到的格線是？","options":[{"label":"緯線圈（水平的圓）","correct":true},{"label":"經線（通過南北極的半圓）","why":"那是固定 $\\theta$、讓 $\\varphi$ 從 $0$ 走到 $\\pi$。"},{"label":"一個點","why":"$\\theta$ 從 $0$ 走到 $2\\pi$ 會繞一圈；只有 $\\varphi=0$ 或 $\\pi$（極點）時才縮成一點。"}]}],"practice":[]},"surface-area":{"id":"surface-area","prerequisites":["parametric-surfaces","jacobian-geometry","polar-double-integral"],"next":["surface-integral"],"related":["surface-area-revolution"],"objectives":["說出 $A=\\iint_D|\\mathbf r_u\\times\\mathbf r_v|\\,dA$ 的來源：小方格被送成近似平行四邊形。","函數圖形 $z=g(x,y)$ 時用 $\\sqrt{1+g_x^2+g_y^2}$。","算出球面、拋物面、斜平面的面積。"],"concept":[{"heading":"① 小方格變成小平行四邊形","body":["參數曲面 $\\mathbf r(u,v)$，$(u,v)\\in D$。$uv$ 平面上一個 $\\Delta u\\times\\Delta v$ 的小方格，被送到曲面上的一小片。","這一小片的兩條邊，近似於向量 $\\mathbf r_u\\Delta u$ 與 $\\mathbf r_v\\Delta v$（就像〈Jacobian 的幾何意義〉的線性近似）。所以它近似一個由這兩個向量張成的平行四邊形，面積是 $|\\mathbf r_u\\Delta u\\times\\mathbf r_v\\Delta v|=|\\mathbf r_u\\times\\mathbf r_v|\\,\\Delta u\\,\\Delta v$。","加起來取極限："],"tex":["A(S)=\\iint_D \\big|\\mathbf r_u\\times\\mathbf r_v\\big|\\,dA"]},{"heading":"② 函數圖形的特例","body":["$z=g(x,y)$：$\\mathbf r=\\langle x,y,g\\rangle$，$\\mathbf r_x=\\langle 1,0,g_x\\rangle$，$\\mathbf r_y=\\langle 0,1,g_y\\rangle$。外積 $\\langle -g_x,-g_y,1\\rangle$，長度 $\\sqrt{1+g_x^2+g_y^2}$。","檢查直觀：平的曲面 $z={}$ 常數，$g_x=g_y=0$，因子是 $1$，面積就是 $D$ 的面積。越陡，因子越大。"],"tex":["A=\\iint_D\\sqrt{1+g_x^2+g_y^2}\\,dA"]},{"heading":"③ 三步驟","body":["1. 參數化曲面，寫出 $D$。2. 算 $\\mathbf r_u\\times\\mathbf r_v$ 與它的長度（圖形就直接用 $\\sqrt{1+g_x^2+g_y^2}$）。3. 在 $D$ 上做二重積分；$D$ 是圓盤時通常接著換〈極座標二重積分〉。","這也統一了〈旋轉曲面面積〉：把旋轉曲面參數化，套這個公式，就得到那裡的 $2\\pi\\int y\\,ds$。"]}],"workedExamples":[{"title":"球面面積","prompt":"半徑 $a$ 的球面面積。","steps":["$\\mathbf r(\\varphi,\\theta)=\\langle a\\sin\\varphi\\cos\\theta,a\\sin\\varphi\\sin\\theta,a\\cos\\varphi\\rangle$，$0\\le\\varphi\\le\\pi$、$0\\le\\theta\\le 2\\pi$。","$\\mathbf r_\\varphi=\\langle a\\cos\\varphi\\cos\\theta,a\\cos\\varphi\\sin\\theta,-a\\sin\\varphi\\rangle$，$\\mathbf r_\\theta=\\langle -a\\sin\\varphi\\sin\\theta,a\\sin\\varphi\\cos\\theta,0\\rangle$。","外積算出來是 $a^2\\sin\\varphi\\,\\langle\\sin\\varphi\\cos\\theta,\\sin\\varphi\\sin\\theta,\\cos\\varphi\\rangle$，括號裡是單位向量，而 $0\\le\\varphi\\le\\pi$ 時 $\\sin\\varphi\\ge 0$，所以 $|\\mathbf r_\\varphi\\times\\mathbf r_\\theta|=a^2\\sin\\varphi$。","$A=\\int_0^{2\\pi}\\int_0^\\pi a^2\\sin\\varphi\\,d\\varphi\\,d\\theta=a^2\\cdot2\\cdot2\\pi=4\\pi a^2$。以 $a=2$ 驗算：$16\\pi$。"],"answer":"$4\\pi a^2$"},{"title":"拋物面","prompt":"$z=x^2+y^2$ 在 $z\\le 9$ 的部分的面積。","steps":["$g_x=2x$、$g_y=2y$，因子 $\\sqrt{1+4x^2+4y^2}=\\sqrt{1+4r^2}$。","$D$：$x^2+y^2\\le 9$，極座標 $0\\le r\\le 3$。$A=\\int_0^{2\\pi}\\int_0^3\\sqrt{1+4r^2}\\,r\\,dr\\,d\\theta$。","令 $w=1+4r^2$，$dw=8r\\,dr$：$\\int_0^3\\sqrt{1+4r^2}\\,r\\,dr=\\frac{1}{8}\\cdot\\frac{2}{3}\\left[w^{3/2}\\right]_1^{37}=\\frac{37\\sqrt{37}-1}{12}$。","乘 $2\\pi$：$\\frac{\\pi}{6}(37\\sqrt{37}-1)$。"],"answer":"$\\frac{\\pi}{6}(37\\sqrt{37}-1)$"},{"title":"斜平面","prompt":"平面 $z=1+2x+2y$ 在單位正方形 $[0,1]^2$ 上方那一片的面積。","steps":["$g_x=2$、$g_y=2$，因子 $\\sqrt{1+4+4}=3$，是常數。","$A=3\\times($正方形面積 $1)=3$。斜面比它的影子大 $3$ 倍。"],"answer":"$3$"}],"pitfalls":["$\\sqrt{1+g_x^2+g_y^2}$ 漏了 $1$。","球面的面積元素漏了 $\\sin\\varphi$，算出 $2\\pi^2a^2$。","把曲面面積跟底下的體積 $\\iint g\\,dA$ 搞混。","$D$ 是圓盤卻不換極座標，卡在 $\\sqrt{1+4x^2+4y^2}$。"],"checks":[{"ask":"$z=g(x,y)$ 的曲面面積元素是？","options":[{"label":"$\\sqrt{1+g_x^2+g_y^2}\\,dA$","correct":true},{"label":"$\\sqrt{g_x^2+g_y^2}\\,dA$","why":"漏了 $1$。平面 $z={}$ 常數 的 $g_x=g_y=0$，面積應該等於 $D$ 的面積，不是 $0$。"},{"label":"$(1+g_x+g_y)\\,dA$","why":"要平方再開根號（是外積 $\\langle -g_x,-g_y,1\\rangle$ 的長度），不是直接相加。"}]},{"ask":"平面 $z=2x$ 在單位正方形 $[0,1]^2$ 上方的面積是？","options":[{"label":"$\\sqrt5$","correct":true},{"label":"$2$","why":"斜率 $2$ 不是面積的放大倍率；倍率是 $\\sqrt{1+2^2+0^2}=\\sqrt5$。"},{"label":"$3$","why":"要先平方再開根號：$\\sqrt{1+4}$，不是 $1+2$。"}]},{"ask":"球面參數式的 $|\\mathbf r_\\varphi\\times\\mathbf r_\\theta|$ 是？","options":[{"label":"$a^2\\sin\\varphi$","correct":true},{"label":"$a^2$","why":"漏了 $\\sin\\varphi$：靠近兩極的格子很窄，面積很小。少了它會算出 $2\\pi^2a^2$。"},{"label":"$a\\sin\\varphi$","why":"兩條邊 $\\mathbf r_\\varphi$、$\\mathbf r_\\theta$ 的長度分別是 $a$ 與 $a\\sin\\varphi$，相乘有兩個 $a$。"}]},{"ask":"為什麼面積元素是 $|\\mathbf r_u\\times\\mathbf r_v|\\,dA$？","options":[{"label":"小方格被送成以 $\\mathbf r_u\\Delta u$、$\\mathbf r_v\\Delta v$ 為邊的近似平行四邊形，外積的長度就是它的面積","correct":true},{"label":"因為 $\\mathbf r_u\\cdot\\mathbf r_v$ 是兩條邊的夾角","why":"點積給的是夾角的餘弦乘長度，不是面積；面積要用外積的長度。"},{"label":"因為面積是兩條邊長相加","why":"平行四邊形的面積是底 $\\times$ 高（外積長度），不是邊長相加。"}]}],"practice":[{"id":"lec-16-m2","core":true,"note":"平行四邊形面積 $=|\\mathbf a\\times\\mathbf b|$，正是曲面面積元素的來源。"},{"id":"vc-surf-003","core":true},{"id":"cx-sa-002","note":"半徑 $2$ 的球面：可以用本課的 $4\\pi a^2$ 核對。"}]},"surface-integral":{"id":"surface-integral","prerequisites":["surface-area","scalar-line-integral"],"next":["flux"],"related":["center-of-mass","parametric-surfaces"],"objectives":["說出 $\\iint_S f\\,dS$ 的意思：薄殼上「密度 $\\times$ 一小片面積」的總和。","用 $dS=|\\mathbf r_u\\times\\mathbf r_v|\\,dA$ 把它化成參數區域上的二重積分。","用對稱性簡化球面上的曲面積分。"],"concept":[{"heading":"① 從線到面","body":["〈純量線積分〉$\\int_C f\\,ds$：一條鐵絲的質量。曲面版本是一片薄殼：每一點的面密度是 $f$（每單位面積的質量），切成小片，每片面積 $\\Delta S$，質量約 $f\\,\\Delta S$，加起來取極限。這就是 $\\iint_S f\\,dS$。","$f=1$ 時，$\\iint_S 1\\,dS$ 就是〈曲面面積〉。"]},{"heading":"② 化成二重積分","body":["跟線積分的 $ds=|\\mathbf r'(t)|\\,dt$ 完全平行：曲面參數化 $\\mathbf r(u,v)$，$(u,v)\\in D$，$dS=|\\mathbf r_u\\times\\mathbf r_v|\\,dA$。$f$ 也要代成 $u$、$v$。","函數圖形 $z=g(x,y)$ 時：$dS=\\sqrt{1+g_x^2+g_y^2}\\,dA$，$f$ 裡的 $z$ 換成 $g(x,y)$。"],"tex":["\\iint_S f\\,dS=\\iint_D f\\big(\\mathbf r(u,v)\\big)\\,\\big|\\mathbf r_u\\times\\mathbf r_v\\big|\\,dA"]},{"heading":"③ 跟方向無關","body":["$dS$ 是面積，永遠是正的。所以 $\\iint_S f\\,dS$ 不需要決定曲面的「正面」是哪一面，換參數化也不影響結果。下一課的〈通量〉就需要選方向了。","曲面由好幾片組成（例如圓柱的側面加上下底），每片各自算，再相加。"]},{"heading":"④ 球面上的對稱捷徑","body":["單位球面上 $x^2+y^2+z^2=1$，所以 $\\iint(x^2+y^2+z^2)\\,dS=\\iint 1\\,dS=4\\pi$。球面對 $x$、$y$、$z$ 三個方向一樣，三項各佔三分之一：$\\iint x^2\\,dS=\\frac{4\\pi}{3}$。","奇函數也一樣：$\\iint_{\\text{球面}} z\\,dS=0$，上下半球抵消。"]}],"workedExamples":[{"title":"球面上的 $x^2$：參數化與對稱各做一次","prompt":"$\\iint_S x^2\\,dS$，$S$ 是單位球面。","steps":["參數化：$x=\\sin\\varphi\\cos\\theta$，$dS=\\sin\\varphi\\,d\\varphi\\,d\\theta$（上一課的 $|\\mathbf r_\\varphi\\times\\mathbf r_\\theta|$，$a=1$）。","$\\int_0^{2\\pi}\\int_0^\\pi\\sin^2\\varphi\\cos^2\\theta\\cdot\\sin\\varphi\\,d\\varphi\\,d\\theta=\\left(\\int_0^{2\\pi}\\cos^2\\theta\\,d\\theta\\right)\\left(\\int_0^\\pi\\sin^3\\varphi\\,d\\varphi\\right)=\\pi\\cdot\\frac{4}{3}=\\frac{4\\pi}{3}$。","對稱法：$\\iint(x^2+y^2+z^2)\\,dS={}$ 球面積 $4\\pi$，三項相等，每項 $\\frac{4\\pi}{3}$。一樣。"],"answer":"$\\frac{4\\pi}{3}$"},{"title":"函數圖形上","prompt":"$\\iint_S y\\,dS$，$S$ 是曲面 $z=x+y^2$，$0\\le x\\le 1$、$0\\le y\\le 2$。","steps":["$g_x=1$、$g_y=2y$，$dS=\\sqrt{1+1+4y^2}\\,dA=\\sqrt{2+4y^2}\\,dA$。","$\\int_0^1\\int_0^2 y\\sqrt{2+4y^2}\\,dy\\,dx$。$x$ 那層只貢獻 $1$。","令 $w=2+4y^2$，$dw=8y\\,dy$：$\\int_0^2 y\\sqrt{2+4y^2}\\,dy=\\frac{1}{8}\\cdot\\frac{2}{3}\\left[w^{3/2}\\right]_2^{18}=\\frac{1}{12}(18\\sqrt{18}-2\\sqrt2)=\\frac{1}{12}(54\\sqrt2-2\\sqrt2)=\\frac{13\\sqrt2}{3}$。"],"answer":"$\\frac{13\\sqrt2}{3}$"},{"title":"好幾片拼成的曲面","prompt":"$\\iint_S z\\,dS$，$S$ 是圓柱 $x^2+y^2\\le 1$、$0\\le z\\le 1$ 的整個表面（側面、上蓋、底）。","steps":["分三片算，再相加。","側面：$\\mathbf r(\\theta,z)=\\langle\\cos\\theta,\\sin\\theta,z\\rangle$，$|\\mathbf r_\\theta\\times\\mathbf r_z|=1$（〈參數曲面〉的圓柱例子）。$\\int_0^{2\\pi}\\int_0^1 z\\,dz\\,d\\theta=2\\pi\\cdot\\frac{1}{2}=\\pi$。","上蓋：$z=1$ 的單位圓盤，$dS=dA$。$\\iint 1\\,dA=\\pi$。","底：$z=0$，被積函數是 $0$，貢獻 $0$。","合計 $2\\pi$。"],"answer":"$2\\pi$"}],"pitfalls":["直接寫 $\\iint_D f\\,dA$，漏了 $|\\mathbf r_u\\times\\mathbf r_v|$（或 $\\sqrt{1+g_x^2+g_y^2}$）。","$f$ 裡的 $z$ 沒有代成 $g(x,y)$。","用了奇函數對稱，但曲面其實不對稱（例如只有上半球）。","以為曲面積分會因為法向量方向而變號；純量曲面積分不會。"],"checks":[{"ask":"$\\iint_S 1\\,dS$ 是？","options":[{"label":"$S$ 的面積","correct":true},{"label":"$S$ 圍住的體積","why":"$dS$ 是曲面上的小片面積，加起來是面積。體積要用三重積分。"},{"label":"$0$","why":"每一小片都貢獻正的面積，不會抵消。"}]},{"ask":"$S$ 是 $z=g(x,y)$ 的圖形，$dS$ 換成？","options":[{"label":"$\\sqrt{1+g_x^2+g_y^2}\\,dA$","correct":true},{"label":"$dA$","why":"那是假設曲面是平的。斜的曲面比它的影子大，要乘放大倍率。"},{"label":"$g(x,y)\\,dA$","why":"$g$ 是高度，跟小片面積的放大倍率無關。"}]},{"ask":"$S$ 是單位球面（整顆），$\\iint_S z\\,dS$ 是？","options":[{"label":"$0$","correct":true},{"label":"$\\frac{4\\pi}{3}$","why":"那是 $\\iint z^2\\,dS$。$z$ 本身在上下半球正負相反，互相抵消。"},{"label":"$2\\pi$","why":"那是 $\\iint|z|\\,dS$（上半球 $\\pi$ 加下半球 $\\pi$）。$z$ 在下半球是負的。"}]},{"ask":"把曲面的「正面」換成另一面，$\\iint_S f\\,dS$ 會？","options":[{"label":"不變","correct":true},{"label":"變號","why":"變號的是通量 $\\iint\\mathbf F\\cdot\\mathbf n\\,dS$。$dS$ 是面積，跟選哪一面無關。"},{"label":"變成 $0$","why":"沒有理由抵消，每一小片的 $f\\,\\Delta S$ 都沒變。"}]}],"practice":[{"id":"vc-surf-001","core":true},{"id":"vc-surf-002","core":true,"note":"圓柱側面：$|\\mathbf r_\\theta\\times\\mathbf r_z|=2$。"}]},"flux":{"id":"flux","prerequisites":["surface-integral","parametric-surfaces","vector-field"],"next":["curl"],"related":["divergence-theorem","green-theorem"],"objectives":["說出 $\\iint_S\\mathbf F\\cdot\\mathbf n\\,dS$ 的意思：每單位時間穿過曲面、往選定那一面流過去的流體量。","選定曲面的方向（法向量朝哪一面），並知道換方向會變號；封閉曲面預設朝外。","用 $\\iint_D\\mathbf F(\\mathbf r(u,v))\\cdot(\\mathbf r_u\\times\\mathbf r_v)\\,dA$ 計算，包括函數圖形朝上的公式。"],"concept":[{"heading":"① 直觀：每秒流過多少","body":["水以速度 $\\mathbf F$ 流動，一片小網面積 $\\Delta S$、單位法向量 $\\mathbf n$。每秒穿過網子的水，是以網子為底、沿 $\\mathbf F$ 斜著拉出去的斜柱體，體積 $={}$ 底面積 $\\times$ 垂直高度 $=(\\mathbf F\\cdot\\mathbf n)\\,\\Delta S$。","$\\mathbf F$ 跟網子垂直時流過最多；跟網子平行（相切）時一滴都不穿過；$\\mathbf F\\cdot\\mathbf n<0$ 表示往反方向穿過。加起來取極限就是通量："],"tex":["\\iint_S \\mathbf F\\cdot d\\mathbf S=\\iint_S \\mathbf F\\cdot\\mathbf n\\,dS"]},{"heading":"② 先選方向","body":["曲面有兩面，$\\mathbf n$ 可以指向任一面。算通量前一定要先選定，而且 $\\mathbf n$ 要在整片曲面上連續地選；能這樣選的曲面叫可定向曲面（Möbius 帶就不行）。","換成另一面，$\\mathbf n$ 變號，通量也變號。這是它跟〈曲面積分〉$\\iint f\\,dS$ 最大的不同。","慣例：封閉曲面（球面、立方體表面）沒特別說明時，取朝外的法向量。"]},{"heading":"③ 計算","body":["參數化 $\\mathbf r(u,v)$。$\\mathbf r_u\\times\\mathbf r_v$ 本身就是「法向量 $\\times$ 面積放大倍率」：$\\mathbf n\\,dS=\\frac{\\mathbf r_u\\times\\mathbf r_v}{|\\mathbf r_u\\times\\mathbf r_v|}\\cdot|\\mathbf r_u\\times\\mathbf r_v|\\,dA=(\\mathbf r_u\\times\\mathbf r_v)\\,dA$。所以長度會消掉，不用開根號。","如果 $\\mathbf r_u\\times\\mathbf r_v$ 指向的不是你選的那一面，就整個加負號。","函數圖形 $z=g(x,y)$、法向量朝上：$\\mathbf r_x\\times\\mathbf r_y=\\langle -g_x,-g_y,1\\rangle$，$z$ 分量是正的，正好朝上。"],"tex":["\\iint_S \\mathbf F\\cdot d\\mathbf S=\\iint_D \\mathbf F\\big(\\mathbf r(u,v)\\big)\\cdot(\\mathbf r_u\\times\\mathbf r_v)\\,dA,\\qquad z=g:\\ \\iint_D\\big(-Pg_x-Qg_y+R\\big)\\,dA"]}],"workedExamples":[{"title":"向外穿過球面","prompt":"$\\mathbf F=\\langle x,y,z\\rangle$ 穿過半徑 $2$ 的球面、法向量朝外的通量。","steps":["捷徑：球面上朝外的單位法向量是 $\\mathbf n=\\frac{\\langle x,y,z\\rangle}{2}$。$\\mathbf F\\cdot\\mathbf n=\\frac{x^2+y^2+z^2}{2}=\\frac{4}{2}=2$，處處一樣。","通量 $=2\\times{}$ 球面積 $=2\\times4\\pi\\cdot2^2=32\\pi$。","用參數式驗算：$\\mathbf r_\\varphi\\times\\mathbf r_\\theta=4\\sin\\varphi\\,\\langle\\sin\\varphi\\cos\\theta,\\sin\\varphi\\sin\\theta,\\cos\\varphi\\rangle$（朝外，因為 $\\sin\\varphi\\ge 0$）。$\\mathbf F$ 在球面上是 $2\\langle\\sin\\varphi\\cos\\theta,\\sin\\varphi\\sin\\theta,\\cos\\varphi\\rangle$，點積 $=8\\sin\\varphi$。$\\int_0^{2\\pi}\\int_0^\\pi 8\\sin\\varphi\\,d\\varphi\\,d\\theta=32\\pi$。"],"answer":"$32\\pi$"},{"title":"穿過拋物面的碗，朝上","prompt":"$\\mathbf F=\\langle y,x,z\\rangle$ 穿過 $z=1-x^2-y^2$（$z\\ge 0$）的通量，法向量朝上。","steps":["$g=1-x^2-y^2$，$g_x=-2x$、$g_y=-2y$。朝上的公式：$-Pg_x-Qg_y+R=y\\cdot2x+x\\cdot2y+z=4xy+1-x^2-y^2$（$z$ 要代成 $g$）。","$D$：$x^2+y^2\\le 1$。換極座標：被積函數 $4r^2\\cos\\theta\\sin\\theta+1-r^2$，再乘 $r$。","$4r^2\\cos\\theta\\sin\\theta$ 對 $\\theta$ 積一整圈是 $0$。剩下 $\\int_0^{2\\pi}\\int_0^1(1-r^2)\\,r\\,dr\\,d\\theta=2\\pi\\cdot\\frac{1}{4}=\\frac{\\pi}{2}$。"],"answer":"$\\frac{\\pi}{2}$"}],"pitfalls":["沒選方向就開始算，或算出來之後才發現 $\\mathbf r_u\\times\\mathbf r_v$ 指向另一面卻沒加負號。","把 $\\mathbf r_u\\times\\mathbf r_v$ 先除以長度再乘 $dA$，弄成多除了一次。","函數圖形公式裡的 $z$ 沒代成 $g(x,y)$。","以為 $\\mathbf F$ 與曲面平行時通量最大；平行（相切）時通量是 $0$。"],"checks":[{"ask":"同一片曲面把法向量換成另一面，通量會？","options":[{"label":"變號","correct":true},{"label":"不變","why":"不變的是純量曲面積分 $\\iint f\\,dS$。通量的被積函數 $\\mathbf F\\cdot\\mathbf n$ 會因為 $\\mathbf n$ 反向而變號。"},{"label":"變成 $0$","why":"只是每一小片的 $\\mathbf F\\cdot\\mathbf n$ 都變號，總和跟著變號，不會抵消成 $0$。"}]},{"ask":"$\\mathbf F$ 在曲面上處處與曲面相切，通量是？","options":[{"label":"$0$","correct":true},{"label":"最大","why":"相切表示流體沿著曲面滑過，沒有穿過去：$\\mathbf F\\cdot\\mathbf n=0$。垂直穿過時才最大。"},{"label":"要看曲面的面積","why":"$\\mathbf F\\cdot\\mathbf n$ 處處為 $0$，乘上多大的面積都是 $0$。"}]},{"ask":"$\\mathbf F=\\langle 0,0,3\\rangle$ 穿過 $xy$ 平面上的單位正方形，法向量朝上，通量是？","options":[{"label":"$3$","correct":true},{"label":"$-3$","why":"$\\mathbf F$ 朝上、$\\mathbf n$ 也朝上，$\\mathbf F\\cdot\\mathbf n=3>0$。法向量朝下時才是 $-3$。"},{"label":"$0$","why":"$\\mathbf F$ 垂直穿過正方形（不是平行），$\\mathbf F\\cdot\\mathbf n=3$，乘面積 $1$。"}]},{"ask":"封閉曲面沒特別說明時，通量用哪個方向？","options":[{"label":"朝外","correct":true},{"label":"朝內","why":"慣例是朝外：通量為正代表淨流出。〈散度定理〉也是用朝外的方向。"},{"label":"任選，結果一樣","why":"兩個方向的答案差一個負號，不能任選。"}]}],"practice":[{"id":"lec-20-q4a","core":true,"note":"可以直接算：球面上 $\\mathbf F\\cdot\\mathbf n=a$。"},{"id":"vc-div-001","core":true,"note":"直接算，不必用散度定理。"},{"id":"vc-div-006","core":true,"note":"直接算：球面上 $\\mathbf F\\cdot\\mathbf n=\\frac{1}{25}$。"},{"id":"vc-div-007","core":true,"note":"三片分開算：上蓋、底、側面，各自注意朝外的方向。"},{"id":"vc-stokes-005","challenge":true,"note":"挑戰：$\\nabla\\times\\mathbf F=\\langle 0,0,2\\rangle$，算它朝上穿過上半球面的通量。"}]},"curl":{"id":"curl","prerequisites":["green-theorem","partial-derivatives","conservative-fields"],"next":["divergence"],"related":["stokes-theorem","clairaut"],"objectives":["用行列式記號算 $\\nabla\\times\\mathbf F$。","說出旋度的意義：放一個小槳輪，它轉不轉、繞哪個軸轉、轉多快；平面上就是 Green 定理裡的 $Q_x-P_y$。","知道 $\\nabla\\times(\\nabla f)=\\mathbf 0$，以及「旋度為 $0\\Rightarrow$ 保守」需要單連通。"],"concept":[{"heading":"① 小槳輪","body":["在流體裡放一個很小的槳輪，軸固定不動。槳葉被兩側流速推動：如果一邊推得比另一邊用力，槳輪就會轉。旋度量的就是這件事：在每一點，槳輪最想繞哪個軸轉（方向）、轉得多快（大小）。","平面場 $\\mathbf F=\\langle P,Q\\rangle$ 只有繞 $z$ 軸轉的可能，量是 $Q_x-P_y$，正值代表逆時針。這正是〈Green 定理〉裡的被積函數：小方格的環流 $\\approx(Q_x-P_y)\\times{}$ 面積。"]},{"heading":"② 定義與記號","body":["$\\mathbf F=\\langle P,Q,R\\rangle$。把 $\\nabla=\\left\\langle\\frac{\\partial}{\\partial x},\\frac{\\partial}{\\partial y},\\frac{\\partial}{\\partial z}\\right\\rangle$ 當成一個向量，跟 $\\mathbf F$ 做外積："],"tex":["\\nabla\\times\\mathbf F=\\det\\begin{pmatrix}\\mathbf i&\\mathbf j&\\mathbf k\\\\ \\partial_x&\\partial_y&\\partial_z\\\\ P&Q&R\\end{pmatrix}=\\left\\langle R_y-Q_z,\\ P_z-R_x,\\ Q_x-P_y\\right\\rangle"]},{"heading":"③ 兩個例子對照直觀","body":["剛體旋轉 $\\langle -y,x,0\\rangle$：$\\nabla\\times\\mathbf F=\\langle 0,0,2\\rangle$。整個平面以角速度 $1$ 逆時針轉，旋度是角速度的 $2$ 倍，方向沿 $z$ 軸（右手定則：四指沿旋轉方向彎，拇指指向 $+z$）。","剪切流 $\\langle y,0,0\\rangle$：流線都是水平直線，沒有任何東西在「繞圈」，旋度卻是 $\\langle 0,0,-1\\rangle$。因為上方流得比下方快，槳輪上緣被推得比下緣用力，順時針轉。旋度量的是局部的自轉，不是流線彎不彎。"]},{"heading":"④ 跟保守場的關係","body":["$\\nabla\\times(\\nabla f)=\\mathbf 0$（$f$ 的二階偏導連續）：每個分量都是一對混合偏導相減，由〈Clairaut 定理〉抵消。所以梯度場沒有旋度。","反過來，$\\mathbf F$ 的一階偏導連續、$\\nabla\\times\\mathbf F=\\mathbf 0$，而且定義域單連通（例如整個 $\\mathbb{R}^3$）時，$\\mathbf F$ 是保守場。定義域有洞時不一定，見〈保守場〉的反例。"]},{"heading":"⑤ 精確的意義（給想知道的人）","body":["取一個單位向量 $\\mathbf n$，在點 $p$ 放一個垂直於 $\\mathbf n$、半徑 $\\varepsilon$ 的小圓盤，邊界依右手定則繞。那麼 $(\\nabla\\times\\mathbf F)(p)\\cdot\\mathbf n=\\lim_{\\varepsilon\\to0}\\frac{1}{\\pi\\varepsilon^2}\\oint\\mathbf F\\cdot d\\mathbf r$：旋度在 $\\mathbf n$ 方向的分量，就是「每單位面積的環流」。這個式子由〈Stokes 定理〉加上連續性推出。"],"collapsible":true}],"workedExamples":[{"title":"照公式算","prompt":"$\\mathbf F=\\langle xz,xyz,-y^2\\rangle$，求 $\\nabla\\times\\mathbf F$。","steps":["$P=xz$、$Q=xyz$、$R=-y^2$。","第一分量 $R_y-Q_z=-2y-xy=-y(2+x)$。","第二分量 $P_z-R_x=x-0=x$。","第三分量 $Q_x-P_y=yz-0=yz$。","$\\nabla\\times\\mathbf F=\\langle -y(2+x),x,yz\\rangle$。"],"answer":"$\\langle -y(2+x),x,yz\\rangle$"},{"title":"剪切流","prompt":"$\\mathbf F=\\langle y,0,0\\rangle$。求旋度，並說明槳輪怎麼轉。","steps":["$R_y-Q_z=0$，$P_z-R_x=0$，$Q_x-P_y=0-1=-1$。$\\nabla\\times\\mathbf F=\\langle 0,0,-1\\rangle$。","$z$ 分量為負：從上往下看，槳輪順時針轉。","原因：槳輪上緣（$y$ 大）往右的流速比下緣大，上緣被往右推得比較多，整個輪子順時針轉。"],"answer":"$\\langle 0,0,-1\\rangle$，順時針"},{"title":"梯度場沒有旋度","prompt":"$f=x^2yz^3$。驗證 $\\nabla\\times(\\nabla f)$ 的第一個分量是 $0$。","steps":["$\\nabla f=\\langle 2xyz^3,x^2z^3,3x^2yz^2\\rangle$。","第一分量 $=\\frac{\\partial}{\\partial y}(3x^2yz^2)-\\frac{\\partial}{\\partial z}(x^2z^3)=3x^2z^2-3x^2z^2=0$。","另外兩個分量同理：都是兩個相同的混合偏導相減。"],"answer":"$0$"}],"pitfalls":["第二分量寫成 $R_x-P_z$：正確是 $P_z-R_x$（行列式展開中間那項有負號）。","以為流線是直線就沒有旋度（剪切流的反例）。","以為旋度等於角速度；剛體旋轉時旋度是角速度的 $2$ 倍。","看到 $\\nabla\\times\\mathbf F=\\mathbf 0$ 就說保守，沒檢查定義域。"],"checks":[{"ask":"$\\mathbf F=\\langle -y,x,0\\rangle$ 的旋度是？","options":[{"label":"$\\langle 0,0,2\\rangle$","correct":true},{"label":"$\\langle 0,0,0\\rangle$","why":"$Q_x-P_y=1-(-1)=2$。算成 $Q_x+P_y$ 才會得到 $0$。"},{"label":"$\\langle 0,0,1\\rangle$","why":"這個場的角速度是 $1$，但旋度是角速度的 $2$ 倍。"}]},{"ask":"剪切流 $\\mathbf F=\\langle y,0,0\\rangle$ 的流線都是水平直線。它的旋度？","options":[{"label":"$\\langle 0,0,-1\\rangle$，不是 $\\mathbf 0$","correct":true},{"label":"$\\mathbf 0$，因為流線是直的","why":"旋度量的是局部自轉。上下流速不同，槳輪會被帶著轉。"},{"label":"$\\langle 0,0,1\\rangle$","why":"$Q_x-P_y=0-1=-1$，是順時針，正負號要注意。"}]},{"ask":"$\\nabla\\times(\\nabla f)$ 等於？（$f$ 的二階偏導連續）","options":[{"label":"零向量","correct":true},{"label":"$\\nabla^2f$","why":"那是 $\\nabla\\cdot(\\nabla f)$（散度），是一個純量。旋度的每個分量都是混合偏導相減，等於 $0$。"},{"label":"要看 $f$","why":"對任何二階偏導連續的 $f$ 都成立，由 Clairaut 定理保證。"}]},{"ask":"下列哪一句正確？","options":[{"label":"$\\mathbf F$ 在整個 $\\mathbb{R}^3$ 偏導連續且 $\\nabla\\times\\mathbf F=\\mathbf 0$，則 $\\mathbf F$ 是保守場","correct":true},{"label":"$\\nabla\\times\\mathbf F=\\mathbf 0$ 就一定是保守場，不必管定義域","why":"$\\frac{\\langle -y,x,0\\rangle}{x^2+y^2}$ 在去掉 $z$ 軸的空間裡旋度為 $\\mathbf 0$，繞 $z$ 軸一圈的功卻是 $2\\pi$。"},{"label":"$\\nabla\\times\\mathbf F\\ne\\mathbf 0$ 的場也可能是保守場","why":"保守場是梯度場，而梯度場的旋度一定是 $\\mathbf 0$。"}]}],"practice":[{"id":"mob-nabla-002","core":true},{"id":"lec-20-m3","core":true},{"id":"vc-nab-012","core":true},{"id":"vc-nab-004","core":true},{"id":"exam-multi-010"},{"id":"uni-der-016"},{"id":"depth-der-014"},{"id":"vc-nab-011","note":"$\\langle yz,zx,xy\\rangle=\\nabla(xyz)$。"},{"id":"mob-nabla-005"}]},"divergence":{"id":"divergence","prerequisites":["flux","partial-derivatives"],"next":["stokes-theorem"],"related":["curl","divergence-theorem","green-theorem"],"objectives":["算 $\\nabla\\cdot\\mathbf F$，並知道結果是一個純量函數。","說出散度的意義：每單位體積的淨流出量；正是源、負是匯。","知道 $\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$、$\\nabla\\cdot\\nabla f=\\nabla^2f$，並分清楚「箭頭往外」與「散度為正」不是同一件事。"],"concept":[{"heading":"① 小方塊的淨流出","body":["在一點旁邊放一個小方塊，量它表面的通量（〈通量〉，朝外）：流出去的減掉流進來的。再除以方塊體積，讓方塊縮到一點：這個極限就是散度。","散度 $>0$：那裡像水龍頭，淨流出（源）。散度 $<0$：像排水孔，淨流入（匯）。散度 $=0$：流進多少就流出多少，例如不可壓縮的水。"]},{"heading":"② 公式","body":["$\\mathbf F=\\langle P,Q,R\\rangle$。為什麼是這三項：看 $x$ 方向的一對面，右面流出約 $P(x+\\Delta x)\\,\\Delta y\\Delta z$，左面流進約 $P(x)\\,\\Delta y\\Delta z$，淨流出約 $P_x\\,\\Delta x\\Delta y\\Delta z$。三個方向加起來除以體積，得到 $P_x+Q_y+R_z$。這是直觀，不是證明；精確的版本就是〈散度定理〉。"],"tex":["\\nabla\\cdot\\mathbf F=\\frac{\\partial P}{\\partial x}+\\frac{\\partial Q}{\\partial y}+\\frac{\\partial R}{\\partial z}"]},{"heading":"③ 箭頭往外，不代表散度為正","body":["$\\langle x,y,z\\rangle$：$\\nabla\\cdot\\mathbf F=3$，處處淨流出，箭頭也確實往外。","$\\langle -y,x,0\\rangle$：$\\nabla\\cdot\\mathbf F=0$，純粹旋轉，沒有源。","$\\frac{\\langle x,y,z\\rangle}{(x^2+y^2+z^2)^{3/2}}$（像點電荷的電場）：箭頭全部往外，但在原點以外散度是 $0$（範例 2）。往外流的量被「越遠越弱」剛好補回來：任何不含原點的小方塊，流進等於流出。源全部集中在原點那一點，見〈散度定理〉。"]},{"heading":"④ 兩個恆等式","body":["$\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$（$\\mathbf F$ 的二階偏導連續）：展開之後是三對混合偏導相減，由 Clairaut 抵消。","$\\nabla\\cdot(\\nabla f)=f_{xx}+f_{yy}+f_{zz}$，記作 $\\nabla^2f$ 或 $\\Delta f$，叫 Laplacian。$\\nabla^2f=0$ 的函數叫調和函數，例如 $\\frac{1}{\\sqrt{x^2+y^2+z^2}}$（原點以外）。"]}],"workedExamples":[{"title":"照公式算","prompt":"$\\mathbf F=\\langle xz,xyz,-y^2\\rangle$，求 $\\nabla\\cdot\\mathbf F$。","steps":["$P_x=z$，$Q_y=xz$，$R_z=0$（$-y^2$ 不含 $z$）。","$\\nabla\\cdot\\mathbf F=z+xz$。"],"answer":"$z+xz$"},{"title":"往外卻沒有源","prompt":"$\\mathbf F=\\frac{\\langle x,y,z\\rangle}{(x^2+y^2+z^2)^{3/2}}$。證明在原點以外 $\\nabla\\cdot\\mathbf F=0$。","steps":["記 $\\rho^2=x^2+y^2+z^2$，$P=x\\rho^{-3}$。$P_x=\\rho^{-3}+x\\cdot(-3)\\rho^{-4}\\cdot\\frac{x}{\\rho}=\\rho^{-3}-3x^2\\rho^{-5}$。","同理 $Q_y=\\rho^{-3}-3y^2\\rho^{-5}$，$R_z=\\rho^{-3}-3z^2\\rho^{-5}$。","相加：$3\\rho^{-3}-3(x^2+y^2+z^2)\\rho^{-5}=3\\rho^{-3}-3\\rho^{-3}=0$。"],"answer":"原點以外 $\\nabla\\cdot\\mathbf F=0$"},{"title":"旋度的散度","prompt":"$\\mathbf F=\\langle xz,xyz,-y^2\\rangle$，驗證 $\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$。","steps":["上一課〈旋度〉算過 $\\nabla\\times\\mathbf F=\\langle -y(2+x),x,yz\\rangle$。","散度：$\\frac{\\partial}{\\partial x}[-y(2+x)]+\\frac{\\partial}{\\partial y}[x]+\\frac{\\partial}{\\partial z}[yz]=-y+0+y=0$。"],"answer":"$0$"}],"pitfalls":["把散度寫成向量 $\\langle P_x,Q_y,R_z\\rangle$；它是三項相加的純量。","對錯變數微分：$P$ 對 $x$、$Q$ 對 $y$、$R$ 對 $z$，不是交叉的。","看到箭頭往外就說散度為正。","把 $\\nabla\\cdot(\\nabla\\times\\mathbf F)$ 與 $\\nabla\\times(\\nabla f)$ 搞混：前者是純量 $0$、後者是零向量，兩者都來自混合偏導相等。"],"checks":[{"ask":"$\\mathbf F=\\langle x^2,y^2,z^2\\rangle$ 在 $(1,1,1)$ 的散度是？","options":[{"label":"$6$","correct":true},{"label":"$3$","why":"$x^2$ 對 $x$ 微分是 $2x$，在 $x=1$ 是 $2$，不是 $1$。三項各 $2$，合計 $6$。"},{"label":"$\\langle 2,2,2\\rangle$","why":"散度是三項相加的純量，不是向量。"}]},{"ask":"某點的散度為正，意思是？","options":[{"label":"那一點附近淨流出（像源）","correct":true},{"label":"流體在那裡旋轉","why":"旋轉是旋度量的。純旋轉的 $\\langle -y,x,0\\rangle$ 散度是 $0$。"},{"label":"流速在那裡很大","why":"均勻的快速流動 $\\langle 100,0,0\\rangle$ 散度是 $0$：流進多少流出多少。"}]},{"ask":"$\\mathbf F=\\frac{\\langle x,y,z\\rangle}{(x^2+y^2+z^2)^{3/2}}$ 在原點以外的散度是？","options":[{"label":"$0$","correct":true},{"label":"正的，因為箭頭全部往外","why":"箭頭往外，但越外越弱，小方塊流進與流出剛好抵消。"},{"label":"處處沒有定義","why":"只有原點沒有定義；其他地方算得出來，結果是 $0$。"}]},{"ask":"$\\nabla\\cdot(\\nabla\\times\\mathbf F)$ 等於？（$\\mathbf F$ 的二階偏導連續）","options":[{"label":"$0$","correct":true},{"label":"$\\nabla^2\\mathbf F$","why":"那是另一個運算。展開 $\\nabla\\cdot(\\nabla\\times\\mathbf F)$ 會得到三對混合偏導相減，全部抵消。"},{"label":"$|\\nabla\\times\\mathbf F|$","why":"$\\nabla\\times\\mathbf F$ 的長度一般不是 $0$；但先取旋度再取散度，展開後每一項都被另一項抵消，結果恆為 $0$。"}]}],"practice":[{"id":"mob-nabla-001","core":true},{"id":"rel-hard-der-008","core":true},{"id":"lec-20-m2","core":true},{"id":"vc-nab-003","core":true},{"id":"vc-nab-005","core":true},{"id":"exam-multi-009"},{"id":"uni-der-015"},{"id":"depth-der-013"},{"id":"vc-nab-002"},{"id":"vc-nab-001","note":"$\\frac{1}{\\rho}$ 是調和函數。"},{"id":"vc-nab-010","challenge":true,"note":"挑戰：先把 $f\\mathbf F$ 乘出來，或用 $\\nabla\\cdot(f\\mathbf F)=\\nabla f\\cdot\\mathbf F+f\\,\\nabla\\cdot\\mathbf F$。"}]},"stokes-theorem":{"id":"stokes-theorem","prerequisites":["curl","flux","green-theorem"],"next":["divergence-theorem"],"related":["fundamental-theorems-unified","conservative-fields","divergence"],"objectives":["寫出 Stokes 定理與它的條件，特別是邊界方向與曲面法向量怎麼用右手定則配對。","把空間封閉曲線的環流換成旋度通量（或反過來），並挑一張好算的曲面。","說出 Green 定理是 Stokes 定理在平面上的特例。"],"concept":[{"heading":"① 把 Green 定理拿到空間裡","body":["〈Green 定理〉：平面區域邊界的環流 $={}$ 區域裡所有小漩渦（$Q_x-P_y$）的總和。","空間裡換成一張曲面 $S$，邊界是一條封閉曲線 $C$。把 $S$ 切成小片，每一小片邊界的環流 $\\approx(\\nabla\\times\\mathbf F)\\cdot\\mathbf n\\times{}$ 小片面積（〈旋度〉在 $\\mathbf n$ 方向的分量）。相鄰小片的共用邊抵消，只剩 $S$ 的邊界 $C$。這是直觀，不是證明。"]},{"heading":"② 定理與方向配對","body":["先講方向怎麼配。右手定則：右手拇指指向曲面的法向量 $\\mathbf n$，四指彎曲的方向就是邊界 $C$ 的方向。等價的說法：頭朝 $\\mathbf n$ 的方向，沿 $C$ 走，曲面在你的左手邊。","例：上半球面、法向量朝上，邊界單位圓要「從上往下看逆時針」。","定理：$S$ 是可定向、分段光滑的曲面，邊界 $C$ 是分段光滑的簡單封閉曲線，$C$ 依右手定則跟 $\\mathbf n$ 配對；$\\mathbf F$ 的分量在一個包含 $S$ 的開集上有連續偏導。那麼"],"tex":["\\oint_C \\mathbf F\\cdot d\\mathbf r=\\iint_S (\\nabla\\times\\mathbf F)\\cdot d\\mathbf S"]},{"heading":"③ 兩個用法","body":["線積分難、旋度簡單：把 $\\oint_C$ 換成曲面積分，而且曲面可以任選，只要邊界是 $C$、方向配好。通常選最平的那張（圓盤、平面上的一片）。","旋度通量難：反過來換成邊界的線積分。推論：兩張曲面邊界相同、方向一致，旋度通量一定相同。","Green 是特例：$S$ 是 $xy$ 平面上的區域、$\\mathbf n=\\mathbf k$，$(\\nabla\\times\\mathbf F)\\cdot\\mathbf k=Q_x-P_y$，$C$ 逆時針，就回到 Green。"]},{"heading":"④ 封閉曲面與保守場（給想知道的人）","body":["封閉曲面（像整個球面）沒有邊界，所以 $\\oiint(\\nabla\\times\\mathbf F)\\cdot d\\mathbf S=0$。這跟〈散度〉的 $\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$ 是同一件事的兩面。","如果在整個 $\\mathbb{R}^3$ 上 $\\nabla\\times\\mathbf F=\\mathbf 0$，任何封閉曲線都是某張曲面的邊界，環流都是 $0$，所以 $\\mathbf F$ 保守，這正是〈保守場〉那個充分條件在三維的理由。"],"collapsible":true}],"workedExamples":[{"title":"換成平面上的一片","prompt":"$\\oint_C\\mathbf F\\cdot d\\mathbf r$，$\\mathbf F=\\langle -y^2,x,z^2\\rangle$，$C$ 是平面 $y+z=2$ 與圓柱 $x^2+y^2=1$ 的交線，從上往下看逆時針。","steps":["$\\nabla\\times\\mathbf F=\\langle 0-0,0-0,1-(-2y)\\rangle=\\langle 0,0,1+2y\\rangle$。","選 $S$：平面 $y+z=2$ 在圓柱裡的那一片（一個橢圓），$z=2-y$。$C$ 從上往下看逆時針，右手定則給法向量朝上。","朝上的通量公式：$-Pg_x-Qg_y+R$，其中 $(P,Q,R)=\\nabla\\times\\mathbf F=(0,0,1+2y)$，得 $1+2y$。","$\\iint_{x^2+y^2\\le1}(1+2y)\\,dA$：$2y$ 對稱抵消，剩 $\\pi$。","驗算：直接參數化 $\\mathbf r(t)=\\langle\\cos t,\\sin t,2-\\sin t\\rangle$ 算線積分，也是 $\\pi$。"],"answer":"$\\pi$"},{"title":"旋度通量換成邊界","prompt":"$\\iint_S(\\nabla\\times\\mathbf F)\\cdot d\\mathbf S$，$\\mathbf F=\\langle xz,yz,xy\\rangle$，$S$ 是球面 $x^2+y^2+z^2=4$ 在圓柱 $x^2+y^2=1$ 裡、$xy$ 平面上方的部分，法向量朝上。","steps":["$S$ 的邊界：$x^2+y^2=1$ 且 $z=\\sqrt{4-1}=\\sqrt3$，是高度 $\\sqrt3$ 的圓。法向量朝上，所以從上往下看逆時針：$\\mathbf r(t)=\\langle\\cos t,\\sin t,\\sqrt3\\rangle$。","$\\mathbf F$ 在 $C$ 上 $=\\langle\\sqrt3\\cos t,\\sqrt3\\sin t,\\cos t\\sin t\\rangle$，$\\mathbf r'(t)=\\langle -\\sin t,\\cos t,0\\rangle$。","$\\mathbf F\\cdot\\mathbf r'=-\\sqrt3\\cos t\\sin t+\\sqrt3\\sin t\\cos t+0=0$。","所以答案是 $0$，完全不用算旋度。"],"answer":"$0$"}],"pitfalls":["邊界方向跟法向量沒有用右手定則配對，差一個負號。","曲面的邊界找錯（例如上半球面的邊界是赤道那一圈，不是一個點）。","換成別的曲面時，新曲面的邊界跟原來的不一樣。","旋度第二分量的正負號算錯（$P_z-R_x$）。"],"checks":[{"ask":"$S$ 是上半球面、法向量朝上。Stokes 定理裡邊界單位圓的方向是？","options":[{"label":"從上往下看逆時針","correct":true},{"label":"從上往下看順時針","why":"右手拇指朝上，四指彎曲的方向從上看是逆時針。順時針配的是朝下的法向量。"},{"label":"哪個方向都可以","why":"兩個方向差一個負號；方向必須跟法向量配對。"}]},{"ask":"兩張曲面 $S_1$、$S_2$ 有相同的邊界 $C$，方向也一致。它們的旋度通量？","options":[{"label":"一定相等","correct":true},{"label":"一般不相等，要看曲面形狀","why":"兩者都等於 $\\oint_C\\mathbf F\\cdot d\\mathbf r$，只看邊界。這正是可以換成平坦曲面的理由。"},{"label":"只有兩者都是平面時才相等","why":"Stokes 定理對任何（可定向、分段光滑）曲面都成立，不限平面。"}]},{"ask":"$S$ 是 $xy$ 平面上的區域、$\\mathbf n=\\mathbf k$。$(\\nabla\\times\\mathbf F)\\cdot\\mathbf k$ 等於？","options":[{"label":"$Q_x-P_y$","correct":true},{"label":"$P_x+Q_y$","why":"那是平面上的散度，對應的是通量形式，不是環流。"},{"label":"$R_z$","why":"旋度的 $\\mathbf k$ 分量是 $Q_x-P_y$，跟 $R$ 無關。"}]},{"ask":"$\\mathbf F$ 在整個 $\\mathbb{R}^3$ 偏導連續，而且 $\\nabla\\times\\mathbf F=\\mathbf 0$。任一封閉曲線 $C$ 上的 $\\oint\\mathbf F\\cdot d\\mathbf r$ 是？","options":[{"label":"$0$","correct":true},{"label":"$2\\pi$","why":"$2\\pi$ 來自有洞（例如去掉 $z$ 軸）的反例。這裡定義域是整個 $\\mathbb{R}^3$，沒有洞。"},{"label":"無法判斷","why":"用 Stokes：環流 $={}$ 任一張以 $C$ 為邊界的曲面上旋度的通量 $=0$。"}]}],"practice":[{"id":"vc-stokes-001","core":true},{"id":"vc-stokes-002","core":true},{"id":"lec-20-q4b","core":true},{"id":"vc-stokes-005","core":true},{"id":"vc-stokes-003"},{"id":"vc-stokes-006"},{"id":"vc-stokes-004","challenge":true,"note":"挑戰：三角形在平面 $x+y+z=1$ 上，先用走的順序判斷法向量是 $\\langle 1,1,1\\rangle$ 還是反方向。"}]},"divergence-theorem":{"id":"divergence-theorem","prerequisites":["divergence","flux","triple-integral"],"next":["fundamental-theorems-unified"],"related":["spherical-coordinates","stokes-theorem","green-theorem"],"objectives":["寫出散度定理與它的條件：封閉曲面、朝外法向量、$\\mathbf F$ 在整個立體上偏導連續。","把封閉曲面的通量換成散度的三重積分；對不封閉的曲面，補一個蓋子再扣掉。","解釋點源場 $\\frac{\\langle x,y,z\\rangle}{\\rho^3}$ 為什麼散度為 $0$、通量卻是 $4\\pi$。"],"concept":[{"heading":"① 直觀：小方塊的流出量加起來","body":["〈散度〉：每個小方塊的淨流出 $\\approx(\\nabla\\cdot\\mathbf F)\\times{}$ 體積。把立體 $E$ 切成小方塊，全部加起來。","相鄰兩塊共用一個面：從左塊流出的，正好流進右塊，一正一負抵消。最後只剩最外面那層表面的流出。所以：表面的總流出 $={}$ 裡面所有小源的總和。這是直觀，不是證明。"]},{"heading":"② 定理","body":["$E$ 是空間中有界的立體，邊界 $S$ 是分段光滑的封閉曲面，$S$ 取朝外的法向量；$\\mathbf F$ 的分量在一個包含 $E$（連同邊界）的開集上有連續偏導。那麼下式成立。也叫 Gauss 定理。"],"tex":["\\iint_S \\mathbf F\\cdot d\\mathbf S=\\iiint_E \\nabla\\cdot\\mathbf F\\,dV"]},{"heading":"③ 怎麼用","body":["封閉曲面的通量、而且散度很簡單（常數、或只剩多項式）：換成三重積分，通常再接〈球座標〉或柱座標。","曲面不封閉（像只有碗面、沒有底）：先補一片蓋子 $S_0$ 讓它封閉，用散度定理算總通量，再減去蓋子那片的通量（蓋子也要朝外）。","通量形式的〈Green 定理〉$\\oint\\mathbf F\\cdot\\mathbf n\\,ds=\\iint(P_x+Q_y)\\,dA$ 就是它的平面版本。"]},{"heading":"④ 條件壞掉時：點源","body":["$\\mathbf F=\\frac{\\langle x,y,z\\rangle}{\\rho^3}$（$\\rho=\\sqrt{x^2+y^2+z^2}$）在原點以外 $\\nabla\\cdot\\mathbf F=0$。但穿出任一個以原點為中心的球面，通量都是 $4\\pi$：球面上 $\\mathbf F\\cdot\\mathbf n=\\frac{1}{\\rho^2}$，乘上面積 $4\\pi\\rho^2$ 得 $4\\pi$。","這不矛盾：$\\mathbf F$ 在原點沒有定義，包含原點的立體不滿足定理的條件。所有的源都擠在原點一點上。物理上這就是 Gauss 定律：點電荷的電通量只看包住的電荷。","對不包含原點的封閉曲面，條件成立，通量是 $0$。"]}],"workedExamples":[{"title":"散度是常數","prompt":"$\\mathbf F=\\langle z,y,x\\rangle$ 穿出單位球面的通量。","steps":["$\\nabla\\cdot\\mathbf F=0+1+0=1$。","$\\mathbf F$ 處處偏導連續，單位球面封閉、朝外，條件成立。","通量 $=\\iiint_{\\text{單位球}} 1\\,dV=\\frac{4\\pi}{3}$。"],"answer":"$\\frac{4\\pi}{3}$"},{"title":"避開難算的分量","prompt":"$\\mathbf F=\\langle xy,y^2+e^{xz^2},\\sin(xy)\\rangle$，$E$ 由拋物柱面 $z=1-x^2$ 與平面 $z=0$、$y=0$、$y+z=2$ 圍成。求穿出 $E$ 表面的通量。","steps":["表面有四片，直接算要碰 $e^{xz^2}$、$\\sin(xy)$，很難。","$\\nabla\\cdot\\mathbf F=y+2y+0=3y$：$e^{xz^2}$ 不含 $y$，$\\sin(xy)$ 不含 $z$，偏微分都消失。","描述 $E$：$x$ 從 $-1$ 到 $1$，$z$ 從 $0$ 到 $1-x^2$，$y$ 從 $0$ 到 $2-z$。","$\\iiint 3y\\,dV=\\int_{-1}^{1}\\int_0^{1-x^2}\\int_0^{2-z}3y\\,dy\\,dz\\,dx=\\frac{184}{35}$。"],"answer":"$\\frac{184}{35}$"},{"title":"補蓋子","prompt":"$\\mathbf F=\\langle y,x,z\\rangle$ 朝上穿過碗面 $z=1-x^2-y^2$（$z\\ge 0$）的通量。","steps":["碗面不封閉。補上底部圓盤 $S_0$：$z=0$、$x^2+y^2\\le 1$，朝外就是朝下（$-\\mathbf k$）。","$\\nabla\\cdot\\mathbf F=1$。封閉曲面總通量 $={}$ 碗下的體積 $=\\int_0^{2\\pi}\\int_0^1(1-r^2)\\,r\\,dr\\,d\\theta=\\frac{\\pi}{2}$。","底部：$\\mathbf F\\cdot(-\\mathbf k)=-z=0$，通量 $0$。","碗面通量 $=\\frac{\\pi}{2}-0=\\frac{\\pi}{2}$。跟〈通量〉那一課直接算的結果一樣。"],"answer":"$\\frac{\\pi}{2}$"}],"pitfalls":["用在不封閉的曲面上，忘了補蓋子再扣掉。","法向量朝內卻照用，差一個負號。","立體裡有 $\\mathbf F$ 沒定義的點（像點源的原點）還照用。","補了蓋子，卻忘了蓋子的方向也要朝外。"],"checks":[{"ask":"散度定理裡封閉曲面 $S$ 的法向量要取？","options":[{"label":"朝外","correct":true},{"label":"朝內","why":"定理是「淨流出 $={}$ 內部源的總和」，所以要朝外；朝內會差一個負號。"},{"label":"朝上","why":"封閉曲面有朝上的部分也有朝下的部分（像球的下半），要一律朝外。"}]},{"ask":"$E$ 是邊長 $3$ 的正方體，$\\nabla\\cdot\\mathbf F=2$（處處）。穿出 $E$ 表面的通量是？","options":[{"label":"$54$","correct":true},{"label":"$18$","why":"用了一個面的面積 $9$。要乘的是體積 $27$。"},{"label":"$2$","why":"散度是每單位體積的淨流出，要乘上體積。"}]},{"ask":"$S$ 是上半球面（沒有底），可以直接用散度定理嗎？","options":[{"label":"不能直接用：先補上底部圓盤，算完再扣掉圓盤的通量","correct":true},{"label":"可以，直接換成半球的三重積分","why":"上半球面不封閉，它本身不是任何立體的完整邊界。"},{"label":"永遠不能用","why":"補一片蓋子就能用，這是很常見的做法。"}]},{"ask":"$\\mathbf F=\\frac{\\langle x,y,z\\rangle}{\\rho^3}$ 穿出球面 $\\rho=5$ 的通量是 $4\\pi$，可是原點以外 $\\nabla\\cdot\\mathbf F=0$。為什麼？","options":[{"label":"$\\mathbf F$ 在原點沒有定義，球體不滿足定理的條件","correct":true},{"label":"散度定理錯了","why":"定理沒錯，是條件不成立：它要求 $\\mathbf F$ 在整個立體上偏導連續。"},{"label":"其實通量應該是 0","why":"球面上 $\\mathbf F\\cdot\\mathbf n=\\frac{1}{25}$，乘面積 $100\\pi$ 確實是 $4\\pi$。"}]}],"practice":[{"id":"vc-div-001","core":true},{"id":"vc-div-004","core":true},{"id":"vc-div-003","core":true},{"id":"vc-div-002","core":true,"note":"散度 $3\\rho^2$，接球座標。"},{"id":"vc-div-007","core":true},{"id":"vc-div-005"},{"id":"lec-20-q4a"},{"id":"vc-rec-001"},{"id":"vc-div-006","challenge":true,"note":"挑戰：散度在原點以外為 $0$，答案卻不是 $0$；想清楚為什麼。"}]},"fundamental-theorems-unified":{"id":"fundamental-theorems-unified","prerequisites":["divergence-theorem","stokes-theorem","green-theorem","path-independence"],"next":["ode-intro"],"related":["ftc-part2","curl","divergence"],"objectives":["把微積分基本定理、線積分基本定理、Green、Stokes、散度定理排在一起，說出它們共同的樣子。","說出每個定理裡「邊界的方向」怎麼由區域的方向決定。","看到一個積分，判斷該用哪一個定理。"],"concept":[{"heading":"① 五個定理排在一起","body":["〈微積分基本定理 II〉：線段 $[a,b]$ 上積 $F'$，等於 $F$ 在兩個端點的差。","〈路徑無關〉：曲線上積 $\\nabla f$，等於 $f$ 在起點、終點的差。","〈Green 定理〉：平面區域上積 $Q_x-P_y$，等於邊界曲線上的環流。","〈Stokes 定理〉：曲面上積旋度的通量，等於邊界曲線上的環流。","〈散度定理〉：立體裡積散度，等於邊界曲面上的通量。"],"tex":["\\begin{aligned}\\int_a^b F'(x)\\,dx&=F(b)-F(a)\\\\\\int_C\\nabla f\\cdot d\\mathbf r&=f(B)-f(A)\\\\\\iint_D(Q_x-P_y)\\,dA&=\\oint_{\\partial D}P\\,dx+Q\\,dy\\\\\\iint_S(\\nabla\\times\\mathbf F)\\cdot d\\mathbf S&=\\oint_{\\partial S}\\mathbf F\\cdot d\\mathbf r\\\\\\iiint_E\\nabla\\cdot\\mathbf F\\,dV&=\\iint_{\\partial E}\\mathbf F\\cdot d\\mathbf S\\end{aligned}"]},{"heading":"② 共同的樣子","body":["每一行左邊：在一個區域上，積某種「導數」（$F'$、$\\nabla$、平面旋度、旋度、散度）。右邊：在那個區域的邊界上，積「原來的東西」。區域是 $k$ 維，邊界就是 $k-1$ 維：線段的邊界是兩個點，曲面的邊界是曲線，立體的邊界是曲面。","直觀理由每次都一樣：把區域切成小塊，每一小塊上「導數 $\\times$ 大小」$\\approx$ 那一小塊邊界上的量；相鄰小塊的共用邊界方向相反、互相抵消，只剩最外圍。"]},{"heading":"③ 方向就是正負號","body":["每個定理都要求邊界的方向跟區域配好：線段的終點記 $+$、起點記 $-$（所以是 $F(b)-F(a)$）；Green 的邊界逆時針（區域在左手邊）；Stokes 用右手定則跟法向量配對；散度定理取朝外。方向配錯，就差一個負號。"]},{"heading":"④ 邊界的邊界是空的","body":["封閉曲線沒有端點，封閉曲面沒有邊界曲線。這件幾何事實對應到兩個恆等式：","$\\nabla\\times(\\nabla f)=\\mathbf 0$：保守場繞封閉曲線一圈，線積分基本定理給 $0$（沒有端點），Stokes 也給 $0$。","$\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$：旋度場穿過封閉曲面，Stokes 給 $0$（沒有邊界曲線），散度定理也給 $0$。"]},{"heading":"⑤ 預告：一個公式包辦全部（給想知道的人）","body":["更進階的課程會把這五個定理寫成同一個式子：$\\int_M d\\omega=\\int_{\\partial M}\\omega$，叫做廣義 Stokes 定理。$M$ 是一個 $k$ 維的區域（線段、曲面、立體，甚至更高維），$\\partial M$ 是它帶方向的邊界。","$\\omega$ 是「可以在 $k-1$ 維物件上積分的東西」：在點上取值的函數、像 $P\\,dx+Q\\,dy$ 這種沿曲線積的式子、像通量那種沿曲面積的式子。$d$ 是一個統一的微分運算，在不同維度分別變成梯度、旋度、散度；而「邊界的邊界是空的」對應到 $d(d\\omega)=0$。","要把 $\\omega$ 與 $d$ 說清楚，需要微分形式的語言，本課程不正式講。這裡只要記得：五個定理不是五件事，是同一件事在不同維度的樣子。"],"collapsible":true}],"workedExamples":[{"title":"同一個數，三種算法","prompt":"$\\mathbf F=\\langle -y,x,0\\rangle$，$C$ 是 $xy$ 平面上的單位圓，從上往下看逆時針。分別用 (a) 線積分 (b) 平圓盤 (c) 上半球面 算 $\\oint_C\\mathbf F\\cdot d\\mathbf r$。","steps":["(a) $\\mathbf r(t)=\\langle\\cos t,\\sin t,0\\rangle$：$\\mathbf F\\cdot\\mathbf r'=\\sin^2t+\\cos^2t=1$，$\\int_0^{2\\pi}dt=2\\pi$。","$\\nabla\\times\\mathbf F=\\langle 0,0,2\\rangle$。","(b) 平圓盤、法向量朝上（右手定則）：$(\\nabla\\times\\mathbf F)\\cdot\\mathbf k=2$，乘面積 $\\pi$，得 $2\\pi$。","(c) 上半球面、法向量朝外（也就是朝上）：$\\mathbf n$ 的 $z$ 分量是 $\\cos\\varphi$，$dS=\\sin\\varphi\\,d\\varphi\\,d\\theta$。$\\int_0^{2\\pi}\\int_0^{\\pi/2}2\\cos\\varphi\\sin\\varphi\\,d\\varphi\\,d\\theta=2\\pi\\cdot2\\cdot\\frac{1}{2}=2\\pi$。","三個都是 $2\\pi$：曲面可以換，只要邊界與方向一樣。"],"answer":"$2\\pi$"},{"title":"該用哪一個？","prompt":"(a) $\\oint_C(e^x+y)\\,dx+3x\\,dy$，$C$ 是正方形 $[0,2]^2$ 的邊界，逆時針。(b) $\\int_C\\nabla(xyz)\\cdot d\\mathbf r$，$C$ 從 $(0,0,0)$ 到 $(1,2,3)$。(c) $\\langle x,y,z\\rangle$ 穿出單位球面的通量。","steps":["(a) 平面上的封閉曲線 $\\to$ Green。$Q_x-P_y=3-1=2$，乘面積 $4$ 得 $8$。（直接沿四條邊算：$e^x$ 那部分在上下兩邊抵消，結果一樣是 $8$。）","(b) 梯度場的線積分 $\\to$ 線積分基本定理。$xyz$ 在 $(1,2,3)$ 是 $6$，在原點是 $0$，答案 $6$。","(c) 封閉曲面的通量 $\\to$ 散度定理。$\\nabla\\cdot\\mathbf F=3$，乘體積 $\\frac{4\\pi}{3}$ 得 $4\\pi$。"],"answer":"(a) $8$　(b) $6$　(c) $4\\pi$"}],"pitfalls":["用了定理卻沒檢查條件：封閉嗎？方向對嗎？區域裡有沒有奇異點？","Stokes 與散度定理混用：曲線 $\\leftrightarrow$ 曲面用 Stokes，曲面 $\\leftrightarrow$ 立體用散度定理。","把「邊界的邊界是空的」誤用到不封閉的曲面上。"],"checks":[{"ask":"$S$ 是封閉曲面，$\\mathbf F$ 在 $S$ 圍住的立體上偏導連續。$\\oiint_S(\\nabla\\times\\mathbf F)\\cdot d\\mathbf S$ 是？","options":[{"label":"$0$","correct":true},{"label":"要看 $\\mathbf F$","why":"用散度定理：等於 $\\iiint\\nabla\\cdot(\\nabla\\times\\mathbf F)\\,dV$，而 $\\nabla\\cdot(\\nabla\\times\\mathbf F)$ 恆為 $0$。"},{"label":"$4\\pi$","why":"$4\\pi$ 是點源場 $\\frac{\\langle x,y,z\\rangle}{\\rho^3}$ 的通量，它不是旋度場。"}]},{"ask":"平面上封閉曲線的線積分換成二重積分，用的是？","options":[{"label":"Green 定理","correct":true},{"label":"散度定理","why":"散度定理連接的是封閉曲面與立體。"},{"label":"線積分基本定理","why":"它只適用於梯度場，而且結果是端點的差，不是二重積分。"}]},{"ask":"把微積分基本定理看成這一族的一員時，$[a,b]$ 的「邊界」是？","options":[{"label":"兩個點：$b$ 帶 $+$、$a$ 帶 $-$","correct":true},{"label":"兩個點，都帶 $+$","why":"那會得到 $F(b)+F(a)$。方向要配：終點 $+$、起點 $-$。"},{"label":"整個區間 $[a,b]$","why":"區間是區域本身，邊界是比它低一維的東西：兩個端點。"}]},{"ask":"這五個定理共同的樣子是？","options":[{"label":"區域上某種導數的積分 $={}$ 邊界上原來的東西的積分","correct":true},{"label":"封閉曲線或封閉曲面上的積分都是 0","why":"只有特定的場（梯度場、旋度場）才是 0；Green、Stokes、散度定理一般給的是非零的值。"},{"label":"只對保守場成立","why":"Green、Stokes、散度定理對一般偏導連續的場都成立，不需要保守。"}]}],"practice":[{"id":"mob-nabla-007","core":true},{"id":"vc-green-007","core":true},{"id":"vc-stokes-002","core":true},{"id":"vc-div-005","core":true},{"id":"vc-rec-001"},{"id":"vc-rec-002"},{"id":"mob-tech-013"},{"id":"mob-nabla-010"}]}});
